import PageWrapper from "@/components/PageWrapperV1"
import AttandanceForm from "./Form"
import AttandanceDetail from "./Detail"
import { useQuery } from "@umijs/max"
import { useState } from "react"
import { TableViewSearchParams } from "@/components/DataCrud/TableView"
import { AttendanceAPIService } from "./services"
import AttendanceAdvanceSearch from "./AdvanceSearch"
import { Button, message } from "antd"
import { UploadOutlined } from "@ant-design/icons"
import ExportModalForm from "./ExportModalForm"
import { downloadGenericReport } from "@/services/apiGateway"
import moment from "moment"
import { getUrlReporting } from "@/pages/ReportUrl"
import { simpleRequestActions } from "@/services/model"


export default () => {
    const requestActions = simpleRequestActions();
    const [advanceSearch, setAdvanceSearch] = useState<boolean>(false)
    const [filter, setFilter] = useState<TableViewSearchParams<any>>({});
    const [exportSate, setExportState] = useState(false);
    const { data, isFetching, refetch } = useQuery({
        queryKey: ["attendances", filter],
        queryFn: () => AttendanceAPIService.page(filter),
        refetchOnWindowFocus: false,
    });

    const onDowloadReportHandler = async (values: any) => {
        try {
            const reportName = values.reportName || "";
            await downloadGenericReport(requestActions)({
                fileName: `${reportName}-${moment().format()}.xls`,
                type: "EXCEL",
                data: {
                    reportName: reportName,
                    reportPath: getUrlReporting('hrm'),
                    data: [
                        { key: 'bu', value: values?.bu?.join(","), type: 'string' },
                        { key: 'department', value: values?.department?.join(","), type: 'string' },
                        { key: 'fromDate', value: values?.fromDate, type: 'string' },
                        { key: 'toDate', value: values?.toDate, type: 'string' },
                        { key: 'employee', value: values?.employee?.join(","), type: 'string' },
                    ],
                },
            }).then(() => {
                setExportState(false)
            });
        } catch (error: any) {
            message.error(error.message || 'Failed to generate report.');
        }
    };

    return (
        <>
            <PageWrapper
                tabRender={(item) => [
                    {
                        tabKey: "add",
                        action: "add",
                        tabLabel: "Attendance",
                        panel: () => <AttandanceForm />
                    },
                    {
                        action: "view",
                        tabKey: `view-${item?.id}`,
                        tabLabel: item?.employee ? `${item?.employee?.empNo} - ${item?.employee?.firstName + ' ' + item?.employee?.lastName}` : 'Detail',
                        panel: () => <AttandanceDetail item={item} />
                    }
                ]}
                listView={{
                    type: "Table",
                    title: "Attendances",
                    onOpenAdvanceSearch: () => setAdvanceSearch(true),
                    statuses: [
                        { option: { value: "ALL", label: "All" } },
                        { option: { value: "CHECK_IN", label: "Check In" } },
                        { option: { value: "CHECK_OUT", label: "Check Out" } }
                    ],
                    onFilter: (params, page, sort) => {
                        setFilter((p) => ({
                            criteria: {
                                ...p.criteria,
                                ...params,
                                sort
                            },
                            pagination: { page: page?.current, pageSize: page?.pageSize }
                        }))
                    },
                    onRefresh: refetch,
                    actionButtons: [
                        <Button icon={<UploadOutlined />} type="text" onClick={() => setExportState(true)}>Export</Button>
                    ],
                    props: {
                        dataSource: data?.items || [],
                        pagination: {
                            total: data?.total || 0,
                            current: (data?.page || 0) + 1,
                            pageSize: data?.pageSize || 20,
                        },
                        loading: isFetching,
                        columns: [
                            {
                                title: 'Employee ID',
                                dataIndex: ['employee', 'empNo'],
                                key: 'empNo',
                                actionProps: (item: any) => ({ type: 'view', label: item?.employee?.empNo || 'NA' })
                            },
                            {
                                title: 'Employee Name',
                                key: 'employeeName',
                                render: (_, r) => (
                                    <div style={{ lineHeight: '1.4' }}>
                                        <div>{[r.employee?.firstName, r.employee?.lastName].filter(o => o).join(' ')}</div>
                                        {r.employee?.internalName && (
                                            <div style={{ fontSize: '12px', color: '#888' }}>
                                                {r.employee?.internalName}
                                            </div>
                                        )}
                                    </div>
                                )
                            },
                            {
                                title: "Job Title",
                                render: (_, r) => {
                                    return r.employee?.job?.jobTitle;
                                }
                            },
                            {
                                title: "Function",
                                render: (_, r) => {
                                    return r.employee?.department?.name;
                                }
                            },
                            {
                                title: "Bu",
                                render: (_, r) => {
                                    return r.employee?.bu?.name;
                                }
                            },
                            {
                                title: 'Date',
                                dataIndex: 'attendanceDate',
                                key: 'attendanceDate',
                                valueType: 'date',
                            },
                            {
                                title: 'Clock In',
                                dataIndex: 'checkIn',
                                key: 'checkIn',
                                // valueType: "dateTime",
                                render: (_, r) => {
                                    return r.checkIn ? moment(r.checkIn).format('DD-MMM-YYYY HH:mm A') : '-';
                                }
                            },
                            {
                                title: 'Clock Out',
                                dataIndex: 'checkOut',
                                key: 'checkOut',
                                render: (_, r) => {
                                    return r.checkOut ? moment(r.checkOut).format('DD-MMM-YYYY HH:mm A') : '-';
                                }
                            },
                            {
                                title: "Late",
                                render: (_, r) => {
                                    if (!r.lateMinute) return '-';
                                    const h = Math.floor(r.lateMinute / 60);
                                    const m = r.lateMinute % 60;
                                    return `${h}h ${m}m`;
                                }
                            },
                            {
                                title: "Early Out",
                                render: (_, r) => {
                                    if (!r.earlyOutMinute) return '-';
                                    const h = Math.floor(r.earlyOutMinute / 60);
                                    const m = r.earlyOutMinute % 60;
                                    return `${h}h ${m}m`;
                                }
                            },
                            {
                                title: 'Work Time',
                                dataIndex: 'workMinute',
                                key: 'workMinute',
                                render: (_, r) => {
                                    if (!r.workMinute) return '-';
                                    const h = Math.floor(r.workMinute / 60);
                                    const m = r.workMinute % 60;
                                    return `${h}h ${m}m`;
                                }
                            },
                            {
                                title: 'Type',
                                dataIndex: "attendanceType",
                                key: 'attendanceType',
                            },
                            {
                                title: 'Status',
                                dataIndex: 'status',
                                key: 'status',
                            }
                        ]
                    }
                }}
            />

            <ExportModalForm
                open={exportSate}
                modalProps={{
                    onCancel: () => setExportState(false),
                    width: 500
                }}
                onFinish={async (value: any) => {
                    value && onDowloadReportHandler(value)
                }}
            />

            <AttendanceAdvanceSearch
                open={advanceSearch}
                drawerProps={{
                    onClose: () => setAdvanceSearch(false),
                    width: 500
                }}
                onFinish={async (values: any) => {
                    setFilter(p => ({
                        criteria: {
                            ...p.criteria,
                            ...values,
                            sort: { field: 'attendanceDate', order: 'descend' }
                        },
                    }));
                }}
                initialValues={filter}
            />
        </>
    )
}

