import CrudWrapper from "@/components/DataCrud/CrudWrapper"
import MainPage from "../df/MainPage"
import { HrmPaths } from ".."
import DataEntryView from "../df/DataEntryView"
import DataEntryFormView from "../df/DataEntryFormView"
import { Card } from "antd"

export default () => {
    return(
        <CrudWrapper disablePageContainer   baseURL={HrmPaths.notification} >
        {(view, id, navigate) => {
            switch (view) {
                case 'list':
                    return <MainPage />
                case 'detail':
                    return <Card>
                        <DataEntryFormView id={id} type="EDIT" onCloseTab={() => navigate?.gotToListHandler?.()}/>
                    </Card>

                // case 'detail':
                //     return <div>Main</div>
                default:
                    throw Error('Not supported')
            }
        }}
        </CrudWrapper>
    )
}

