import PageWrapper from "@/components/PageWrapperV1"
import ShiftForm from "./Form"
import { useQuery } from "@umijs/max"
import { useState } from "react"
import { TableViewSearchParams } from "@/components/DataCrud/TableView"
import ShiftAPIService from "./service"
import ShiftDetail from "./Detail"
import { Tag, Space, Button } from "antd"
import { EditOutlined, EyeOutlined, UserAddOutlined } from "@ant-design/icons"
import AssignEmployeeShiftForm from "./employee_assign/Form"
import { PageWrapperContext } from "@/components/PageWrapperV1"
import { useContext } from "react"



export default () => {
    const { onAddTab, tabRender } = useContext(PageWrapperContext);
    const [filter, setFilter] = useState<TableViewSearchParams<any>>();
    const { data, isFetching, refetch } = useQuery({
        queryKey: ["shifts", filter],
        queryFn: () => ShiftAPIService.page(filter),
        refetchOnWindowFocus: false
    })

    return (
        <>
            <PageWrapper
                tabRender={(it) => [
                    {
                        action: "add",
                        tabLabel: "New Shift",
                        panel: ({ onCloseTab }) => <ShiftForm onClose={() => {
                            refetch?.();
                            onCloseTab?.()
                        }} />
                    },
                    {
                        action: "view",
                        tabLabel: `${it?.code}-Shift Detail`,
                        panel: () => <ShiftDetail id={it?.id} />
                    },
                    {
                        action: "edit",
                        tabLabel: "Edit Shift",
                        panel: ({ onCloseTab }) => <ShiftForm id={it?.id} onClose={onCloseTab} />
                    },
                    // {
                    //     action: "assign",
                    //     tabLabel: "Assign Shift",
                    //     panel: ({ onCloseTab }) => <AssignEmployeeShiftForm visible={true} onClose={onCloseTab} />
                    // },
                ]}
                listView={{
                    title: "Shifts",
                    type: "Table",
                    onRefresh: refetch,
                    // actionButtons: [
                    //     <PageWrapperContext.Consumer key="assign">
                    //         {({ onAddTab, tabRender }) => (
                    //             <Button icon={<UserAddOutlined />} type="text"
                    //                 onClick={() => {
                    //                     const config = tabRender?.().find(t => t.action === 'assign');
                    //                     if (config) onAddTab?.({}, config, "assign");
                    //                 }}
                    //             >
                    //                 Assign Shift
                    //             </Button>
                    //         )}
                    //     </PageWrapperContext.Consumer>
                    // ],
                    props: {
                        dataSource: data?.items,
                        loading: isFetching,
                        columns: [
                            {
                                title: "Shift Code",
                                dataIndex: "code",
                                actionProps: (it) => ({
                                    label: it.code,
                                    type: "view"
                                })
                            },
                            {
                                title: "Shift Name",
                                dataIndex: "name"
                            },
                            {
                                title: "Shift Type",
                                dataIndex: "shiftType",
                                render: (val: any) => {
                                    let color = "blue";
                                    if (val === "FLEXIBLE") color = "green";
                                    if (val === "ROTATING") color = "orange";
                                    return <Tag color={color}>{val || "-"}</Tag>;
                                }
                            },
                            {
                                title: "Timing",
                                render: (_: any, record: any) => {
                                    if (!record.startTime && !record.endTime) return "-";
                                    return `${record.startTime || '--:--'} - ${record.endTime || '--:--'}`;
                                }
                            },
                            {
                                title: "Status",
                                dataIndex: "active",
                                render: (_, r) => (
                                    <Tag color={r.active ? "success" : "default"}>
                                        {r.active ? "Active" : "Inactive"}
                                    </Tag>
                                )
                            },
                            {
                                title: "Actions",
                                valueType: "option",
                                width: 100,
                                render: (_, record: any, __, action: any) => (
                                    <Space>
                                        <Button
                                            type="link"
                                            size="small"
                                            icon={<EyeOutlined />}
                                            onClick={() => action?.openTab?.("view", record)}
                                        >
                                            View
                                        </Button>
                                        <Button
                                            type="link"
                                            size="small"
                                            icon={<EditOutlined />}
                                            onClick={() => action?.openTab?.("edit", record)}
                                        >
                                            Edit
                                        </Button>
                                    </Space>
                                )
                            }
                        ]
                    }
                }}
            />
        </>
    )
}

