import PageWrapper from "@/components/PageWrapperV1"
import AssignEmployeeShiftForm from "./Form"
import { useState } from "react"
import { TableViewSearchParams } from "@/components/DataCrud/TableView"
import { useQuery } from "@tanstack/react-query"
import ShiftAssignmentAPIService from "./services"
import ShiftAssignmentDetail from "./Detail"
import dayjs from "dayjs"
import { formatTime } from "../shift/utils"
import { Button, Space, Switch, Tag } from "antd"
import { DeleteOutlined } from "@ant-design/icons"
import { RemarkModal } from "@/components/RemarkModal"
import ShiftAssignmentSearch from "./AdvanceSearch"

export default () => {

    const [filter, setFilter] = useState<TableViewSearchParams<any>>({});
    const { data, isFetching, refetch } = useQuery({
        queryKey: ["shift-assignment-page", filter],
        queryFn: () => ShiftAssignmentAPIService.page(filter),
        refetchOnWindowFocus: false,
    });

    const [remarkModalOpen, setRemarkModalOpen] = useState<{ visible: boolean, action?: string, id?: number }>({ visible: false })
    const [shiftAssignmentSearchOpen, setShiftAssignmentSearchOpen] = useState(false);

    return (
        <div>
            <PageWrapper
                tabRender={(it) => [
                    {
                        tabKey: "staff_proposal",
                        action: "add",
                        tabLabel: "Staff Proposal",
                        panel: ({ onCloseTab }) => (
                            <AssignEmployeeShiftForm
                                visible={true}
                                onClose={onCloseTab}
                                onSuccess={refetch}
                            />
                        )
                    },
                    {
                        action: "view",
                        tabKey: `view-${it?.id}`,
                        tabLabel: it?.employeeCode ? `${it.employeeCode} - Detail` : 'Detail',
                        panel: ({ onCloseTab }) => <ShiftAssignmentDetail item={it} onClose={onCloseTab} onRefresh={refetch} />
                    }
                ]}
                listView={{
                    type: "Table",
                    title: "Shift Assignments",
                    onOpenAdvanceSearch: () => setShiftAssignmentSearchOpen(true),
                    onRefresh: refetch,
                    onFilter: (params, page, sort) => {
                        setFilter((p) => ({
                            criteria: {
                                ...p.criteria,
                                ...params,
                                sort
                            },
                            pagination: { page: page?.current, pageSize: page?.pageSize }
                        }))
                    },
                    props: {
                        dataSource: data?.items,
                        loading: isFetching,
                        pagination: {
                            pageSize: data?.pageSize || 20,
                        },
                        columns: [
                            {
                                key: "employeeCode",
                                title: "Employee No",
                                dataIndex: "employeeCode",
                                sorter: true,
                                actionProps: (item: any) => ({
                                    type: "view",
                                    label: item?.employeeCode || "N/A"
                                })
                            },
                            {
                                key: "name",
                                title: "Name",
                                dataIndex: "name",
                                sorter: true,
                                render: (_text: any, record: any) => {
                                    if (record.employeeName) return record.employeeName;
                                    if (record.firstName || record.lastName) {
                                        return [record.firstName, record.lastName].filter(Boolean).join(" ");
                                    }
                                    if (record.employee) {
                                        return [record.employee.firstName, record.employee.lastName].filter(Boolean).join(" ") || record.employee.name;
                                    }
                                    return "-";
                                }
                            },
                            {
                                key: "shift",
                                title: "Shift",
                                dataIndex: "shift",
                                sorter: true,
                                render: (_text: any, record: any) => {
                                    const shiftCode = record.shift?.code || record.shiftCode;
                                    const shiftName = record.shift?.name || record.shiftName;
                                    if (shiftCode && shiftName) {
                                        return `${shiftCode} - ${shiftName}`;
                                    }
                                    return shiftName || shiftCode || "-";
                                }
                            },
                            {
                                key: "effectiveDate",
                                title: "Effective Period",
                                sorter: true,
                                render: (_text: any, record: any) => {
                                    const from = record.effectiveFrom ? dayjs(record.effectiveFrom).format("YYYY-MM-DD") : "";
                                    const to = record.effectiveTo ? dayjs(record.effectiveTo).format("YYYY-MM-DD") : "Unlimited";
                                    return from ? `${from} - ${to}` : "-";
                                }
                            },
                            {
                                key: "shiftDuration",
                                title: "Shift Timing",
                                render: (_text: any, record: any) => {
                                    const startTime = record.shift?.startTime || record.startTime;
                                    const endTime = record.shift?.endTime || record.endTime;
                                    if (startTime && endTime) {
                                        return `${formatTime(startTime)} - ${formatTime(endTime)}`;
                                    }
                                    return "-";
                                }
                            },
                            {
                                key: "created",
                                title: "Created Info",
                                dataIndex: "createdDate",
                                sorter: true,
                                render: (_text: any, record: any) => {
                                    const date = record.createdDate ? dayjs(record.createdDate).format("YYYY-MM-DD HH:mm") : "-";
                                    const by = record.createdBy || "-";
                                    return (
                                        <div>
                                            <div>{by}</div>
                                            <div style={{ fontSize: "11px", color: "#8c8c8c" }}>{date}</div>
                                        </div>
                                    );
                                }
                            },
                            {
                                title: "Action",
                                width: 100,
                                render: (_, r) => {
                                    return (
                                        <Space>
                                            <Switch
                                                size="small"
                                                checked={r.status === "Active"}
                                                onChange={(checked) => setRemarkModalOpen({
                                                    visible: true,
                                                    action: checked ? "ACTIVE" : "INACTIVE",
                                                    id: r.id
                                                })}
                                            />
                                            <Button icon={<DeleteOutlined />}
                                                onClick={() => {
                                                    setRemarkModalOpen({ visible: true, action: "REMOVE", id: r.id })
                                                }}
                                                danger type="text" />

                                        </Space>
                                    )
                                }
                            }
                        ]
                    }
                }}
            />

            <RemarkModal
                open={remarkModalOpen.visible}
                title={"Reason for Deletion"}
                onOk={async (remark) => {
                    await ShiftAssignmentAPIService.action({ ids: [remarkModalOpen.id!], remark: remark, action: remarkModalOpen.action! })
                    setRemarkModalOpen({ visible: false, id: 0, action: "" })
                    refetch()
                }}
                required
                onCancel={() => {
                    setRemarkModalOpen({ visible: false, id: 0, action: "" })
                }}
            />

            <ShiftAssignmentSearch
                open={shiftAssignmentSearchOpen}
                drawerProps={{
                    onClose: () => setShiftAssignmentSearchOpen(false)
                }}
                width={400}
                onFinish={async (values) => {
                    setFilter((prev) => {
                        return {
                            ...prev,
                            criteria: {
                                ...prev.criteria,
                                ...values
                            }
                        }
                    })
                }}
            />
        </div>
    )
}

