import { Outlet, useAccess, useNavigate, useLocation } from '@umijs/max';
import { Button, Flex, Menu, MenuProps, theme } from 'antd';
import Sider from 'antd/es/layout/Sider';
import { Content } from 'antd/es/layout/layout';
import React, { useEffect, useState } from 'react';
import {
  BankOutlined,
  DeploymentUnitOutlined,
  TeamOutlined,
  KeyOutlined,
  LeftOutlined,
  RightOutlined
} from '@ant-design/icons';

type MenuItem = Required<MenuProps>['items'][number];

const HrmSettingHub: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const access = useAccess();
  const [collapsed, setCollapsed] = useState(false);
  const {
    token: { colorBgContainer },
  } = theme.useToken();

  const items: MenuItem[] = [
    {
      label: 'HRM Settings',
      type: 'group',
      children: [
        ...(access.canAccessHodManagement ? [{
          label: 'HOD Management',
          key: 'hod-management',
          icon: <TeamOutlined />,
        }] : []),
        ...(access.canAccessBusinessUnit ? [{
          label: 'Business Unit',
          key: 'business-unit',
          icon: <BankOutlined />,
        }] : []),
        ...(access.canAccessFunction ? [{
          label: 'Function',
          key: 'function',
          icon: <DeploymentUnitOutlined />,
        }] : []),
        ...(access.canAccessSalaryKeyManagement ? [{
          label: 'Salary Encryption Key',
          key: 'salary-key',
          icon: <KeyOutlined />,
        }] : []),
      ],
    },
  ];

  // Determine selected key based on URL path
  const getSelectedKey = () => {
    if (location.pathname.includes('/hod-management')) {
      return 'hod-management';
    }
    if (location.pathname.includes('/business-unit')) {
      return 'business-unit';
    }
    if (location.pathname.includes('/function')) {
      return 'function';
    }
    if (location.pathname.includes('/salary-key')) {
      return 'salary-key';
    }
    return '';
  };

  const onClick: MenuProps['onClick'] = (e) => {
    if (e.key === 'hod-management') {
      navigate('/hrm/setting/hod-management/list');
    }
    if (e.key === 'business-unit') {
      navigate('/hrm/setting/business-unit/list');
    }
    if (e.key === 'function') {
      navigate('/hrm/setting/function/list');
    }
    if (e.key === 'salary-key') {
      navigate('/hrm/setting/salary-key');
    }
  };

  useEffect(() => {
    if (location.pathname === '/hrm/setting' || location.pathname === '/hrm/setting/') {
      const defaultPath = access.canAccessHodManagement
        ? '/hrm/setting/hod-management/list'
        : access.canAccessBusinessUnit
        ? '/hrm/setting/business-unit/list'
        : access.canAccessFunction
        ? '/hrm/setting/function/list'
        : access.canAccessSalaryKeyManagement
        ? '/hrm/setting/salary-key'
        : undefined;
      if (defaultPath) navigate(defaultPath, { replace: true });
    }
  }, [location.pathname]);

  return (
    <Flex style={{ minHeight: 'calc(100vh - 64px)', position: 'relative' }}>
      <Sider
        trigger={null}
        collapsible
        collapsed={collapsed}
        onCollapse={(value) => setCollapsed(value)}
        breakpoint="lg"
        collapsedWidth="64"
        style={{
          background: colorBgContainer,
          borderRight: '1px solid #e8e8e8',
          position: 'relative',
        }}
        width={250}
      >
        <Menu
          mode="inline"
          onClick={onClick}
          selectedKeys={[getSelectedKey()]}
          items={items}
          style={{ height: '100%', borderRight: 0 }}
        />

        {/* Custom floating toggle trigger on the border */}
        <Button
          type="text"
          shape="circle"
          size="small"
          icon={collapsed ? <RightOutlined style={{ fontSize: 10 }} /> : <LeftOutlined style={{ fontSize: 10 }} />}
          onClick={() => setCollapsed(!collapsed)}
          style={{
            position: 'absolute',
            top: 20,
            right: -12,
            zIndex: 100,
            background: colorBgContainer,
            border: '1px solid #d9d9d9',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.15)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
          }}
        />
      </Sider>
      <Content style={{ padding: '24px', flex: 1, minHeight: 280, background: '#f5f7fa' }}>
        <Outlet />
      </Content>
    </Flex>
  );
};

export default HrmSettingHub;

