import React, { useState } from 'react';
import { Button, message, Space, Popconfirm, Tooltip } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, BankOutlined } from '@ant-design/icons';
import { useQuery } from '@umijs/max';
import { simpleRequestActions } from '@/services/model';
import PageWrapper from "@/components/PageWrapperV1";
import { ModalForm, ProFormText, ProFormTextArea } from '@ant-design/pro-components';
import { BuAPI } from './service';
import type { ProColumns } from '@ant-design/pro-components';
import type { TableViewSearchParams } from '@/components/DataCrud/TableView';

const BusinessUnitPage: React.FC = () => {
