import { useState } from 'react';
import { message, Space, Tag } from 'antd';
import { KeyOutlined, HistoryOutlined } from '@ant-design/icons';
import { PageContainer, ProCard, ProForm, ProFormText, ProTable } from '@ant-design/pro-components';
import { useQuery } from '@umijs/max';
import moment from 'moment';
import { simpleRequestActions } from '@/services/model';
import { EmployeeServices } from '../../services';
import { SalaryEncryptionKeyHistoryItem } from '../../data';

export default () => {
  const [form] = ProForm.useForm<{ newKey: string; currentKey?: string }>();
  const requestActions = simpleRequestActions();
  const [pagination, setPagination] = useState({ current: 1, pageSize: 10 });

  const { data, isFetching, refetch } = useQuery({
    queryKey: ['salary-encryption-key-history', pagination],
    queryFn: () => EmployeeServices.pageSalaryEncryptionKeyHistory({ pagination }).query(requestActions),
    refetchOnWindowFocus: false,
  });

  return (
    <PageContainer title={false} breadcrumbRender={false}>
      <Space direction="vertical" size={16} style={{ width: '100%' }}>
        <ProCard
          title={<span><KeyOutlined /> Salary Encryption Key</span>}
          bordered
          size="small"
          style={{ maxWidth: 520 }}
        >
          <ProForm
            form={form}
            submitter={{ searchConfig: { submitText: 'Save Key' }, resetButtonProps: false }}
            onFinish={async (values) => {
              try {
                await EmployeeServices.setSalaryEncryptionKey({
                  newKey: values.newKey,
                  currentKey: values.currentKey,
                });
                message.success('Salary encryption key updated.');
                form.resetFields();
                refetch();
                return true;
              } catch (error: any) {
                message.error(error.message || 'Failed to update the salary encryption key.');
                return false;
              }
            }}
          >
            <ProFormText.Password
              name="newKey"
              label="New Key"
              rules={[{ required: true, message: 'Please enter the new key.' }]}
              placeholder="Enter the new salary encryption key"
              fieldProps={{ autoComplete: 'new-password' }}
            />
            <ProFormText.Password
              name="currentKey"
              label="Current Key"
              placeholder="Required only if a key has already been set"
              extra="Leave blank for first-time setup. If a key already exists, you must enter it to confirm the rotation."
              fieldProps={{ autoComplete: 'new-password' }}
            />
          </ProForm>
        </ProCard>

        <ProCard
          title={<span><HistoryOutlined /> Key Rotation History</span>}
          bordered
          size="small"
        >
          <ProTable<SalaryEncryptionKeyHistoryItem>
            rowKey="version"
            search={false}
            options={{ reload: () => refetch() }}
            loading={isFetching}
            dataSource={data?.items || []}
            pagination={{
              current: pagination.current,
              pageSize: pagination.pageSize,
              total: data?.total || 0,
              showSizeChanger: true,
              onChange: (current, pageSize) => setPagination({ current, pageSize }),
            }}
            columns={[
              { title: 'Version', dataIndex: 'version', width: 90 },
              {
                title: 'Active',
                dataIndex: 'active',
                width: 90,
                render: (_, r) => r.active ? <Tag color="green">Active</Tag> : <Tag>Inactive</Tag>,
              },
              { title: 'Created By', dataIndex: 'createdBy', render: (_, r) => r.createdBy || '-' },
              {
                title: 'Created Date',
                dataIndex: 'createdDate',
                render: (_, r) => r.createdDate ? moment(r.createdDate).format('YYYY-MM-DD HH:mm') : '-',
              },
            ]}
          />
        </ProCard>
      </Space>
    </PageContainer>
  );
};

