import React, { useState } from 'react';
import PageWrapper from '@/components/PageWrapperV1';
import { useQuery } from '@umijs/max';
import { MiniAppAPIService } from './services';
import { Typography, Tag, Button, Dropdown, message } from 'antd';
import { EllipsisOutlined } from '@ant-design/icons';
import { TableViewSearchParams } from '@/components/DataCrud/TableView';
import MiniAppForm from './Form';
import MiniAppDetail from './Detail';

const { Text } = Typography;

export default () => {

    const [filter, setFilter] = useState<TableViewSearchParams<any>>();
    const { data, isFetching, refetch } = useQuery({
        queryKey: ["miniapp_list", filter],
        queryFn: () => MiniAppAPIService.paging(filter),
        refetchOnWindowFocus: false
    });

    const handleStatusChange = async (record: any, newStatus: string, action: "CHANGE_STATUS" | "DELETE") => {
        try {
            await MiniAppAPIService.actionApp({
                id: record.id,
                action,
                status: newStatus
            });
            message.success(`Mini app status updated to ${newStatus} successfully!`);
            refetch();
        } catch (error: any) {
            message.error(error.message || 'Failed to update status');
        }
    };

    return (
        <PageWrapper
            tabRender={(it) => [
                {
                    tabLabel: "Add",
                    tabKey: "add",
                    tabIcon: "",
                    action: "add",
                    panel: (prop) => <MiniAppForm onClose={(item) => prop.onUpdateTab("view", item, undefined, prop.key)} />
                },
                {
                    tabLabel: `${it?.name}`,
                    action: "view",
                    tabKey: `${it?.id}`,
                    panel: (props) => <MiniAppDetail item={it} />
                },

            ]}
            listView={{
                type: "Table",
                onRefresh: () => refetch(),
                statuses: [
                    { option: { value: "ALL", label: "All" } },
                    { option: { value: "DRAFT", label: "Draft" } },
                    { option: { value: "ACTIVE", label: "Active" } },
                    { option: { value: "INACTIVE", label: "Inactive" } },
                    { option: { value: "ARCHIVED", label: "Archived" } },
                ],
                onFilter: (params, page, sort) => {
                    setFilter((p) => ({
                        ...p,
                        ...params
                    }))
                },
                props: {
                    dataSource: data?.items ?? [],
                    loading: isFetching,

                    columns: [
                        {
                            title: 'Mini App',
                            dataIndex: 'name',
                            actionProps: (it) => ({
                                label: it?.name || "-",
                                type: "view",

                            })
                        },
                        {
                            title: 'Version',
                            dataIndex: 'version',
                            width: 100,
                            render: (_, r) => (
                                <span style={{
                                    fontSize: '11px',
                                    fontWeight: 600,
                                    padding: '2px 6px',
                                    borderRadius: '4px',
                                    color: '#2563eb',
                                    background: '#eff6ff',
                                    display: 'inline-flex'
                                }}>
                                    {r.version}
                                </span>
                            )
                        },
                        {
                            title: 'API URL',
                            dataIndex: 'apiUrl',
                            ellipsis: true,
                            render: (_, r) => <Text type="secondary">{r.apiUrl}</Text>
                        },
                        {
                            title: 'Bundle Hash',
                            dataIndex: 'bundleHash',
                            width: 120,
                            render: (_, r) => <Text code>{r.bundleHash}</Text>
                        },
                        {
                            title: 'Status',
                            dataIndex: 'status',
                            width: 100,
                            render: (_, r) => {
                                const status = r.status || 'DRAFT';
                                let style = {
                                    color: '#475569',
                                    background: '#f1f5f9',
                                    border: '1px solid #cbd5e1'
                                }
                                if (status === 'ACTIVE') {
                                    style = {
                                        color: '#16a34a',
                                        background: '#f0fdf4',
                                        border: '1px solid #bbf7d0'
                                    }
                                } else if (status === 'INACTIVE') {
                                    style = {
                                        color: '#dc2626',
                                        background: '#fef2f2',
                                        border: '1px solid #fecaca'
                                    }
                                } else if (status === 'DRAFT') {
                                    style = {
                                        color: '#d97706',
                                        background: '#fffbeb',
                                        border: '1px solid #fef3c7'
                                    }
                                }
                                return (
                                    <span style={{
                                        fontSize: '11px',
                                        fontWeight: 600,
                                        padding: '3px 8px',
                                        borderRadius: '4px',
                                        textTransform: 'uppercase',
                                        letterSpacing: '0.03em',
                                        display: 'inline-flex',
                                        alignItems: 'center',
                                        ...style
                                    }}>
                                        {status}
                                    </span>
                                );
                            }
                        },
                        {
                            title: 'Action',
                            key: 'action',
                            align: 'center',
                            width: 50,
                            render: (_, record: any) => (
                                <Dropdown
                                    menu={{
                                        items: [
                                            { key: 'ACTIVE', label: 'Active', disabled: record.status === 'ACTIVE' },
                                            { key: 'INACTIVE', label: 'Inactive', disabled: record.status === 'INACTIVE' },
                                            { key: 'ARCHIVED', label: 'Archived', disabled: record.status === 'ARCHIVED' },
                                            { key: 'DELETE', label: 'Delete', disabled: record.status !== 'ARCHIVED', danger: true },
                                        ],
                                        onClick: ({ key }) => handleStatusChange(record, key, key === "DELETE" ? "DELETE" : "CHANGE_STATUS")
                                    }}
                                    trigger={['click']}
                                >
                                    <Button size="small" icon={<EllipsisOutlined />} type="link" />
                                </Dropdown>
                            )
                        }
                    ]
                }
            }}

        />

    );
};

