import { PMPaths } from '..';
import PMCrudPage from '../components/PMCrudPage';
import SampleCrudView from '../components/SampleCrudView';
import AssetListView from './AssetListView';

export default () => {
  return (
    <PMCrudPage baseURL={PMPaths.asset} title="Asset">
      {(view, id, navigate) => {
        switch (view) {
          case 'list':
            return (
              <AssetListView
                onDetail={(assetId) => navigate?.goToDetail?.({ id: assetId })}
                onEdit={(assetId) => navigate?.gotoEdit?.({ id: assetId })}
              />
            );
          case 'create':
          case 'detail':
          case 'edit':
            return <SampleCrudView title="Asset" view={view} id={id} navigate={navigate} />;
