                            }
                        },
                    });
                },
            }}
        />
        <AttachmentModal
            open={modals.isVisible('attachments')}
            onCancel={() => modals.hideModal('attachments')}
            actionHandlers={{
                onSaveAll: async (files) => {
                    if (state.data?.detail?.id) {
                        await actions.attachFiles(files, state.data?.detail?.id);
                    }
                    modals.hideModal('attachments');
                },
            }}
        />
    </Spin>
}

