import { useQuery } from "@tanstack/react-query";
import { useState } from "react";
import { Badge } from "antd";
import dayjs from "dayjs";
import PageWrapper from "@/components/PageWrapper";
import { AddressAPIServices } from "./services";
import DetailAddress from "./Detail";
import AddressAdvancedSearchForm from "./Advansearch";
import { TableViewSearchParams } from "@/components/DataCrud/TableView";


export default () => {
    const [filters, setFilters] = useState<TableViewSearchParams<any>>({
        criteria: { advanceSearch: { status: "all" } }
    });

    const { data, isFetching, refetch } = useQuery({
        queryKey: ["address-request-update-info", filters],
        queryFn: () => AddressAPIServices.requestUpdateInfoPage(filters).query(),
        refetchOnWindowFocus: false,
        retry: 1,
        cacheTime: 0,

    })
    const [advanceSearch, setAdvanceSearch] = useState(false)

    return (
        <>
            <PageWrapper
                tabRender={(item) => [
                    {
                        action: 'view',
                        tabKey: `view-${item?.id}`,
                        tabLabel: `${item?.address}` || 'Detail',
                        panel: (props) => <DetailAddress data={item} />
                    }
                ]}

                listView={{
                    type: 'Table',
                    statuses: [
                        { option: { value: "all", label: "All", default: true } },
                        // { option: { value: "20001", label: "Unverified" } },
                        { option: { value: "20002", label: "Pending" } },
                        { option: { value: "20003", label: "Rejected" } },
                        { option: { value: "20004", label: "Confirmed" } },
                    ],
                    onRefresh: refetch,
                    onFilter: (params, page, sort) => {

                        setFilters(pre => ({
                            ...pre.criteria,
                            criteria: {
                                searchValue: params?.searchValue,
                                advanceSearch: {
                                    ...params,
                                }
                            }
                        }))

                    },
                    onOpenAdvanceSearch: () => setAdvanceSearch(true),
                    props: {
                        loading: isFetching,
                        dataSource: data?.items,
                        pagination: {
                            total: data?.total
                        },
                        columns: [
                            {
                                title: "Address Code",
                                dataIndex: "address",
                                actionProps: (r) => ({
                                    label: r?.address,
                                    type: 'view',
                                })
                            },
                            {
                                title: "Customer Code",
                                dataIndex: ["customer", "code"],
                            },
                            {
                                title: "Customer Name",
                                dataIndex: ["customer", "name"],
                            },
                            {
                                title: "Salesperson",
                                render: (_, r) => [r?.salesperson?.code, r?.salesperson?.name].filter(p => p).join(" ")
                            },
                            {
                                title: "Date",
                                dataIndex: "logDate",
                                key: "log_date",
                                render: (text: any) => text ? dayjs(text).format('YYYY-MM-DD hh:mm A') : '-'
                            },
                            {
                                title: "Status",
                                dataIndex: 'request_update_status',
                                key: 'request_update_status',
                                render: (_, record) => {
                                    let color: any = 'default';
                                    const status = record?.verifiedStatus?.name;
                                    if (status === 'Unverified') color = 'default';
                                    if (status === 'Pending') color = 'processing';
                                    if (status === 'Confirmed') color = 'success';
                                    if (status === 'Rejected') color = 'error';
                                    return <Badge status={color} text={status} />;
                                }
                            }

                        ]
                    }
                }}
            />


            <AddressAdvancedSearchForm
                open={advanceSearch}
                drawerProps={{
                    onClose: () => setAdvanceSearch(false)
                }}
            />
        </>
    )
}

