import React, { useEffect, useRef, useState } from "react";
import PageWrapper from "@/components/PageWrapper";
import { history, useAccess, useQuery } from "@umijs/max";
import {
  SavePayLoad,
  SearchParams,
  StaffProposalAdvanceParams,
  StaffProposalDetail,
  StaffProposalFormNames,
  StaffProposalListItem,
  TotalCountSP,
} from './data.types';
import { createService } from "./services";
import { simpleRequestActions } from "@/services/model";
import {
  PlusOutlined,
  ExportOutlined,
  FilterOutlined,
  SelectOutlined,
} from "@ant-design/icons";
import { formatDateTime } from "@/pages/utils";
import StaffProposalRequestForm from "./StaffProposalRequestForm";
import Status from "@/components/Status";
import { Badge, Button, Flex, Typography } from "antd";
import type { TableViewSearchParams } from "@/components/DataCrud/TableView";
import { ActionType } from "@ant-design/pro-components";
import AdvanceSearchDrawer from '@/pages/hrm/staff-requisition/AdvanceEmployeeSearch';
import DetailProposal from "./detail";
import Form from '@/pages/process-flow/form';
import SpDataEntryView from "./SpDataEntryView";

export default function StaffProposalPage() {
  const requestActions = simpleRequestActions();
  const services = createService(requestActions);
  const access = useAccess();
  const actionRef = useRef<ActionType>();
  const [filter, setFilter] = useState<TableViewSearchParams<StaffProposalAdvanceParams>>({
    criteria: {
      advanceSearch: {
        buIds: [],
        deptIds: [],
        feedback: "ALL",
        // status: "ALL",
      },
    },
  });
  const [pendingCount, setPendingCount] = useState<TotalCountSP>();
  const [advanceSearchVisible, setAdvanceSearchVisible] = useState(false);
  const [advanceSearchParams, setAdvanceSearchParams] = useState<StaffProposalAdvanceParams>({});
  const { data, isLoading, refetch } = useQuery(
    ["fetch-paging-staff-proposal", filter],
    () => services.fetchPaging(filter),
    { refetchOnWindowFocus: false }
  );

  useEffect(() => {
    totalPendingRefresh()
  }, []);

  const totalPendingRefresh = () => {
    services.findPendingCountSP().then((res) => {
      setPendingCount(res);
    });
  }

  return (
    <>
      <PageWrapper<
        StaffProposalListItem,
        StaffProposalAdvanceParams,
        StaffProposalDetail
      //{ searchValue?: string; advanceSearch?: SearchParams | SavePayLoad }
      >
        tabRender={(item) =>
          access.canRequestHrStaffProposal
            ? [
              {
                action: "add",
                value: "new",
                // tabIcon: <PlusOutlined />,
                tabLabel: "New Form",
                panel: (props) => (
                  <StaffProposalRequestForm{...props} visisble
                    formKey={StaffProposalFormNames.processDefKey}
                    onClose={() => {
                      props?.onCloseTab?.();
                      totalPendingRefresh()
                      refetch()
                    }}
                  />
                ),
              },
              {
                action: "view",
                value: item?.formNo || item?.processInstId,
                tabLabel: item?.formNo || "Form",
                panel: (props) => (['DRAFT', 'SAVED'].some(it => it == item?.status) || !item?.formNo) ?
                  <SpDataEntryView formKey="staff_proposal_request_process" id={item?.id} {...props} visisble
                    action={item?.status || 'DRAFT'}
                    onClose={() => {
                      props?.onCloseTab?.();
                      totalPendingRefresh()
                      refetch()
                    }}
                  />
                  : <Form openInTab formKey="staff_proposal_request_process" id={item?.processInstId} />
                ,
              }
            ]
            : [
              {
                action: "view",
                value: item?.formNo,
                tabLabel: item?.formNo || "Form",
                panel: (props) => (
                  <StaffProposalRequestForm {...props} visisble
                    formKey={StaffProposalFormNames.processDefKey}
                  // id={item?.processInstId||''}
                  // type="EDIT"
                  // onCloseTab={() => props?.onCloseTab?.()}
                  />
                ),
              },
            ]
        }
        listView={{
          type: "Table",
          title: "Staff Proposal Requests",
          advanceSearchButton: (
            <Button
              onClick={() => setAdvanceSearchVisible(true)}
              icon={
                Object.values(advanceSearchParams || {}).some((v) => v !== undefined && v !== null && v !== "")
                  ? <FilterOutlined style={{ color: "red" }} />
                  : <SelectOutlined />
              }
            />
          ),
          statuses: [
            { option: { label: "All", value: "ALL", default: true } },
            {
              option: {
                label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                  Draft<Badge count={pendingCount?.draft} size="small" />
                </span>,
                value: "DRAFT"
              }
            },
            {
              option: {
                label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                  Feedback<Badge count={pendingCount?.feedbackCount?.total} size="small" />
                </span>,
                value: "SAVED"
              },
              subOptions: [
                { label: 'All', value: 'ALL', default: true },
                {
                  label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                    Pending<Badge count={pendingCount?.feedbackCount?.draft} size="small" />
                    </span>, 
                  value: "PENDING" 
                },
                {
                  label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                    In Progress<Badge count={pendingCount?.feedbackCount?.inProgress} size="small" />
                  </span>,
                  value: "IN_PROGRESS"
                },
                {
                  label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                    Completed<Badge count={pendingCount?.feedbackCount?.completed} size="small" />
                  </span>,
                  value: "COMPLETED"
                }
              ]
            },
            { option: { label: "Pending", value: "PENDING" } },
            { option: { label: "Completed", value: "COMPLETED" } },
            { option: { label: "Rejected", value: "REJECTED" } },
            { option: { label: "Canceled", value: "CANCELED" } },
          ],
          onRefresh: refetch,
          onFilter: (params) => {
            setFilter((p => ({
              ...p,
              criteria: {
                ...p.criteria,
                keyword: params?.searchValue,
                advanceSearch: {
                  ...p.criteria?.advanceSearch,
                  status: params?.status,
                  feedback: params?.subStatus,
                }
              }
            })))
          },
          props: {
            actionRef,
            dataSource: data?.items || [],
            loading: isLoading,
            pagination: {
              total: data?.total,
              current: filter.pagination?.current,
              pageSize: filter.pagination?.pageSize,
              onChange: (current, pageSize) => {
                setFilter((p) => ({
                  criteria: {
                    ...p.criteria
                  },
                  pagination: {
                    current: current,
                    pageSize: pageSize
                  }
                }))
              }
            },
            scroll: { x: "max-content" },
            bordered: true,
            columns: [
              {
                title: "#",
                width: 40, // adjust width if needed
                align: "center",
                render: (_, entity, index) => (
                  <Flex gap={3} align="center">
                    <span>{index + 1}</span>
                    <Button
                      size="small"
                      type="link"
                      icon={<ExportOutlined />}
                      onClick={() =>
                        window.open(
                          `/external/data-form/${StaffProposalFormNames.processDefKey}/${entity.processInstId}`,
                          "_blank"
                        )
                      }
                      disabled={(['DRAFT', 'SAVED'].some(it => it == entity?.status) || !entity?.formNo)}
                    />

                    {/* Form link */}
                    <a
                      onClick={() =>
                        history.push(
                          `/data-form/${StaffProposalFormNames.processDefKey}/${entity.processInstId}`
                        )
                      }
                    >
                    </a>
                  </Flex>
                ),
              },
              {
                title: "Form #",
                width: 160,
                actionProps: (item) => ({
                  type: 'view',
                  label: item.formNo,
                }),
                render: (_, entity) => (
                  <span
                    style={{ color: "#1677ff", cursor: "pointer" }}
                    onClick={() => {
                      actionRef.current?.open?.({
                        action: "view",
                        value: entity.formNo || entity.processInstId,
                        tabLabel: entity.formNo,
                      });
                    }}
                  >
                    {entity.formNo}
                  </span>
                ),
              },
              { title: "Requested By", dataIndex: "requestedBy" },
              {
                title: "Requested Date",
                render: (_, r) => formatDateTime(r.requestedDate),
              },
              { title: "Employee", dataIndex: "empName" },
              { title: "Job Title", dataIndex: "jobTitle" },
              { title: "BU", dataIndex: "bu" },
              { title: "Function", dataIndex: "department" },
              { title: "Report To", dataIndex: "reportTo" },
              {
                title: "Status",
                hideInTable: (!["SAVED"].some(it => it == filter.criteria?.advanceSearch?.status)) ? false : true,
                width: 120,
                render: (_, r) => <Status text={r.status} />,
              },
              {
                title: "Feedback Status",
                hideInTable: (["SAVED"].some(it => it == filter.criteria?.advanceSearch?.status)) ? false : true,
                width: 120,
                render: (_, r) => <Status text={r.feedbackStatus} />,
              },
            ],
          },
        }}
      />
      <AdvanceSearchDrawer
        open={advanceSearchVisible}
        onClose={() => setAdvanceSearchVisible(false)}
        onSearch={(params) => {
          setFilter((prev) =>
          ({
            criteria: {
              ...prev.criteria,
              advanceSearch: {
                ...prev.criteria?.advanceSearch,
                ...params,
              }
            }
          }))
          setAdvanceSearchParams(params);
          setAdvanceSearchVisible(false);
        }}
        onReset={() => {
          setFilter((prev) => ({
            ...prev,
            criteria: {
              ...prev.criteria,
              advanceSearch: {
                ...prev.criteria?.advanceSearch,
                buIds: [],
                depIds: [],
              },
            },
            pagination: { ...prev.pagination, current: 1 },
          }));
          setAdvanceSearchVisible(false);
        }}
      />
    </>
  );
}

