import PageWrapper from "@/components/PageWrapper";
import IOSForm from "./IOSForm";
import { useAccess, useQuery } from "@umijs/max";
import { IOSService } from "./service";
import { TableViewSearchParams } from "@/components/DataCrud/TableView";
import { useEffect, useMemo, useRef, useState } from 'react';
import { simpleRequestActions } from "@/services/model";
import AdvancSearch from "./AdvancSearch";
import { Badge, Button, Flex, message, Radio, Segmented, Space } from 'antd';
import { DiffOutlined, ExportOutlined, FileSearchOutlined, FilterOutlined, SelectOutlined, UploadOutlined } from '@ant-design/icons';
import { ActionType, LightFilter, ModalForm, ProFormSelect, ProFormTextArea } from '@ant-design/pro-components';
import Status from "@/components/Status";
import BatchSubmitDrawer from "./BatchSubmitDrawer";
import ImportFileButton from '@/components/ImportFileButton';
import { DataResponse, ImportDataItem } from '@/services/shared/data';
import UploadData from '@/pages/hrm/ios/upload-data';
import Export from "./export-data/Export";
import IOSExport from "./reports/IOSExport";
import { set } from "lodash";
import ImportIosEmpDetailModal from "./upload-data/ImportIosEmpDetailModal";


interface LightFilterProp {
    iosFlowTypeId?: string[];
    iosSettingId?: number;
}

export default () => {
    const access = useAccess();
    const requestAction = simpleRequestActions();
    const actionRef = useRef<ActionType>();
    const [filter, setFilter] = useState<TableViewSearchParams<any>>({});
    const [advanceSearchVisible, setAdvanceSearchVisible] = useState(false);  
    // const [importData, setImportData] = useState<DataResponse<ImportDataItem>>();
    const { data, isLoading, refetch } = useQuery(
        ['ios-emp-request-list', filter],
        () => IOSService.page(filter),
        {refetchOnWindowFocus: false}
    )

    const { data: fetchStatus, isLoading: isLoading2, refetch: refetch2 } = useQuery({
        queryKey: ['ipo-list'],
        queryFn: () => IOSService.fetchStatus({}).query(requestAction),
        refetchOnWindowFocus: false,

    })
    const onCloseTabIos=(cb:()=>void)=>{      
        refetch()
        refetch2()
        cb?.()
    }

    const { data: iosLookupData} = useQuery({
        queryKey: ['ios-lookupist'],
        queryFn: () => IOSService.iosLookupData().query(requestAction),
        refetchOnWindowFocus: false,

    })

    const isAdvancedFiltered = () => {
        const adv = filter.criteria?.advanceSearch;
        return (
        (adv?.buIds?.length ?? 0) > 0 ||
        (adv?.depIds?.length ?? 0) > 0 ||
        (adv?.subDepIds?.length ?? 0) > 0
        );
    };
    const advanceSearchIcon = useMemo(() => {
    return isAdvancedFiltered()
        ? <FilterOutlined style={{ color: "red" }} />
        : <SelectOutlined />;
    }, [filter.criteria?.advanceSearch]);

    const [batchSubmitState, setBatchSubmitState] = useState<{ visible?: { open: boolean, ids?: number[] } }>();
    const [confirmSubmitState, setConfirmSubmitState] = useState<{ visible?: { open: boolean, ids?: number[], action?: string,cb:()=>void } }>();
    const getActionName = (action: string) => {
        if(action=='SUBMITTED'){
            return 'Submit'
        }else if(action=='ENDORSED'){
            return 'Endorse'
        }else if(action=='APPROVED'){
            return 'Approve'
        }else if(action=='RETURN'){
            return 'Send Back'
        }else if(action=='CHANGED'){
            return 'Change'
        }else{
            return action        
        }
    }
    const  importedKey= (iosLookupData?.currentFlowType||"START")=="START"?"IMPORT_OBJECTIVE_IOS":"IMPORT_EMP_IOS_MID_YEAR_REVIEW"
    return (
        <>
         <PageWrapper
                tabRender={(item) => [
                    {
                        tabKey: item?.id?.toString(),
                        tabLabel: `${item?.empNo} - ${item?.empName}`,
                        action: "edit",
                        actionLabel: "Edit IOS",
                        panel: ({ }) => <IOSForm id={item?.id} />
                    },
                    {
                        tabKey: item?.id?.toString(),
                        tabLabel: `${item?.empNo} - ${item?.empName}`,
                        action: "view",
                        actionLabel: "Detail IOS",
                        panel: ({ onCloseTab }) => <IOSForm id={item?.id} onCancel={() => onCloseTabIos(onCloseTab)} />
                    }
                ]}
                listView={{
                    type: "Table",
                    title: "IOS Performance Review",
                    onStatusRender: <Flex gap={8}>
                        <Segmented
                            defaultValue={"ALL"}
                            style={{ overflow: 'unset !important' }}
                            onChange={(value) => {
                                setFilter((prev: any) => ({
                                    ...prev,
                                    // pagination: { ...prev.pagination, current: (prev?.criteria.status!==value)?0:prev.pagination?.current },                                    
                                    criteria: {
                                        ...prev.criteria,
                                        status: value,
                                    },
                                }));
                            }}
                            options={[
                                { value: "ALL", label: "All" },
                                {
                                    value: "PENDING", label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                                        Pending
                                        <Badge count={fetchStatus?.pending ?? 0} size="small" />
                                    </span>
                                },
                                {
                                    value: "IN_PROGRESS", label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                                        In Progress
                                        <Badge count={fetchStatus?.inProgress ?? 0} size="small" />
                                    </span>
                                },
                                { value: "COMPLETED", label: "Completed" },
                            ]}
                        />
                        {iosLookupData && <LightFilter<LightFilterProp> 
                            onValuesChange={(_, value) => {
