import { DataResponse, ImportDataItem } from '@/services/shared/data';
import UploadData from '@/pages/hrm/ios-upload/upload-data';
import { ActionType, LightFilter, ProFormSelect } from '@ant-design/pro-components';
import { TableViewSearchParams } from '@/components/DataCrud/TableView';
import AdvanceSearchDrawer from '@/pages/hrm/ios-upload/AdvanceSearchEmpIOS';
import moment from 'moment';
import UpdateIosEmpInfo from '@/pages/hrm/ios-upload/upload-data/UdateIosEmpInfo';
import LaunchIOSDrawer from './components/LaunchIOSDrawer';
import IOSMasterDataExport from '../ios-upload/reports/IOSMasterDataExport';
import { IOSService } from '../ios/service';
import { simpleRequestActions } from '@/services/model';

interface LightFilterProp {
    iosFlowTypeId?: string[];
    iosSettingId?: number;
}

const Index = () => {
  const access = useAccess();
  const requestAction = simpleRequestActions();
  const [importData, setImportData] = useState<DataResponse<ImportDataItem>>();
  const [importDataIosInfo, setImportDataIosInfo] = useState<DataResponse<ImportDataItem>>();
  const [importedKey, setImportedKey] = useState<string>('IMPORT_EMPLOYEE_IPO');
  const services = EmpISOServiceAPI();
  const actionRef = useRef<ActionType>();
  const [filter, setFilter] = useState<TableViewSearchParams<IOSEmployeeSearchParams>>({
    criteria: {
      advanceSearch: {
        searchValue: undefined,
        buIds: [],
        depIds: [],
        status: "ALL",
      },
      // pagination: { current: 1, pageSize: 20 },
    },
  })
  const { data, isLoading, refetch } = useQuery(
    ["fetch_ios_emp_master_page", filter],
    () => services.ListAll(filter),
    { refetchOnWindowFocus: false }
  );
  const { data: iosLookupData} = useQuery({
      queryKey: ['ios-lookupist'],
      queryFn: () => IOSService.iosLookupData().query(requestAction),
      refetchOnWindowFocus: false,

  })
  const [advanceSearchVisible, setAdvanceSearchVisible] = useState(false);
  const [batchSubmitState, setBatchSubmitState] = useState<{ visible?: { open: boolean, ids?: number[] } }>();
  const isAdvancedFiltered = () => {
    const adv = filter.criteria?.advanceSearch;
    return (
      (adv?.buIds?.length ?? 0) > 0 ||
      (adv?.depIds?.length ?? 0) > 0 ||
      (adv?.subDepIds?.length ?? 0) > 0
    );
  };
  const advanceSearchIcon = useMemo(() => {
    return isAdvancedFiltered()
      ? <FilterOutlined style={{ color: "red" }} />
      : <SelectOutlined />;
  }, [filter.criteria?.advanceSearch]);
  const handleDelete = async (record: EmpISOData) => {
    Modal.confirm({
      title: "Delete Confirmation",
      icon: <ExclamationCircleOutlined />,
      content: "Are you sure you want to delete this Employee IOS?",
      okText: "Yes",
      okType: "danger",
      cancelText: "Cancel",
      onOk: async () => {
        try {
          const res = await services.DeleteEmployeeIOS(record.id);
          if(res.message==='ok' && res.id || 0 >0 ) {
            message.success("Deleted successfully.")
          refetch();
          }
        } catch (err: any) {
          Modal.error({ title: "Delete failed", content: String(err.message) });
        }
      },
    });
  };
  const batchLaunchIOS = async (data:any, cb:()=>void) => {
    var msg = 'Are you sure you want to launch the selected Employee IOS Form(s)?'
    if(data.action=='MID') {
      msg= 'Are you sure you want to launch the selected Employee Mid-Year Review Form(s)?'
    }else if(data.action=='END') {
      msg= 'Are you sure you want to launch the selected Employee End-Year Review Form(s)?'
    }
    if(data?.ids==undefined || data?.ids==null || data.ids.length==0){
      message.warning("Please seletet Emyployee IOS Form(s).")
      return
    }
    Modal.confirm({
      title: "Launch IOS",
      icon: <ExclamationCircleOutlined />,
      content: msg,
      okText: "Yes",
      // okType: "danger",
      cancelText: "Cancel",
      onOk: async () => {
        try {
          await services.batchLaunchIOSRequest(data);
          message.success("Launch successfully.")
          cb?.()
        } catch (err: any) {
          Modal.error({ title: "Launch Employee IOS  failed", content: String(err.message) });
        }
      },
    });
  }
  return (
    <>
      <PageWrapper<EmpISOData, IOSEmployeeSearchParams, undefined>
        tabRender={(item) => [
          {
            action: 'view',
            value: item?.empNo,
            tabLabel: `${item?.empNo} - ${item?.empName}`,
            // panel: () => (
            //   <Profile
            //     id={item?.empNo}
            //   />
            // ),
          },
        ]}
        listView={{
          type: "Table",
          title: "IOS Employee Profile",
          onStatusRender: <Flex gap={8}>
            {iosLookupData &&<LightFilter<LightFilterProp>
                onValuesChange={(_, values) => {
                    setFilter((prev) => ({
                        ...prev,
                        criteria: {
                            ...prev.criteria,
                            ..._,
                        },
                    }));

                }}
            >
                <ProFormSelect style={{ width: '100%' }} allowClear={false}
                    fieldProps={{ defaultValue: iosLookupData?.currentIosSetting?.id }}
                    initialValue ={2026}
                    rules={[{ required: false }]} name={"iosSettingId"} label="Year"
                    options={iosLookupData?.iosSettingList?.map(it => ({ label: it.name, value: it.id }))}
                />
            </LightFilter>}
          </Flex>,
          advanceSearchButton: (
            <Button
              onClick={() => setAdvanceSearchVisible(true)}
              icon={advanceSearchIcon}
            />
          ),
          actionButtons: [
            <Space key="import-with-filter" align="center">
                <Button icon={<SelectOutlined />} type="link" onClick={() => setBatchSubmitState({ visible: { open: true, ids: [] } })}>Launch IOS</Button>
                {/* <ImportFileButton<ImportDataItem>
                  importedKey="IMPORT_EMP_IOS_INFO"
                  tootltip='Update Emp IOS Info'
                  label='Import IOS Info'
                  onDataResponse={data => {
                    setImportDataIosInfo(data)
                  }}
                  key={"IMPORT_EMP_IOS_INFO_LIST"}
                  onHandleChange={(status) => {
                    if (status === 'done') {
                      message.info('Data uploaded.');
                    }
                  }}
                />                    
                <ImportFileButton<ImportDataItem>
                  importedKey="IMPORT_EMP_IOS_PROCESS"
                  tootltip='Update LM Process Flow'
                  label='Import LM Process'
                  onDataResponse={data => {
                    setImportedKey('IMPORT_EMP_IOS_PROCESS')
                    setImportData(data)
                  }}
                  key={"IMPORT_EMP_IOS_PROCESS_LIST"}
                  onHandleChange={(status) => {
                    if (status === 'done') {
                      message.info('Data uploaded.');
                    }
                  }}
                />  */}
                <ImportFileButton<ImportDataItem>
                  importedKey="IMPORT_EMPLOYEE_IPO"
                  onDataResponse={data => {
                    setImportedKey('IMPORT_EMPLOYEE_IPO')
                    setImportData(data)
                  }}
                  key={"IMPORT_EMP_IOS_LIST"}
                  onHandleChange={(status) => {
                    if (status === 'done') {
                      message.info('Data uploaded.');
                    }
                  }}
               />
               <Space hidden={!access.can('HRM_IOS_EMPLOYEE_MASTER','MENU_IOS_EXPORT_REPORT')}> <IOSMasterDataExport trigger={<Button type="link" icon={<ExportOutlined style={{ fontSize: '16px', color: '#08c' }} />}>Report</Button>} /></Space>  
            </Space>

          ],
          onRefresh: refetch,
          onFilter: (params: any) => {
            setFilter((p,) => ({
              ...p,
              ...filter.pagination,
              criteria: {
                ...p.criteria,
                searchValue: params?.searchValue,
                advanceSearch: {
                  ...p.criteria?.advanceSearch,
                  status: params?.status || p.criteria?.advanceSearch?.status,
                  ...params
                },
              },
            }));
          },
          props: {
            dataSource: data?.items || [],
            toolbar: {
            },
            loading: isLoading,
            rowKey: "employeeId",
            pagination: {
              total: data?.total,
              current: filter.pagination?.current,
              pageSize: filter.pagination?.pageSize,
              onChange: (current, pageSize) =>
                setFilter((p) => ({
                  ...p,
                  pagination: { current, pageSize },
                })),
            },
            columns: [
              {
                title: '#',
                width: 40,
                dataIndex: 'employeeCode',
                sorter: 'employeeCode',
                render(_, entity, index) {
                  return <Flex gap={3} align="center">
                    <span>{index + 1}</span>
                  </Flex>
                },
              },
              {
                title: 'Employee ID',
                dataIndex: 'empNo',
                sorter: 'employeeCode',
                width: 115,
              },
              { title: "Employee Name", dataIndex: "empName" , width:120},
              { title: "Company", dataIndex: "buName" },
              { title: "Location", dataIndex: "location" },
              { title: "Function", dataIndex: "deptName" },
              { title: "Sub Function", dataIndex: "subDeptName" ,width:120},
              { title: "Position", dataIndex: "jobTitle" },
              { title: "Job Level", dataIndex: "jobLevel" },
              {
                title: "Start Date",
                dataIndex: "startedDate",
                width: 99,
                render: (_, entity) =>
                  entity.startedDate
                    ? moment(entity.startedDate).format("YYYY-MM-DD")
                    : "-",
              },
              {
                title: "Probation End Date",
                dataIndex: "probationEndDate",
                width: 140,
                render: (_, entity) =>
                  entity.probationEndDate
                    ? moment(entity.probationEndDate).format("YYYY-MM-DD")
                    : "-",
              },
              { title: "LM1 ID", dataIndex: "appraiser1No" , width:80},
              { title: "LM1 Name", dataIndex: "appraiser1" ,width:120},
              { title: "LM2/FM ID", dataIndex: "appraiser2No" , width: 80},
              { title: "LM2/FM Name", dataIndex: "appraiser2" ,width:120},
              { title: "Remark", dataIndex: "remark" },
              {
                width: 50, title: "Action",
                render: (dom, r) => {
                  return (
                    <Space>
                      <Button
                        icon={<DeleteOutlined />}
                        danger
                        size="small"
                        type="link"
                        onClick={() => handleDelete(r)}   // ✅ FIXED
                      />
                    </Space>
                  );
                }
              }
            ],
          },
        }}
      />
      <UploadData importedKey={importedKey} title="Imported Review List" onCancel={() => setImportData(undefined)} open={!!importData} datasources={importData} onFinish={() => { actionRef.current?.reloadAndRest?.() }} />
      <UpdateIosEmpInfo importedKey={'IMPORT_EMP_IOS_INFO'} title="Imported Review List" onCancel={() => setImportDataIosInfo(undefined)} open={!!importDataIosInfo} datasources={importDataIosInfo} onFinish={() => { actionRef.current?.reloadAndRest?.() }} />
      <AdvanceSearchDrawer
        open={advanceSearchVisible}
        onClose={() => setAdvanceSearchVisible(false)}
        onSearch={(params) => {
          setFilter((prev) =>
            ({
              criteria:{
                ...prev.criteria,
                advanceSearch: {
                  ...prev.criteria?.advanceSearch,
                  ...params,
                }
              }
            }))
          setAdvanceSearchVisible(false);
        }}
        onReset={() => {
          setFilter((prev) => ({
            criteria: {
              ...prev.criteria,
              advanceSearch: {
                buIds: [],
                depIds: [],
                subDeptIds: []
              },
            },
            pagination: { ...prev.pagination, current: 1 },
          }));
        }}
      />
      {iosLookupData && <LaunchIOSDrawer
          currentIosSetting={iosLookupData?.currentIosSetting}
          currentFlowType={iosLookupData?.currentFlowType}
          open={batchSubmitState?.visible?.open}
          width={"calc(100vw - 100px)"}
          drawerProps={{
              onClose: () => {
                  setBatchSubmitState({ visible: undefined })
              },
          }}
          onSubmit={async (data,cb) => {
              // setConfirmSubmitState({ visible: { open: true, ids: data.ids, action: data.action } })             
              batchLaunchIOS(data,cb)

          }}
      />}
    </>
  );
};
export default Index;

