import { ActionType } from "@ant-design/pro-components";
import {  useEffect, useMemo, useRef, useState } from 'react';
import {useQuery } from '@umijs/max';
import PageWrapper from "@/components/PageWrapper";
import { FMANewStaffFormNames, NewStaffListItem, SearchParams, TotalCountRs } from "@/pages/fma/new-staff/data.types";
import { simpleRequestActions } from "@/services/model";
import { createService } from "@/pages/fma/new-staff/services";
import { TableViewSearchParams } from "@/components/DataCrud/TableView";
import { formatDateTime, toReadable } from "@/pages/utils";
import moment from "moment";
import Status from "@/components/Status";
import { Badge, Button, Flex, Tooltip } from "antd";
import { BellOutlined, ExportOutlined, FilterOutlined, PlusOutlined, SelectOutlined } from "@ant-design/icons";
import Detail from "./detail";
import NewStaffRequestForm from "./NewStaffRequestForm";
import { NewStaffService } from "./service";
import AdvanceEmployeeSearch from "@/pages/fma/new-staff/AdvanceSearchParams";
import AcknowledgeAction from "./components/AcknowledgeAction";

export default () => {
  const requestActions = simpleRequestActions();
  const srv = createService(requestActions)
  const [pendingCount, setPendingCount] = useState<TotalCountRs>();
  const [filter, setFilter] = useState<TableViewSearchParams<SearchParams>>({
    criteria: {
      advanceSearch: {
        keyword: undefined,
        buIds: [],
        depIds: [],
        // status: "ALL",
        startDate: undefined,
        endDate: undefined,
      },
    },
  });
  const [advanceSearchVisible, setAdvanceSearchVisible] = useState(false);
  const [unacknowledgedOnly, setUnacknowledgedOnly] = useState(false);
  const [prevStatus, setPrevStatus] = useState<SearchParams['status']>('ALL');
   const isAdvancedFiltered = () => {
    const adv = filter.criteria?.advanceSearch;
    return (
      (adv?.buIds?.length ?? 0) > 0 ||
      (adv?.depIds?.length ?? 0) > 0 ||
      !!adv?.startDate ||
      !!adv?.endDate
    );
  };
  const advanceSearchIcon = useMemo(() => {
    return isAdvancedFiltered()
      ? <FilterOutlined style={{ color: "red" }} />
      : <SelectOutlined />;
  }, [filter.criteria?.advanceSearch]);

  const actionRef = useRef<ActionType>();
  const { data, isLoading, refetch } = useQuery(
    ['fetch-paging-new-staff-request', filter],
    () => NewStaffService.fetchPaging(filter),
    { refetchOnWindowFocus: false }
  )
   const totalPendingRefresh = async () => {
    const rs = await NewStaffService.fetchTotalCount().query(requestActions)
      setPendingCount(rs);
  }

  useEffect(()=>{
    totalPendingRefresh()
  },[])

  const onAcknowledgeHandler = async (item: NewStaffListItem, employeeId: number) => {
    refetch();
    totalPendingRefresh();
  }

  return (
    <>
      <PageWrapper<NewStaffListItem, SearchParams, any> 
         tabRender={(item) =>[
          {
            action: 'add',
            tabLabel: "New Request",
            tabIcon: <PlusOutlined />,
            panel: (props) =>(
              <NewStaffRequestForm
                formKey=""
                visible  
                onClose={() => props?.onCloseTab?.()}
                cb={()=>{refetch()}}               
              />
            )},
          {
            action: "view",
            tabLabel: `${item?.formNo} | ${item?.ref}`,
             panel: (props)=> <Detail item={item} onAcknowledge={onAcknowledgeHandler}/>
          },
          {
            action: 'edit',
            tabLabel: `Edit Request | ${item?.formNo || 'Draft'}`,
            panel: (props) => (
              <NewStaffRequestForm
                formKey=""
                visible
                onClose={() => props?.onCloseTab?.()}
                cb={() => { refetch() }}
                draftData={item}
              />
            )
          }
        ]}
        listView={{
          type: "Table",
          title: "New Staff Support Request",
           advanceSearchButton: (
            <Button
              onClick={() => setAdvanceSearchVisible(true)}
              icon={advanceSearchIcon}
            />
          ),
          actionButtons: [
            <Badge count={pendingCount?.unacknowledged} size="small" key="unacknowledged-toggle">
              <Tooltip title="UnAcknowledge">
                <Button
                  type={unacknowledgedOnly ? 'primary' : 'default'}
                  icon={<BellOutlined />}
                  onClick={() => {
                    const next = !unacknowledgedOnly;
                    setUnacknowledgedOnly(next);
                    if (next) {
                      setPrevStatus(filter.criteria?.status || 'ALL');
                    }
                    setFilter((prev) => ({
                      ...prev,
                      criteria: {
                        ...prev.criteria,
                        status: next ? 'UNACKNOWLEDGE' : prevStatus,
                      },
                    }));
                  }}
                />
              </Tooltip>
            </Badge>
          ],
          statuses: [
            {
              option: { label: "All", value: "ALL", default: true },
            },
            {
              option: {
                 label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                  Draft<Badge count={pendingCount?.draft} size="small" />
                </span>,
                value: "DRAFT"
              }
            }, {
              option: {
                label: <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                  Pending<Badge count={pendingCount?.pending} size="small" />
                </span>,
                value: "PENDING"
              }
            },
            {
              option: {
                label: "Completed", value: "COMPLETED"
              }
            },
            {
              option: {
                label: "Rejected", value: "REJECTED"
              }
            }
          ],
          onRefresh: refetch,
          onFilter: (params, page, sort) =>{
            setUnacknowledgedOnly(false);
            setFilter((p)=>({
              ...p,
              criteria: {
                ...p.criteria,
                searchValue: params?.keyword,
                status: params?.status,
                advanceSearch: {
                  ...p.criteria?.advanceSearch,
                },
              },
              sort: sort,
              pagination: page,
            }))
          },
           props: {
            dataSource:  data?.items||[],
            actionRef: actionRef,
            loading: isLoading,
            pagination: {
                total: data?.total,
                current: filter.pagination?.current,
                pageSize: filter.pagination?.pageSize,
                onChange: (page, pageSize) =>
                    setFilter((prev) => ({
                    ...prev,
                    pagination: { ...prev.pagination, current: page, pageSize },
                })),
            },
             columns: [
              {
                title: '#',
                render(_, entity, index) {
                  return <Flex gap={5}>
                        <span >
                            { index + 1 }
                        </span>
                    {/* <Button
                      size="small"
                      type="link"
                      title="Open in new tab"
                      icon={<ExportOutlined />}
                      onClick={() => {
                        window
                          .open(
                            `/external/data-form/${FMANewStaffFormNames.processDefKey}/${entity.processInstId}`,
                          )
                          ?.focus();
                      }}
                    /> */}
                  </Flex>
                }
              },
              {
                title: "Form #",
                width: 190,
                actionProps: (item) => ({
                  type: item?.requestedStatus === 'DRAFT' ? 'edit' : 'view',
                  label:  item?.requestedStatus === 'DRAFT' ? `Edit Request | ${item?.formNo || 'Draft'}` : `${item?.formNo} | ${item?.ref}`,
                }),
                // render: (_, entity) => (
                //   <span
                //     style={{ color: '#1677ff', cursor: 'pointer' }}
                //     onClick={() => {
                //       actionRef.current?.open?.({
                //         action: 'view',
                //         value: entity, // ✅ pass full entity
                //         tabLabel: entity.formNo,
                //         key: entity.id, // optional unique key
                //       });
                //     }}
                //   >
                //     {entity.formNo}
                //   </span>
                // ),
              },
              { title: 'Requested By', sorter: 'requestedBy', dataIndex: 'requestedBy' },
              {
                title: 'Requested Date', align: 'right', sorter: 'requestedDate', render(_, entity) {
                  return formatDateTime(entity.requestedDate)
                },
              },
              { title: 'Employee ID.', dataIndex: "empNo", sorter: 'empNo' },
              { title: 'Employee Name', dataIndex: "empName", sorter: 'empName' },
              { title: 'Employee Name (KH)', dataIndex: "empLocalName" , sorter:'empLocalName'},
              { title: 'COMPANY', dataIndex: "bu", sorter: 'bu'},
              { title: 'Function', dataIndex: "department", sorter: 'dept' },
              { title: 'Job Title', dataIndex: "jobTitle", sorter: 'jobTitle' },
              // { title: 'Approval', dataIndex: 'HOD' },
              { title: "Start Date", dataIndex: "startingDate", sorter:'startingDate',
                render: (_ , entity) =>
                  entity.startingDate
                    ? moment(entity.startingDate).format("YYYY-MM-DD")
                    : "-",
              },
              { title: 'Status', width: 100, render: (_, r) => <Status text={toReadable(r.status)} /> },
              ...(unacknowledgedOnly ? [] : [
                { title: 'HPM Status', width: 100, render: (_: any, r: NewStaffListItem) => <Status text={toReadable(r.requestedStatus)} /> },
                { title: 'ICT Status', width: 100, render: (_: any, r: NewStaffListItem) => <Status text={toReadable(r.refStatus)} /> },
              ]),
              ...(unacknowledgedOnly ? [{
                title: 'Action',
                width: 120,
                render: (_: any, r: NewStaffListItem) => (
                  <AcknowledgeAction item={r} onAcknowledge={onAcknowledgeHandler} />
                ),
              }] : []),
            ]
           }
        }}   
      />
      <AdvanceEmployeeSearch
        open={advanceSearchVisible}
        onClose={() => setAdvanceSearchVisible(false)}
        onSearch={(params) => {
          setFilter((prev) => ({
            ...prev,
            criteria: {
              ...prev.criteria,
              advanceSearch: {
                ...prev.criteria?.advanceSearch,
                 buIds: params.buIds,
                depIds: params.depIds,
                startDate: params.startDate,
                endDate: params.endDate,
              },
            },
          }));
          setAdvanceSearchVisible(false);
        }}
        onReset={() => {
          setFilter((prev) => ({
            ...prev,
            criteria: {
              ...prev.criteria,
              advanceSearch: {
                ...prev.criteria?.advanceSearch,
                  buIds: [],
                  depIds: [],
                  startDate: undefined,
                  endDate: undefined,
              },
            },
            pagination: { ...prev.pagination, current: 1 },
          }));
        }}
      />
    </>
  );
}

