import { Outlet, useNavigate, useLocation } from '@umijs/max';
import { Button, Flex, Menu, MenuProps, theme } from 'antd';
import Sider from 'antd/es/layout/Sider';
import { Content } from 'antd/es/layout/layout';
import React, { useEffect, useState } from 'react';
import {
  DashboardOutlined,
  TeamOutlined,
  BarChartOutlined,
  LeftOutlined,
  RightOutlined,
} from '@ant-design/icons';

type MenuItem = Required<MenuProps>['items'][number];

const HrmDashboardHub: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [collapsed, setCollapsed] = useState(false);
  const {
    token: { colorBgContainer },
  } = theme.useToken();

  const items: MenuItem[] = [
    {
      label: 'E-Recruitment',
      type: 'group',
      children: [
        {
          label: 'Dashboard',
          key: 'overview',
          icon: <DashboardOutlined />,
        },
        {
          label: 'Recruitment Pipeline',
          key: 'recruitment',
          icon: <TeamOutlined />,
        },
        {
          label: 'Reporting',
          key: 'probation-overview',
          icon: <BarChartOutlined />,
        },
      ],
    },
  ];

  const getSelectedKey = () => {
    if (location.pathname.includes('/probation-overview')) {
      return 'probation-overview';
    }
    if (location.pathname.includes('/recruitment')) {
      return 'recruitment';
    }
    if (location.pathname.includes('/overview')) {
      return 'overview';
    }
    return '';
  };

  const onClick: MenuProps['onClick'] = (e) => {
    if (e.key === 'overview') {
      navigate('/hrm/dashboard/overview');
    }
    if (e.key === 'recruitment') {
      navigate('/hrm/dashboard/recruitment');
    }
    if (e.key === 'probation-overview') {
      navigate('/hrm/dashboard/probation-overview');
    }
  };

  useEffect(() => {
    if (location.pathname === '/hrm/dashboard' || location.pathname === '/hrm/dashboard/') {
      navigate('/hrm/dashboard/overview', { replace: true });
    }
  }, [location.pathname]);

  return (
    <Flex style={{ minHeight: 'calc(100vh - 64px)', position: 'relative' }}>
      <Sider
        trigger={null}
        collapsible
        collapsed={collapsed}
        onCollapse={(value) => setCollapsed(value)}
        breakpoint="lg"
        collapsedWidth="64"
        style={{
          background: colorBgContainer,
          borderRight: '1px solid #e8e8e8',
          position: 'relative',
        }}
        width={250}
      >
        <Menu
          mode="inline"
          onClick={onClick}
          selectedKeys={[getSelectedKey()]}
          items={items}
          style={{ height: '100%', borderRight: 0 }}
        />

        {/* Custom floating toggle trigger on the border */}
        <Button
          type="text"
          shape="circle"
          size="small"
          icon={collapsed ? <RightOutlined style={{ fontSize: 10 }} /> : <LeftOutlined style={{ fontSize: 10 }} />}
          onClick={() => setCollapsed(!collapsed)}
          style={{
            position: 'absolute',
            top: 20,
            right: -12,
            zIndex: 100,
            background: colorBgContainer,
            border: '1px solid #d9d9d9',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.15)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
          }}
        />
      </Sider>
      <Content style={{ padding: '24px', flex: 1, minHeight: 280, background: '#f5f7fa' }}>
        <Outlet />
      </Content>
    </Flex>
  );
};

export default HrmDashboardHub;

