                                    setFilter((prev) => ({
                                        criteria: {
                                            ...prev.criteria,
                                            searchValue: value,
                                        }
                                    }))
                                }}
                            />
                            <Radio.Group
                                optionType="button"
                                defaultValue={"all"}
                                onChange={(e) => {
                                    setFilter((prev) => ({
                                        criteria: {
                                            ...prev.criteria,
                                            type: e.target.value,
                                        }
                                    }))
                                }}
                                options={[
                                    { label: "All", value: "all" },
                                    { label: "PO", value: "PurchaseOrder" },
                                    { label: "Invoice", value: "Invoice" },
                                    // { label: "Lead", value: "Lead" },
                                ]}
                            />
                        </Space>
                        <Space>
                            <Button hidden={!access.can("SALE_SUPPORTER", "PO_ROLLBACK")}
                                type="link"
                                onClick={() => {
                                    setActionState({
                                        open: true,
                                        action: "PO_ROLLBACK",
                                    })
                                }}
                            >PO</Button>
                            <Button hidden={!access.can("SALE_SUPPORTER", "PO_CHANGE_ITEM")}
                                type="link"
                                onClick={() => {
                                    setActionState({
                                        open: true,
                                        action: "PO_CHANGE_ITEM",
                                    })
                                }}
                            >PO Items</Button>
                            <Button hidden={!access.can("SALE_SUPPORTER", "INVOICE_CORRECTION")}
                                type="link"
                                onClick={() => {
                                    setActionState({
                                        open: true,
                                        action: "INVOICE",
                                    })
                                }}
                            >Invoice</Button>
                            <Button
                                type="link"
                                icon={<ReloadOutlined />}
                                onClick={() => refetch()}
                            />
                        </Space>
                    </Flex>
                </Card>
            }}
        >
            <Row gutter={6} style={{ overflow: "hidden" }}>
                <Col span={10}><ProTable
                    options={false}
                    dataSource={data?.items}
                    search={false}
                    rowSelection={{
                        type: "radio",
                        selections: ["SELECT_INVERT"],
                        selectedRowKeys: [ip?.id || data?.items[0]?.id]
                    }}
                    tableAlertRender={false}
                    pagination={{
                        pageSize: data?.pageSize,
                        total: data?.total,
                        current: (data?.page || 0) + 1,
                        onChange: (page, pageSize) => {
                            setFilter((filter) => ({
                                criteria: {
                                    ...filter.criteria,
                                },
                                pagination: {
                                    page: page,
                                    pageSize: pageSize
                                },
                            }))
                        }
                    }}
                    onRow={(record) => {
                        return {
                            onClick: () => {
                                setIp(record)
                            }
                        }
                    }}
                    rowKey={"id"}
                    columns={[
                        {
                            title: "Entity Code",
                            dataIndex: "entityCode"
                            // render: (_, r) => {
                            //     switch (r.type) {
                            //         case "PurchaseOrder":
                            //             return r.entry?.purchaseOrderCode;
                            //         case "Invoice":
                            //             return r.entry?.invoiceNo;
                            //         case "Lead":
                            //             return r.entry?.leadCode;
                            //         default:
                            //             return "";
                            //     }
                            // }
                        },
                        {
                            title: "Action",
                            dataIndex: "changeType",
                            render: (_, r) => r?.changeType === "PO_ROLLBACK" ? "Update Purchase Order Into"
                                : r.changeType === "PO_CHANGE_ITEM" ? "Update Item"
                                    : r.changeType === "LEAD_TRANSFER" ? "Transfer"
                                        : "Update Invoice"
                        },
                        {
                            title: "Issue By",
                            dataIndex: "createdBy"
                        },
                    ]}
                />
                </Col>
                <Col span={14}>
                    <Card
                        size="small"
                        bodyStyle={{
                            maxHeight: '1027px',
                            overflowY: 'auto',
                            scrollbarWidth: "thin",
                            margin: 0,
                            backgroundColor: "transparent"
                        }}
                    >
                        <DetailList data={ip || data?.items?.[0]} />
                    </Card>
                </Col>
            </Row>

            <POAdjustForm
                open={
                    actionState.open &&
                    actionState.action !== "INVOICE"
                }
                onClose={async () => {
                    refetch?.()
                    setActionState({ open: false })
                }}
                actionType={actionState.action}
                modalProps={{
                    width:
                        actionState.action === "PO_ROLLBACK" ? "80%" : "60%",
                    onCancel: () => setActionState({ open: false }),
                }}
            />

            {/* Invoice Modal */}
            <InvoiceCorrectForm
                open={
                    actionState.open && actionState.action === "INVOICE"
                }
                onClose={async () => {
                    refetch?.()
                    setActionState({ open: false })
                }}
                actionType={actionState.action}
                onFinish={async () => {
                    refetch?.()
                }}
                modalProps={{
                    width: "80%",
                    onCancel: () => setActionState({ open: false }),
                }}
            />
        </PageContainer>
    )
}

