import { simpleRequestActions } from "@/services/model"
import { ActionType, PageContainer, ProTable } from "@ant-design/pro-components"
import { useEffect, useRef, useState } from "react"
import { Button, Space } from "antd"
import { SaleServiceAPI } from "@/services/sale/services"

export default () => {
    const requestActions = simpleRequestActions();
    const saleServices = SaleServiceAPI(requestActions);
    const actionRef = useRef<ActionType>();
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(false)
    const syncSOFromSAP = async () => {
        try {
            setLoading(true)
            await saleServices.syncAllSOFromSAP({});
            actionRef.current?.reload()
        } catch (error) {
            return;
        } finally {
            setLoading(false)
        }
    };
    const updateToSAP = async () => {
        try {
            setLoading(true)
            await saleServices.updateAllSAPSaleplan({ data: data });
            actionRef.current?.reload()
        } catch (error) {
            return;
        } finally {
            setLoading(false)
        }
    };



    return (
        <PageContainer
            breadcrumbRender={false}
            title="Sync SO"
            extra={
                <Space>
                    <Button onClick={() => syncSOFromSAP()}>Sync From SAP</Button>
                    <Button onClick={() => updateToSAP()}>Update to SAP</Button>
                </Space>

            }
        >
            <ProTable
                options={false}
                // dataSource={data}
                loading={loading}
                search={false}
                actionRef={actionRef}
                request={async () => {
                    setLoading(true);
                    try {
                        const result = await saleServices.listSyncSo();
                        setData(result);

                        return {
                            data: result,
                            success: true,
                        };
                    } catch (error) {
                        return {
                            data: [],
                            success: false,
                        };
                    } finally {
                        setLoading(false);
                    }
                }}
                // search={false}
