                //         onClick: () => {
                //             setIp(record)
                //         }
                //     }
                // }}
                rowKey={"id"}
                columns={[
                    {
                        title: "PO #",
                        dataIndex: "doc_entry_num"
                    },
                    {
                        title: "SO Num",
                        dataIndex: "so_no"
                    },
                    {
                        title: "Customer Code",
                        dataIndex: "customer_code"
                    },
                    {
                        title: "Shipping Addrress",
                        dataIndex: "shipping_address"
                    }
                ]}
            />
        </PageContainer>
    )
}

