import { simpleRequestActions } from '@/services/model';
import { ProCard, ProFormTextArea } from '@ant-design/pro-components';
import { Alert, message, Spin, Space, Modal, Button, Badge, Tooltip } from 'antd';
import { useParams, useLocation } from '@umijs/max';
import { useEffect, useMemo, useState } from 'react';
import { formatDATEFUll } from '../utils';
import { ProfileData } from './data';
import { EssProfileData } from "./data.ess";
import Personal from './tabitems/Personal';
import Relationship from './tabitems/Relationship';
import Emergency from './tabitems/Emergency';
import Education from './tabitems/Education';
import Languages from './tabitems/Languages';
import Training from './tabitems/Training';
import Experiences from './tabitems/Experiences';
import { ProfileServices } from './service';
import { ProfileServicesEss } from './service_ess';
import styles from './style.less';
import UserContact from './UserContact';
import IdentityCard from './IdentityCard';
import {
  EditOutlined, HistoryOutlined, ExclamationCircleOutlined, UserOutlined, PhoneOutlined, ThunderboltOutlined, ReadOutlined, TagOutlined, SisternodeOutlined, ScheduleOutlined,
  LinkOutlined, FieldTimeOutlined, UsergroupDeleteOutlined, RightOutlined, DownOutlined, EyeOutlined, PlusOutlined, SafetyCertificateOutlined
} from "@ant-design/icons";
import PersonalViewDetailModal from './modal/PersonalViewDetailModal';
import AttachmentList from './tabitems/AttachmentList';
import Message from './Message';
import Activity from './tabitems/Activity';
import { useAccess } from '@umijs/max';

type ProfileProps = {
  id?: number;
  is_admin?: number;
};

type ProfileTabLike = {
  contactInformation?: number;
  personalInformation?: number;
  familyMember?: number;
  emergencyContact?: number;
  education?: number;
  languages?: number;
  training?: number;
  workExperiences?: number;
};

// Sections tracked for the "profile completeness" progress summary.
// Attachment Files / Activity are informational only and aren't counted.
const TRACKED_SECTIONS: { key: string; label: string; tabField: keyof ProfileTabLike }[] = [
  { key: 'personal', label: 'Personal Information', tabField: 'personalInformation' },
  { key: 'contact', label: 'Contact Information', tabField: 'contactInformation' },
  { key: 'relationship', label: 'Family Member', tabField: 'familyMember' },
  { key: 'emergency', label: 'Emergency Contact', tabField: 'emergencyContact' },
  { key: 'education', label: 'Education', tabField: 'education' },
  { key: 'language', label: 'Languages', tabField: 'languages' },
  { key: 'training', label: 'Training/Certification', tabField: 'training' },
  { key: 'experience', label: 'Work Experiences', tabField: 'workExperiences' },
];

const SECTION_ICONS: Record<string, React.ReactNode> = {
  contact: <PhoneOutlined />,
  personal: <UserOutlined />,
  relationship: <UsergroupDeleteOutlined />,
  emergency: <ThunderboltOutlined />,
  education: <ScheduleOutlined />,
  language: <TagOutlined />,
  training: <ReadOutlined />,
  experience: <SisternodeOutlined />,
  attachmentfiles: <LinkOutlined />,
  activity: <FieldTimeOutlined />,
};

function isSectionComplete(profileTab: ProfileTabLike | undefined, field: keyof ProfileTabLike) {
  if (!profileTab) return true; // unknown state -> don't flag as incomplete
  const val = profileTab[field];
  return val == null || val === 0;
}

function Profile(props: ProfileProps) {
  const params = useParams();
  const { is_admin, id } = params;

  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);

  // ✅ Add prop override
  const _id = props.id ?? id ?? queryParams.get('id') ?? 0;
  const _is_admin = props.is_admin ?? is_admin ?? queryParams.get('is_admin') ?? 0;

  const requestActions = simpleRequestActions();

  var _valueText = "";

  const [profile, setProfile] = useState<ProfileData>();
  const [step, setStep] = useState(1);
  const [personalActions, setPersonalActions] = useState<{ canEdit: boolean; editDisabled: boolean; onViewPending: () => void; onEdit: () => void }>();
  const [contactActions, setContactActions] = useState<{ canAdd: boolean; addDisabled: boolean; onAdd: () => void }>();
  const [relationshipActions, setRelationshipActions] = useState<{ canAdd: boolean; addDisabled: boolean; onAdd: () => void; canViewEdit: boolean; onViewEdit: () => void }>();
  const [emergencyActions, setEmergencyActions] = useState<{ canAdd: boolean; addDisabled: boolean; onAdd: () => void; canViewEdit: boolean; onViewEdit: () => void }>();
  const [educationActions, setEducationActions] = useState<{ canAdd: boolean; addDisabled: boolean; onAdd: () => void; canViewEdit: boolean; onViewEdit: () => void }>();
  const [languageActions, setLanguageActions] = useState<{ canAdd: boolean; addDisabled: boolean; onAdd: () => void; canViewEdit: boolean; onViewEdit: () => void }>();
  const [experienceActions, setExperienceActions] = useState<{ canAdd: boolean; addDisabled: boolean; onAdd: () => void; canViewEdit: boolean; onViewEdit: () => void }>();
  const [trainingActions, setTrainingActions] = useState<{
    canAddTraining: boolean; addTrainingDisabled: boolean; onAddTraining: () => void; canViewTraining: boolean; onViewTraining: () => void;
    canAddCert: boolean; addCertDisabled: boolean; onAddCert: () => void; canViewCert: boolean; onViewCert: () => void;
  }>();
  const [collapsedMap, setCollapsedMap] = useState<Record<string, boolean>>({});

  const onTextChange = (val: string) => {
    _valueText = val;
  }

  const scrollToSection = (key: string) => {
    const el = document.getElementById(`profile-section-${key}`);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      const header = el.querySelector<HTMLElement>('.ant-pro-card-header, .ant-pro-card-title');
      header?.focus?.();
    }
  };

  const onStartModify = async (step_id: number, sms: string) => {
    // Validate required tabs before Submit Update
    if (step_id === 3) {
      const incompleteReasons = new Map<string, string[]>();
      const flagIncomplete = (label: string, reasons: string[]) => {
        incompleteReasons.set(label, [...(incompleteReasons.get(label) || []), ...reasons]);
      };

      let hasEmail = Boolean(profile?.email && profile.email.trim() !== '');
      let hasPhone = false;
      let contactList = profile?.contacts || [];
      if (profile?.id) {
        try {
          const res = await ProfileServices.listContact(profile.id).query(requestActions);
          if (res && Array.isArray(res)) {
            contactList = res;
          }
        } catch (err) {
          console.error('Check contacts failed:', err);
        }
      }
      for (const c of contactList) {
        const typeName = c.type?.name?.toLowerCase() || '';
        if (typeName.includes('email') && c.value && c.value.trim() !== '') {
          hasEmail = true;
        }
        if (
          (typeName.includes('personal phone') ||
            typeName.includes('business phone') ||
            typeName.includes('telegram') ||
            typeName.includes('phone')) &&
          c.value &&
          c.value.trim() !== ''
        ) {
          hasPhone = true;
        }
      }

      const missingContacts: string[] = [];
      if (!hasEmail) missingContacts.push('At least 1 Email is required');
      if (!hasPhone) missingContacts.push('At least 1 Phone (Personal Phone, Business Phone, or Telegram) is required');
      if (missingContacts.length > 0) {
        flagIncomplete('Contact Information', missingContacts);
      }

      const missingPersonalInfo: string[] = [];
      const p = profile?.profile_draft || profile?.profile || ({} as any);
      if (!p.dateBirth || String(p.dateBirth).trim() === '') {
        missingPersonalInfo.push('Date of Birth is required');
      }
      if ((!p.religionId || Number(p.religionId) <= 0) && (!p.religionName || String(p.religionName).trim() === '')) {
        missingPersonalInfo.push('Religion is required');
      }
      const hasValidNationalId = Boolean(
        p.nationalId && String(p.nationalId).trim() !== '' &&
        p.nationalIssuedDate && String(p.nationalIssuedDate).trim() !== '' &&
        p.nationalExpiryDate && String(p.nationalExpiryDate).trim() !== ''
      );
      const hasValidPassport = Boolean(
        p.passportNumber && String(p.passportNumber).trim() !== '' &&
        p.passportIssuedDate && String(p.passportIssuedDate).trim() !== '' &&
        p.passportExpiryDate && String(p.passportExpiryDate).trim() !== ''
      );
      if (!hasValidNationalId && !hasValidPassport) {
        missingPersonalInfo.push('Either National ID (with issued/expiry dates) OR Passport Number (with issued/expiry dates) is required');
      }
      if (!p.provincePbId || Number(p.provincePbId) <= 0 || !p.districtPbId || Number(p.districtPbId) <= 0 || !p.communePbId || Number(p.communePbId) <= 0) {
        missingPersonalInfo.push('Place of Birth (City/Province, District, Commune) is required');
      }
      if (!p.provincePaId || Number(p.provincePaId) <= 0 || !p.districtPaId || Number(p.districtPaId) <= 0 || !p.communePaId || Number(p.communePaId) <= 0 || !p.homePaNo || String(p.homePaNo).trim() === '') {
        missingPersonalInfo.push('Permanent Address (City/Province, District, Commune, House No) is required');
      }
      if (!p.provinceCrId || Number(p.provinceCrId) <= 0 || !p.districtCrId || Number(p.districtCrId) <= 0 || !p.communeCrId || Number(p.communeCrId) <= 0 || !p.homeCrNo || String(p.homeCrNo).trim() === '') {
        missingPersonalInfo.push('Current Address (City/Province, District, Commune, House No) is required');
      }
      if (missingPersonalInfo.length > 0) {
        flagIncomplete('Personal Information', missingPersonalInfo);
      }

      // Validate required sections must have at least 1 record.
      // Results are cached by key so the profileTab re-check below can reuse them
      // instead of re-querying the same list APIs.
      const sectionHasRecord = new Map<string, boolean>();
      if (profile?.id) {
        const essId = profile.ess?.id || 0;
        const requiredSections: { key: string; label: string }[] = [
          { key: 'familyMember', label: 'Family Member' },
          { key: 'emergencyContact', label: 'Emergency Contact' },
          { key: 'education', label: 'Education' },
          { key: 'languages', label: 'Languages' },
          { key: 'workExperiences', label: 'Work Experiences' },
        ];

        await Promise.all(requiredSections.map(async (section) => {
          try {
            let hasRecord = false;
            if (section.key === 'familyMember') {
              const res = await ProfileServicesEss.listRelationship(profile.id, essId).query(requestActions);
              hasRecord = (res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0;
            } else if (section.key === 'emergencyContact') {
              const res = await ProfileServicesEss.listEmergency(profile.id, essId).query(requestActions);
              hasRecord = (res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0;
            } else if (section.key === 'education') {
              const res = await ProfileServicesEss.listEducation(profile.id, essId).query(requestActions);
              hasRecord = (res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0;
            } else if (section.key === 'languages') {
              const res = await ProfileServicesEss.listLanguage(profile.id, essId).query(requestActions);
              hasRecord = (res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0;
            } else if (section.key === 'workExperiences') {
              const res = await ProfileServicesEss.listExperience(profile.id, essId).query(requestActions);
              hasRecord = (res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0;
            }
            sectionHasRecord.set(section.key, hasRecord);
            if (!hasRecord) {
              flagIncomplete(section.label, ['At least 1 record is required']);
            }
          } catch (err) {
            console.error(`Check required section ${section.key} failed:`, err);
          }
        }));
      }

      // Validate required tabs before Submit Update.
      // contactInformation/personalInformation are already fully covered above and never
      // flag anything here, so they're excluded. The 5 list-backed sections reuse the
      // result already fetched above instead of querying again; only 'training' is unique
      // to this pass and still needs its own request.
      if (profile?.profileTab) {
        const tab = profile.profileTab;
        const tabNameMap: Record<string, string> = {
          familyMember: 'Family Member',
          emergencyContact: 'Emergency Contact',
          education: 'Education',
          languages: 'Languages',
          training: 'Training/Certification',
          workExperiences: 'Work Experiences',
        };
        const unreadyKeys = Object.keys(tabNameMap).filter((key) => (tab as any)[key] !== 0 && (tab as any)[key] != null);

        if (unreadyKeys.length > 0 && profile.id) {
          const essId = profile.ess?.id || 0;
          await Promise.all(unreadyKeys.map(async (key) => {
            if (key !== 'training') {
              if (!sectionHasRecord.get(key)) {
                flagIncomplete(tabNameMap[key], ['At least 1 record is required']);
              }
              return;
            }

            let hasModifiedOrNew = false;
            try {
              const res = await ProfileServicesEss.listTraining(profile.id, essId).query(requestActions);
              if ((res?.data?.length || 0) > 0 || (res?.dataCert?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0 || (res?.oldDataCert?.length || 0) > 0 || (res?.newDataCert?.length || 0) > 0) hasModifiedOrNew = true;
            } catch (err) {
              console.error(`Check modified/new for ${key} failed:`, err);
            }

            if (!hasModifiedOrNew) {
              flagIncomplete(tabNameMap[key], ['At least 1 Training/Certification record is required']);
            }
          }));
        }
      }

      const uniqueIncompleteTabs = Array.from(incompleteReasons.keys());
      if (uniqueIncompleteTabs.length > 0) {
        const getTabIcon = (name: string) => {
          switch (name) {
            case 'Contact Information': return <PhoneOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Personal Information': return <UserOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Family Member': return <UsergroupDeleteOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Emergency Contact': return <ThunderboltOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Education': return <ScheduleOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Languages': return <TagOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Training/Certification': return <ReadOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Work Experiences': return <SisternodeOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            default: return <ExclamationCircleOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
          }
        };

        // Fallback modal — shown only when Submit Update is actually blocked.
        Modal.warning({
          title: <span style={{ fontSize: 18, fontWeight: 600, color: '#1f1f1f' }}>Cannot Submit Update</span>,
          width: 500,
          content: (
            <div style={{ marginTop: 12 }}>
              <p style={{ color: '#595959', fontSize: 14, marginBottom: 16 }}>
                Please click on any section below to open and complete all required fields:
              </p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 340, overflowY: 'auto', paddingRight: 4 }}>
                {uniqueIncompleteTabs.map((name, idx) => {
                  const tabKeyMap: Record<string, string> = {
                    'Contact Information': 'contact',
                    'Personal Information': 'personal',
                    'Family Member': 'relationship',
                    'Emergency Contact': 'emergency',
                    'Education': 'education',
                    'Languages': 'language',
                    'Training/Certification': 'training',
                    'Work Experiences': 'experience',
                  };
                  return (
                    <div
                      key={name || idx}
                      onClick={() => {
                        Modal.destroyAll();
                        const targetKey = tabKeyMap[name] || 'contact';
                        setTimeout(() => scrollToSection(targetKey), 100);
                      }}
                      style={{
                        display: 'flex',
                        flexDirection: 'column',
                        gap: 8,
                        background: '#fff2f0',
                        border: '1px solid #ffccc7',
                        borderRadius: 8,
                        padding: '10px 14px',
                        boxShadow: '0 2px 4px rgba(255, 77, 79, 0.05)',
                        transition: 'all 0.2s ease',
                        cursor: 'pointer',
                      }}
                    >
                      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                          <div
                            style={{
                              width: 34,
                              height: 34,
                              borderRadius: 8,
                              background: '#fff',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              boxShadow: '0 1px 3px rgba(0,0,0,0.06)',
                              flexShrink: 0,
                            }}
                          >
                            {getTabIcon(name)}
                          </div>
                          <span style={{ fontWeight: 600, color: '#cf1322', fontSize: 14 }}>
                            {name}
                          </span>
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                          <span
                            style={{
                              background: '#ff4d4f',
                              color: '#fff',
                              fontSize: 11,
                              fontWeight: 600,
                              padding: '2px 10px',
                              borderRadius: 12,
                              textTransform: 'uppercase',
                              letterSpacing: 0.5,
                              flexShrink: 0,
                            }}
                          >
                            Incomplete
                          </span>
                          <span
                            style={{
                              display: 'flex',
                              alignItems: 'center',
                              gap: 4,
                              color: '#1677ff',
                              fontSize: 12,
                              fontWeight: 600,
                              background: '#e6f4ff',
                              border: '1px solid #91caff',
                              padding: '2px 10px',
                              borderRadius: 12,
                              flexShrink: 0,
                            }}
                          >
                            Open Section <RightOutlined style={{ fontSize: 10 }} />
                          </span>
                        </div>
                      </div>
                      {(incompleteReasons.get(name) || []).length > 0 && (
                        <ul style={{ margin: 0, paddingLeft: 46, color: '#8c2f2f', fontSize: 12, lineHeight: 1.6 }}>
                          {(incompleteReasons.get(name) || []).map((reason, reasonIdx) => (
                            <li key={reasonIdx}>{reason}</li>
                          ))}
                        </ul>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ),
        });
        return;
      }
    }

    Modal.confirm({
      title: sms,
      content: 'Do you want to ' + sms + ' data?',
      onOk: async () => {
        try {
          if (step_id == 2) {
            await ProfileServicesEss.saveEssProfile({ ...profile?.profile, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: '', status: true })(requestActions);
          } else if (step_id == 9) {
            message.info("Save to draft...");
          } else {
            await ProfileServicesEss.saveEssProfile({ ...profile?.profile_draft, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: '', status: true })(requestActions);
          }
          initData();
        } catch (error: any) {
          message.error(error.message || 'Failed to created.');
        }
      },
    });
  }

  const onRejected = (step_id: number) => {
    Modal.confirm({
      title: 'Rejected',
      content: <div><ProFormTextArea name={"comment"} fieldProps={{ onChange: (e) => { onTextChange(e.currentTarget.value); } }} placeholder={"Entry Message"} /></div>,
      onOk: async () => {
        try {
          await ProfileServicesEss.approvalEssProfile({ ...profile?.profile_draft, id: profile?.id, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: _valueText, status: true })(requestActions);
          initData();
        } catch (error: any) {
          message.error(error.message || 'Failed to created.');
        }
      },
    });
  }

  const onStartAproval = (step_id: number) => {
    Modal.confirm({
      title: 'Approval Data',
      content: 'Do you want to start approval data?',
      onOk: async () => {
        try {
          await ProfileServicesEss.approvalEssProfile({ ...profile?.profile_draft, id: profile?.id, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: '', status: true })(requestActions);
          setStep(step_id);
          initData();
        } catch (error: any) {
          message.error(error.message || 'Failed to created.');
        }
      },
    });
  }

  const access = useAccess();

  useEffect(() => {
    initData();
  }, []);

  const initData = async () => {
    try {
      const rs = await ProfileServices.fetchProfile(Number(_id)).query(requestActions);
      if (rs?.profile_draft == null) {
        setStep(rs?.ess.stag);
      } else {
        setStep(rs?.profile_draft.step!!);
      }
      setProfile(rs);
    } catch (error: any) {
      if (error.message !== 'Profile not found') {
        message.error(error.message || 'Failed to load data.');
      }
    }
  }

  const reloadData = () => {
    initData();
  }

  const sectionContent: Record<string, React.ReactNode> = profile ? {
    contact: <UserContact profile={profile} step={step} is_admin={Number(_is_admin)} onActionsChange={setContactActions} />,
    personal: <Personal profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: () => { reloadData(); } }} onActionsChange={setPersonalActions} />,
    relationship: <Relationship profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: () => { reloadData(); } }} onActionsChange={setRelationshipActions} />,
    emergency: <Emergency profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: () => { reloadData(); } }} onActionsChange={setEmergencyActions} />,
    education: <Education profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: () => { reloadData(); } }} onActionsChange={setEducationActions} />,
    language: <Languages profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: () => { reloadData(); } }} onActionsChange={setLanguageActions} />,
    training: <Training profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: () => { reloadData(); } }} onActionsChange={setTrainingActions} />,
    experience: <Experiences profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: () => { reloadData(); } }} onActionsChange={setExperienceActions} />,
    attachmentfiles: <AttachmentList profile={profile} step={step} is_admin={Number(_is_admin)} />,
    activity: <Activity profile={profile} step={step} is_admin={Number(_is_admin)} />,
  } : {};

  const { completedCount, totalCount, firstIncompleteKey } = useMemo(() => {
    const total = TRACKED_SECTIONS.length;
    let completed = 0;
    let firstIncomplete: string | undefined;
    for (const s of TRACKED_SECTIONS) {
      const done = isSectionComplete(profile?.profileTab as ProfileTabLike, s.tabField);
      if (done) completed++;
      else if (!firstIncomplete) firstIncomplete = s.key;
    }
    return { completedCount: completed, totalCount: total, firstIncompleteKey: firstIncomplete };
  }, [profile?.profileTab]);

  const [modalViedEditVisible, setModalViewEditVisible] = useState<{ type: 'ADD'; payload: undefined } | { type: 'EDIT'; payload: EssProfileData } | { type: 'PREVIEW'; payload: EssProfileData }>();
  const hideModal = (visble?: boolean) => !visble && setModalViewEditVisible(undefined);

  const _info = "Update Period:  " + (profile?.ess.id!! <= 0 ? '' : formatDATEFUll(profile?.ess.startDate)) + "  -  " + (profile?.ess.id!! <= 0 ? '' : formatDATEFUll(profile?.ess.endDate)) + "";
  // Keyed by the real ess_open_announcement_item.step_id values (see EssProfileServiceImpl.kt) —
  // 0 isn't included: it's only ever written directly to the item, never to profile_draft.step,
  // so `step` here (sourced from profile_draft.step) never actually takes that value.
  const STAGE_INFO: Record<number, { label: string; message: string }> = {
    1: { label: 'Getting Started', message: _info },
    2: { label: 'Start Modifying', message: 'Employee starts modifying profile' },
    3: { label: 'Reviewing', message: 'Your update request is under review' },
    4: { label: 'Rejected', message: profile?.profile_draft == null ? '' : profile?.profile_draft.remark },
    5: { label: 'Re-Edit', message: profile?.profile_draft == null ? '' : profile?.profile_draft.remark },
    6: { label: 'Approval', message: 'Approval' },
    7: { label: 'Cancelled Submitted', message: 'Cancelled Submitted' },
    8: { label: 'Cancel Updated', message: 'Cancel Updated' },
  };

  const showFooterActions = profile && (step != 1 || Number(_is_admin) > 0);
  const canDraftOrSubmit = Boolean([7, 5, 2].find((element) => element == step)) && Number(_id) == 0;

  return (
    <Spin spinning={requestActions.request?.loading}>
      {profile?.ess.id!! <= 0 ? '' : profile?.ess.empClosed == 2 ? '' : profile?.ess.stag == 8 ? '' :
        profile && <Message visible={(step == 6 && Number(_id) == 0) ? true : false}
          message={STAGE_INFO[step]?.label}
          description={STAGE_INFO[step]?.message}
          opentitle={profile?.ess.description!!}
          type={[4, 5].find((element) => element == step) ? "error" : "info"}
          step={step}
          data={profile?.profile_draft}
          empId={profile.id}
          is_admin={[1, 2].find((element) => element == Number(_is_admin)) ? true : false}
          cb={{
            onStartModify: (stepId) => {
              onStartModify(stepId, 'Start Modify Data');
            },
          }}
        />
      }

      {profile && (step != 1 || Number(_is_admin) > 0) && (
        <div className={styles.profilePage}>
          {/* Identity card: avatar + key facts, always visible at the top */}
          <IdentityCard profile={profile} />

          {/* Progress summary — replaces per-tab red text with an always-visible status */}
          <div className={styles.progressBar}>
            <Badge
              status={completedCount === totalCount ? 'success' : 'warning'}
              text={
                <span className={styles.progressText}>
                  {completedCount === totalCount
                    ? 'All sections complete'
                    : `${completedCount}/${totalCount} sections complete`}
                </span>
              }
            />
          </div>

          {/* Collapsible section cards replacing the 10-tab navigation */}
          <div className={styles.sectionsGrid}>
            {TRACKED_SECTIONS.map((section) => {
              const complete = isSectionComplete(profile?.profileTab as ProfileTabLike, section.tabField);
              const shouldExpand = section.key === (firstIncompleteKey ?? 'personal');
              return (
                <div id={`profile-section-${section.key}`} key={section.key} className={styles.sectionAnchor}>
                  <ProCard
                    title={
                      <Space size={8}>
                        {(collapsedMap[section.key] ?? !shouldExpand)
                          ? <RightOutlined style={{ fontSize: 12, color: 'rgba(0,0,0,0.45)' }} />
                          : <DownOutlined style={{ fontSize: 12, color: 'rgba(0,0,0,0.45)' }} />}
                        <span>{SECTION_ICONS[section.key]} {section.label}</span>
                        {complete
                          ? <Badge status="success" text="Complete" />
                          : <Badge status="error" text="Incomplete" />}
                      </Space>
                    }
                    bordered
                    headerBordered
                    collapsible
                    collapsed={collapsedMap[section.key] ?? !shouldExpand}
                    onCollapse={(collapsed) => setCollapsedMap((m) => ({ ...m, [section.key]: collapsed }))}
                    extra={
                      section.key === 'personal' && personalActions ? (
                        <Space size={8}>
                          <Tooltip title="View Pending Changes">
                            <Button
                              size="small"
                              danger
                              type="link"
                              icon={<EyeOutlined />}
                              onClick={(e) => {
                                e.stopPropagation();
                                setCollapsedMap((m) => ({ ...m, personal: false }));
                                personalActions.onViewPending();
                              }}
                            />
                          </Tooltip>
                          {personalActions.canEdit && (
                            <Tooltip title="Edit">
                              <Button
                                size="small"
                                type="link"
                                icon={<EditOutlined />}
                                disabled={personalActions.editDisabled}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, personal: false }));
                                  personalActions.onEdit();
                                }}
                              />
                            </Tooltip>
                          )}
                        </Space>
                      ) : section.key === 'contact' && contactActions?.canAdd ? (
                        <Tooltip title="Add">
                          <Button
                            size="small"
                            type="link"
                            icon={<PlusOutlined />}
                            disabled={contactActions.addDisabled}
                            onClick={(e) => {
                              e.stopPropagation();
                              setCollapsedMap((m) => ({ ...m, contact: false }));
                              contactActions.onAdd();
                            }}
                          />
                        </Tooltip>
                      ) : section.key === 'relationship' && relationshipActions ? (
                        <Space size={8}>
                          {relationshipActions.canViewEdit && (
                            <Tooltip title="View Pending Change">
                              <Button
                                size="small"
                                danger
                                type="link"
                                icon={<EyeOutlined />}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, relationship: false }));
                                  relationshipActions.onViewEdit();
                                }}
                              />
                            </Tooltip>
                          )}
                          {relationshipActions.canAdd && (
                            <Tooltip title="Add">
                              <Button
                                size="small"
                                type="link"
                                icon={<PlusOutlined />}
                                disabled={relationshipActions.addDisabled}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, relationship: false }));
                                  relationshipActions.onAdd();
                                }}
                              />
                            </Tooltip>
                          )}
                        </Space>
                      ) : section.key === 'emergency' && emergencyActions ? (
                        <Space size={8}>
                          {emergencyActions.canViewEdit && (
                            <Tooltip title="View Pending Change">
                              <Button
                                size="small"
                                danger
                                type="link"
                                icon={<EyeOutlined />}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, emergency: false }));
                                  emergencyActions.onViewEdit();
                                }}
                              />
                            </Tooltip>
                          )}
                          {emergencyActions.canAdd && (
                            <Tooltip title="Add">
                              <Button
                                size="small"
                                type="link"
                                icon={<PlusOutlined />}
                                disabled={emergencyActions.addDisabled}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, emergency: false }));
                                  emergencyActions.onAdd();
                                }}
                              />
                            </Tooltip>
                          )}
                        </Space>
                      ) : section.key === 'education' && educationActions ? (
                        <Space size={8}>
                          {educationActions.canViewEdit && (
                            <Tooltip title="View Pending Change">
                              <Button
                                size="small"
                                danger
                                type="link"
                                icon={<EyeOutlined />}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, education: false }));
                                  educationActions.onViewEdit();
                                }}
                              />
                            </Tooltip>
                          )}
                          {educationActions.canAdd && (
                            <Tooltip title="Add">
                              <Button
                                size="small"
                                type="link"
                                icon={<PlusOutlined />}
                                disabled={educationActions.addDisabled}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, education: false }));
                                  educationActions.onAdd();
                                }}
                              />
                            </Tooltip>
                          )}
                        </Space>
                      ) : section.key === 'language' && languageActions ? (
                        <Space size={8}>
                          {languageActions.canViewEdit && (
                            <Tooltip title="View Pending Change">
                              <Button
                                size="small"
                                danger
                                type="link"
                                icon={<EyeOutlined />}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, language: false }));
                                  languageActions.onViewEdit();
                                }}
                              />
                            </Tooltip>
                          )}
                          {languageActions.canAdd && (
                            <Tooltip title="Add">
                              <Button
                                size="small"
                                type="link"
                                icon={<PlusOutlined />}
                                disabled={languageActions.addDisabled}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, language: false }));
                                  languageActions.onAdd();
                                }}
                              />
                            </Tooltip>
                          )}
                        </Space>
                      ) : section.key === 'experience' && experienceActions ? (
                        <Space size={8}>
                          {experienceActions.canViewEdit && (
                            <Tooltip title="View Pending Change">
                              <Button
                                size="small"
                                danger
                                type="link"
                                icon={<EyeOutlined />}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, experience: false }));
                                  experienceActions.onViewEdit();
                                }}
                              />
                            </Tooltip>
                          )}
                          {experienceActions.canAdd && (
                            <Tooltip title="Add">
                              <Button
                                size="small"
                                type="link"
                                icon={<PlusOutlined />}
                                disabled={experienceActions.addDisabled}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, experience: false }));
                                  experienceActions.onAdd();
                                }}
                              />
                            </Tooltip>
                          )}
                        </Space>
                      ) : section.key === 'training' && trainingActions ? (
                        <Space size={8} wrap>
                          {trainingActions.canViewTraining && (
                            <Tooltip title="View Training">
                              <Button
                                size="small"
                                danger
                                type="link"
                                icon={<ReadOutlined />}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, training: false }));
                                  trainingActions.onViewTraining();
                                }}
                              />
                            </Tooltip>
                          )}
                          {trainingActions.canViewCert && (
                            <Tooltip title="View Certification">
                              <Button
                                size="small"
                                danger
                                type="link"
                                icon={<SafetyCertificateOutlined />}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setCollapsedMap((m) => ({ ...m, training: false }));
                                  trainingActions.onViewCert();
                                }}
                              />
                            </Tooltip>
                          )}
                        </Space>
                      ) : undefined
                    }
                  >
                    {sectionContent[section.key]}
                  </ProCard>
                </div>
              );
            })}

            <div id="profile-section-attachmentfiles" className={styles.sectionAnchor}>
              <ProCard
                title={<span>{SECTION_ICONS.attachmentfiles} Attachment Files</span>}
                bordered
                headerBordered
                collapsible
                defaultCollapsed
              >
                {sectionContent.attachmentfiles}
              </ProCard>
            </div>

            <div id="profile-section-activity" className={styles.sectionAnchor}>
              <ProCard
                title={<span>{SECTION_ICONS.activity} Activity</span>}
                bordered
                headerBordered
                collapsible
                defaultCollapsed
              >
                {sectionContent.activity}
              </ProCard>
            </div>
          </div>

          {/* Sticky action bar — replaces footer buttons hidden via inline display style */}
          {showFooterActions && (
            <div className={styles.stickyActions}>
              {canDraftOrSubmit && (
                // Pass the current step through instead of the unmapped literal 9 — saving a
                // draft persists form data without advancing the workflow, so step_id shouldn't change.
                <Button style={{ background: '#E7E6E6' }} onClick={() => onStartModify(step, 'Save Draft')}>
                  <EditOutlined /> Save Draft
                </Button>
              )}
              {profile.ess.id!! > 0 && canDraftOrSubmit && (
                <Button type="primary" onClick={() => onStartModify(3, 'Submit Update')}>
                  <EditOutlined /> Submit Update
                </Button>
              )}
              {profile.ess.id!! > 0 && step == 3 && Number(_id) == 0 && (
                <Button danger onClick={() => onStartModify(7, 'Cancel Submitted')}>
                  <HistoryOutlined /> Cancel Submitted
                </Button>
              )}
              {access.canAccessHrESSApprovalProfile == true && profile.ess.id!! > 0 && step == 3 && Number(_id) > 0 && (
                <Button danger onClick={() => onRejected(4)}>
                  <EditOutlined /> Rejected
                </Button>
              )}
              {access.canAccessHrESSApprovalProfile == true && step == 3 && Number(_id) > 0 && (
                <Button type="primary" onClick={() => onStartAproval(6)}>
                  <EditOutlined /> Approval
                </Button>
              )}
            </div>
          )}
        </div>
      )}

      {!profile && <Alert message="Error" description={<div>Your profile is not yet set up , please contact ICT for support or submit by this <a href='https://forms.office.com/r/Zzw498T9Vv' target='_blank'>Link</a>.</div>} type="error" showIcon />}

      <PersonalViewDetailModal
        open={!!modalViedEditVisible?.type}
        onOpenChange={(visible) => hideModal(visible)}
        data={modalViedEditVisible?.payload}
        onFinishFailed={(error) => {
          message.error(
            <Space direction="vertical" align="start">
              {error.errorFields.map((it) => (
                <div>{it.errors.join(', ')}</div>
              ))}
            </Space>,
          );
        }}
      />
    </Spin>
  );
}

export default Profile;

