import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Avatar, Typography, Divider, Timeline, Table, Spin, Alert, Modal, message, Space, Button, Descriptions, Tabs } from 'antd';
import { EditOutlined, MailOutlined, PhoneOutlined, HistoryOutlined, ManOutlined, WomanOutlined, UserOutlined, UsergroupDeleteOutlined, ThunderboltOutlined, ScheduleOutlined, TagOutlined, ReadOutlined, SisternodeOutlined, LinkOutlined, FieldTimeOutlined, ExclamationCircleOutlined, RightOutlined } from '@ant-design/icons';
import { ProFormTextArea, PageContainer } from '@ant-design/pro-components';
import { useParams, useLocation } from '@umijs/max';
import { useAccess } from '@umijs/max';

import { simpleRequestActions } from '@/services/model';
import { formatDATEFUll } from '../utils';
import { ProfileData } from './data.d';
import { EssProfileData } from "./data.ess";
import { ProfileServices } from './service';
import { ProfileServicesEss } from './service_ess';
import Message from './Message';
import BasicInfoCard from './components/BasicInfoCard';
import UserContact from './UserContact';
import Personal from './tabitems/Personal';
import Relationship from './tabitems/Relationship';
import Emergency from './tabitems/Emergency';
import Education from './tabitems/Education';
import Languages from './tabitems/Languages';
import Training from './tabitems/Training';
import Experiences from './tabitems/Experiences';
import AttachmentList from './tabitems/AttachmentList';
import Activity from './tabitems/Activity';
import ImageProfileUploader from '@/components/ImageProfileUploader';
import PersonalViewDetailModal from './modal/PersonalViewDetailModal';

const { Title, Text } = Typography;

type ProfileProps = {
  id?: number;
  is_admin?: number;
};

export default function ProfileV2(props: ProfileProps) {
  const params = useParams();
  const { is_admin, id } = params;

  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);

  // ✅ Add prop override
  const _id = props.id ?? id ?? queryParams.get('id') ?? 0;
  const _is_admin = props.is_admin ?? is_admin ?? queryParams.get('is_admin') ?? 0;

  const requestActions = simpleRequestActions();
  const access = useAccess();

  const initialTab = queryParams.get('tab') || '1';
  const [activeTab, setActiveTab] = useState(initialTab);

  const handleTabChange = (key: string) => {
    setActiveTab(key);
    const params = new URLSearchParams(window.location.search);
    params.set('tab', key);
    window.history.replaceState({}, '', `${window.location.pathname}?${params.toString()}`);
  };
  const [profile, setProfile] = useState<ProfileData>();
  const [step, setStep] = useState(1);
  const [modalViedEditVisible, setModalViewEditVisible] = useState<{ type: 'ADD'; payload: undefined } | { type: 'EDIT'; payload: EssProfileData } | { type: 'PREVIEW'; payload: EssProfileData }>();

  var _valueText = "";

  const onTextChange = (val: string) => {
    _valueText = val;
  }

  const onStartModify = async (step_id: number, sms: string) => {
    // Validate required tabs before Submit Update
    if (step_id === 3) {
      const incompleteTabs: string[] = [];

      let hasEmail = Boolean(profile?.email && profile.email.trim() !== '');
      let hasPhone = false;
      let contactList = profile?.contacts || [];
      if (profile?.id) {
        try {
          const res = await ProfileServices.listContact(profile.id).query(requestActions);
          if (res && Array.isArray(res)) {
            contactList = res;
          }
        } catch (err) {
          console.error('Check contacts failed:', err);
        }
      }
      for (const c of contactList) {
        const typeName = c.type?.name?.toLowerCase() || '';
        if (typeName.includes('email') && c.value && c.value.trim() !== '') {
          hasEmail = true;
        }
        if (
          (typeName.includes('personal phone') ||
            typeName.includes('business phone') ||
            typeName.includes('telegram') ||
            typeName.includes('phone')) &&
          c.value &&
          c.value.trim() !== ''
        ) {
          hasPhone = true;
        }
      }

      const missingContacts: string[] = [];
      if (!hasEmail) missingContacts.push('At least 1 Email is required');
      if (!hasPhone) missingContacts.push('At least 1 Phone (Personal Phone, Business Phone, or Telegram) is required');
      if (missingContacts.length > 0) {
        incompleteTabs.push('Contact Information');
      }

      const missingPersonalInfo: string[] = [];
      const p = profile?.profile_draft || profile?.profile || ({} as any);
      if (!p.dateBirth || String(p.dateBirth).trim() === '') {
        missingPersonalInfo.push('Date of Birth is required');
      }
      if ((!p.religionId || Number(p.religionId) <= 0) && (!p.religionName || String(p.religionName).trim() === '')) {
        missingPersonalInfo.push('Religion is required');
      }
      const hasValidNationalId = Boolean(
        p.nationalId && String(p.nationalId).trim() !== '' &&
        p.nationalIssuedDate && String(p.nationalIssuedDate).trim() !== '' &&
        p.nationalExpiryDate && String(p.nationalExpiryDate).trim() !== ''
      );
      const hasValidPassport = Boolean(
        p.passportNumber && String(p.passportNumber).trim() !== '' &&
        p.passportIssuedDate && String(p.passportIssuedDate).trim() !== '' &&
        p.passportExpiryDate && String(p.passportExpiryDate).trim() !== ''
      );
      if (!hasValidNationalId && !hasValidPassport) {
        missingPersonalInfo.push('Either National ID (with issued/expiry dates) OR Passport Number (with issued/expiry dates) is required');
      }
      if (!p.provincePbId || Number(p.provincePbId) <= 0 || !p.districtPbId || Number(p.districtPbId) <= 0 || !p.communePbId || Number(p.communePbId) <= 0) {
        missingPersonalInfo.push('Place of Birth (City/Province, District, Commune) is required');
      }
      if (!p.provincePaId || Number(p.provincePaId) <= 0 || !p.districtPaId || Number(p.districtPaId) <= 0 || !p.communePaId || Number(p.communePaId) <= 0 || !p.homePaNo || String(p.homePaNo).trim() === '') {
        missingPersonalInfo.push('Permanent Address (City/Province, District, Commune, House No) is required');
      }
      if (!p.provinceCrId || Number(p.provinceCrId) <= 0 || !p.districtCrId || Number(p.districtCrId) <= 0 || !p.communeCrId || Number(p.communeCrId) <= 0 || !p.homeCrNo || String(p.homeCrNo).trim() === '') {
        missingPersonalInfo.push('Current Address (City/Province, District, Commune, House No) is required');
      }
      if (missingPersonalInfo.length > 0) {
        incompleteTabs.push('Personal Information');
      }

      // Validate required tabs before Submit Update
      if (profile?.profileTab) {
        const tab = profile.profileTab;
        const tabNameMap: Record<string, string> = {
          contactInformation: 'Contact Information',
          personalInformation: 'Personal Information',
          familyMember: 'Family Member',
          emergencyContact: 'Emergency Contact',
          education: 'Education',
          languages: 'Languages',
          training: 'Training/Certification',
          workExperiences: 'Work Experiences',
        };
        const unreadyKeys = Object.keys(tabNameMap).filter((key) => tab[key] !== 0 && tab[key] != null);

        if (unreadyKeys.length > 0 && profile.id) {
          const essId = profile.ess?.id || 0;
          for (const key of unreadyKeys) {
            let hasModifiedOrNew = false;
            try {
              if (key === 'education') {
                const res = await ProfileServicesEss.listEducation(profile.id, essId).query(requestActions);
                // Allow submit if there are: newly added records (newData), modified pre-existing records (oldData), OR any pre-existing records from before announcement (data)
                if ((res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0) hasModifiedOrNew = true;
              } else if (key === 'emergencyContact') {
                const res = await ProfileServicesEss.listEmergency(profile.id, essId).query(requestActions);
                if ((res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0) hasModifiedOrNew = true;
              } else if (key === 'familyMember') {
                const res = await ProfileServicesEss.listRelationship(profile.id, essId).query(requestActions);
                if ((res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0) hasModifiedOrNew = true;
              } else if (key === 'languages') {
                const res = await ProfileServicesEss.listLanguage(profile.id, essId).query(requestActions);
                if ((res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0) hasModifiedOrNew = true;
              } else if (key === 'training') {
                const res = await ProfileServicesEss.listTraining(profile.id, essId).query(requestActions);
                // Pass if any existing DB records (data/dataCert) OR newly added/modified during announcement
                if ((res?.data?.length || 0) > 0 || (res?.dataCert?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0 || (res?.oldDataCert?.length || 0) > 0 || (res?.newDataCert?.length || 0) > 0) hasModifiedOrNew = true;
              } else if (key === 'workExperiences') {
                const res = await ProfileServicesEss.listExperience(profile.id, essId).query(requestActions);
                if ((res?.data?.length || 0) > 0 || (res?.oldData?.length || 0) > 0 || (res?.newData?.length || 0) > 0) hasModifiedOrNew = true;
              } else if (key === 'contactInformation') {
                hasModifiedOrNew = true;
              } else if (key === 'personalInformation') {
                hasModifiedOrNew = true;
              }
            } catch (err) {
              console.error(`Check modified/new for ${key} failed:`, err);
            }

            if (!hasModifiedOrNew) {
              incompleteTabs.push(tabNameMap[key]);
            }
          }
        }
      }

      const uniqueIncompleteTabs = Array.from(new Set(incompleteTabs));
      if (uniqueIncompleteTabs.length > 0) {
        const getTabIcon = (name: string) => {
          switch (name) {
            case 'Contact Information': return <PhoneOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Personal Information': return <UserOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Family Member': return <UsergroupDeleteOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Emergency Contact': return <ThunderboltOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Education': return <ScheduleOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Languages': return <TagOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Training/Certification': return <ReadOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            case 'Work Experiences': return <SisternodeOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
            default: return <ExclamationCircleOutlined style={{ color: '#ff4d4f', fontSize: 16 }} />;
          }
        };

        Modal.warning({
          title: <span style={{ fontSize: 18, fontWeight: 600, color: '#1f1f1f' }}>Cannot Submit Update</span>,
          width: 500,
          content: (
            <div style={{ marginTop: 12 }}>
              <p style={{ color: '#595959', fontSize: 14, marginBottom: 16 }}>
                Please click on any tab below to open and complete all required fields:
              </p>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 340, overflowY: 'auto', paddingRight: 4 }}>
                {uniqueIncompleteTabs.map((name, idx) => {
                  const sectionMap: Record<string, string> = {
                    'Contact Information': 'contacts',
                    'Personal Information': 'personal',
                    'Family Member': 'family',
                    'Emergency Contact': 'emergency',
                    'Education': 'education',
                    'Languages': 'languages',
                    'Training/Certification': 'training',
                    'Work Experiences': 'experiences',
                  };
                  return (
                    <div
                      key={name || idx}
                      onClick={() => {
                        Modal.destroyAll();
                        const targetType = sectionMap[name] || 'personal';
                        window.dispatchEvent(new CustomEvent('openProfileV2Section', { detail: targetType }));
                      }}
                      style={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        background: '#fff2f0',
                        border: '1px solid #ffccc7',
                        borderRadius: 8,
                        padding: '10px 14px',
                        boxShadow: '0 2px 4px rgba(255, 77, 79, 0.05)',
                        transition: 'all 0.2s ease',
                        cursor: 'pointer',
                      }}
                    >
                      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                        <div
                          style={{
                            width: 34,
                            height: 34,
                            borderRadius: 8,
                            background: '#fff',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            boxShadow: '0 1px 3px rgba(0,0,0,0.06)',
                            flexShrink: 0,
                          }}
                        >
                          {getTabIcon(name)}
                        </div>
                        <span style={{ fontWeight: 600, color: '#cf1322', fontSize: 14 }}>
                          {name}
                        </span>
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span
                          style={{
                            background: '#ff4d4f',
                            color: '#fff',
                            fontSize: 11,
                            fontWeight: 600,
                            padding: '2px 10px',
                            borderRadius: 12,
                            textTransform: 'uppercase',
                            letterSpacing: 0.5,
                            flexShrink: 0,
                          }}
                        >
                          Incomplete
                        </span>
                        <span
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 4,
                            color: '#1677ff',
                            fontSize: 12,
                            fontWeight: 600,
                            background: '#e6f4ff',
                            border: '1px solid #91caff',
                            padding: '2px 10px',
                            borderRadius: 12,
                            flexShrink: 0,
                          }}
                        >
                          Open Form <RightOutlined style={{ fontSize: 10 }} />
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ),
        });
        return;
      }
    }

    Modal.confirm({
      title: sms,
      content: 'Do you want to ' + sms + ' data?',
      onOk: async () => {
        try {
          if (step_id == 2) {
            await ProfileServicesEss.saveEssProfile({ ...profile?.profile, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: '', status: true })(requestActions);
          } else if (step_id == 9) {
            message.info("Save to draft...");
          } else {
            await ProfileServicesEss.saveEssProfile({ ...profile?.profile_draft, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: '', status: true })(requestActions);
          }
          initData();
        } catch (error: any) {
          message.error(error.message || 'Failed to created.');
        }
      },
    });
  }

  const onRejected = (step_id: number) => {
    Modal.confirm({
      title: 'Rejected',
      content: <div><ProFormTextArea name={"comment"} fieldProps={{ onChange: (e) => { onTextChange(e.currentTarget.value); } }} placeholder={"Entry Message"} /></div>,
      onOk: async () => {
        try {
          await ProfileServicesEss.approvalEssProfile({ ...profile?.profile_draft, id: profile?.id, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: _valueText, status: true })(requestActions);
          initData();
        } catch (error: any) {
          message.error(error.message || 'Failed to created.');
        }
      },
    });
  }

  const onStartResubmit = (step_id: number) => {
    Modal.confirm({
      title: 'Resubmit',
      content: 'Do you want to resubmit data?',
      onOk: async () => {
        try {
          await ProfileServicesEss.saveEssProfile({ ...profile?.profile_draft, id: profile?.id, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: '', status: true })(requestActions);
          initData();
        } catch (error: any) {
          message.error(error.message || 'Failed to created.');
        }
      },
    });
  }

  const onStartAproval = (step_id: number) => {
    Modal.confirm({
      title: 'Approval Data',
      content: 'Do you want to start approval data?',
      onOk: async () => {
        try {
          await ProfileServicesEss.approvalEssProfile({ ...profile?.profile_draft, id: profile?.id, empId: profile?.id, step: step_id, openEssId: profile?.ess.id, otherFile: [], remark: '', status: true })(requestActions);
          setStep(step_id);
          initData();
        } catch (error: any) {
          message.error(error.message || 'Failed to created.');
        }
      },
    });
  }

  useEffect(() => {
    initData();
  }, []);

  const initData = async () => {
    try {
      const rs = await ProfileServices.fetchProfile(Number(_id)).query(requestActions);
      if (rs?.profile_draft == null) {
        setStep(rs?.ess.stag);
      } else {
        setStep(rs?.profile_draft.step!!);
      }
      setProfile(rs);
    } catch (error: any) {
      console.error("fetchProfile error:", error);
      if (error.message !== 'Profile not found') {
        message.error(error.message || 'Failed to load data.');
      }
    }
  }

  const hideModal = (visble?: boolean) => !visble && setModalViewEditVisible(undefined);

  const _info = "Update Period:  " + (profile?.ess?.id!! <= 0 ? '' : formatDATEFUll(profile?.ess?.startDate)) + "  -  " + (profile?.ess?.id!! <= 0 ? '' : formatDATEFUll(profile?.ess?.endDate)) + "";
  // Indexed by the real ess_open_announcement_item.step_id values (see EssProfileServiceImpl.kt).
  // Index 0 is unused: step_id 0 is only ever written directly to the item, never to
  // profile_draft.step, so `step` here (sourced from profile_draft.step) never actually takes that value.
  const _stag = [undefined, "Getting Started", "Start Modifying", "Reviewing", "Rejected", "Re-Edit", "Approval", "Cancelled Submitted", "Cancel Updated"];
  const _stag_message = [
    undefined,
    _info,
    "Employee starts modifying profile",
    "Your update request is under review",
    (profile?.profile_draft == null ? '' : profile?.profile_draft.remark),
    (profile?.profile_draft == null ? '' : profile?.profile_draft.remark),
    "Approval",
    "Cancelled Submitted",
    "Cancel Updated"
  ];

  const familyColumns = [
    { title: 'Family type', dataIndex: 'type', key: 'type', width: '30%' },
    { title: 'Person name', dataIndex: 'name', key: 'name' },
  ];

  const familyData = [
    { key: '1', type: 'Father', name: 'Benjamin Williams' },
    { key: '2', type: 'Mother', name: 'Evelyn Potts' },
    { key: '3', type: 'Siblings', name: <><Text>James Williams</Text><br /><Text>Emily Williams</Text></> },
  ];

  const renderUIOnly = () => {
    return (
      <div>
        <Tabs renderTabBar={() => null} tabBarStyle={{ display: 'none' }} activeKey={activeTab} onChange={handleTabChange} items={[
          {
            key: '1',
            label: '',
            children: (
              <div style={{ marginBottom: '24px' }}>
                <BasicInfoCard profile={profile as any} is_admin={Number(_is_admin)} empId={Number(_id)} step={step} cb={{ onLoadData: initData, onChangeTab: handleTabChange }} />
              </div>
            )
          },
          // { key: 'personal', label: 'Employee details', children: <Personal profile={profile as any} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: initData }} /> },
          // { key: 'contacts', label: 'Contact Info', children: <UserContact profile={profile as any} step={step} is_admin={Number(_is_admin)} /> },
          // { key: 'emergency', label: 'Emergency Contact', children: <Emergency profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: initData }} /> },
          // { key: 'education', label: 'Education', children: <Education profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: initData }} /> },
          // { key: 'family', label: 'Family', children: <Relationship profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: initData }} /> },
          // { key: 'languages', label: 'Languages', children: <Languages profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: initData }} /> },
          // { key: 'training', label: 'Training', children: <Training profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: initData }} /> },
          // { key: 'experiences', label: 'Experiences', children: <Experiences profile={profile} step={step} is_admin={Number(_is_admin)} empId={Number(_id)} cb={{ onLoadData: initData }} /> },
          // { key: 'files', label: 'Files', children: <AttachmentList profile={profile as any} step={step} is_admin={Number(_is_admin)} /> },
          // { key: 'activity', label: 'Activity', children: <Activity profile={profile as any} step={step} is_admin={Number(_is_admin)} /> },
        ]} />
        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px', padding: '16px 0' }}>
          {/* Pass the current step through instead of the unmapped literal 9 — saving a draft
              persists form data without advancing the workflow, so step_id shouldn't change. */}
          <Button key="draft" style={{ background: '#E7E6E6', display: ([7, 5, 2].find((element) => element == step)) && Number(_id) == 0 ? '' : 'none' }} onClick={() => onStartModify(step, 'Save Draft')}><EditOutlined /> Save Draft</Button>
          {profile?.ess?.id!! > 0 && <Button key="submit" type="primary" style={{ display: ([7, 5, 2].find((element) => element == step)) && Number(_id) == 0 ? '' : 'none' }} onClick={() => onStartModify(3, 'Submit Update')}><EditOutlined /> Submit Update</Button>}
          {profile?.ess?.id!! > 0 && <Button key="cancel" style={{ display: (step == 3 && Number(_id) == 0) == true ? '' : 'none', color: 'red' }} onClick={() => onStartModify(7, 'Cancel Submitted')}><HistoryOutlined /> Cancel Submitted</Button>}
          {access?.canAccessHrESSApprovalProfile == true && profile?.ess?.id!! > 0 && <Button key="reject" style={{ color: 'red', display: (step == 3 && Number(_id) > 0) == true ? '' : 'none' }} onClick={() => onRejected(4)}><EditOutlined /> Rejected</Button>}
          {access?.canAccessHrESSApprovalProfile == true && <Button key="approve" type="primary" style={{ display: (step == 3 && Number(_id) > 0) == true ? '' : 'none' }} onClick={() => onStartAproval(6)}><EditOutlined /> Approval</Button>}
        </div>
      </div>
    );
  }

  return (
    <Spin spinning={requestActions.request?.loading}>
      <div style={{ width: '100%', margin: '0 auto' }}>
        {profile?.ess?.id!! <= 0 ? '' : profile?.ess?.empClosed == 2 ? '' : profile?.ess?.stag == 8 ? '' :
          profile && <Message visible={(step == 6 && Number(_id) == 0) ? true : false}
            message={_stag[step]}
            description={_stag_message[step]}
            opentitle={profile?.ess?.description!!}
            type={[4, 5].find((element) => element == step) ? "error" : "info"}
            step={step}
            data={profile?.profile_draft}
            is_admin={[1, 2].find((element) => element == Number(_is_admin)) ? true : false}
            cb={{
              onStartModify: (stepId) => {
                onStartModify(stepId, 'Start Modify Data');
              },
            }}
          />
        }

        {profile && renderUIOnly()}

        {!profile && <Alert message="Error" description={<div>Your profile is not yet set up , please contact ICT for support or submit by this <a href='https://forms.office.com/r/Zzw498T9Vv' target='_blank'>Link</a>.</div>} type="error" showIcon />}
      </div>

      <PersonalViewDetailModal
        open={!!modalViedEditVisible?.type}
        onOpenChange={(visible) => hideModal(visible)}
        data={modalViedEditVisible?.payload}
        onFinishFailed={(error: any) => {
          message.error(
            <Space direction="vertical" align="start">
              {error?.errorFields?.map((it: any) => (
                <div key={it.name?.[0]}>{it.errors.join(', ')}</div>
              ))}
            </Space>,
          );
        }}
      />
    </Spin>
  );
}

