    const [cardOpen, setCardOpen] = useState<{ visible: boolean }>({
        visible: false
    });
    console.log(state)
    const [zoomTo, setZoomto] = useState<Location>()
    const [claimedLines, setClaimedLines] = useState<string[]>([]);
    const [claimIds, setClaimIds] = useState<number[]>([]);
