              renderItem={gridRender}
            />}

            {!isFullscreen && viewType == 'list' && <ProList<QueueDisplay> dataSource={filteredData}
              actionRef={actionRef}
              rowKey='id'
              rowClassName={(item: QueueDisplay) => getColor(item)
              }
              metas={{
                avatar: {
                  render: () => <FieldTimeOutlined />
                },
                title: {
                  render: (_, r) => r.truck
                },
                subTitle: {
                  render: (_, r) => r.driver
                },
                description: {
                  render: (_, r) => <ProDescriptions<QueueDisplay> dataSource={r} column={4} columns={[
                    { title: "Ticket No", render: () => r.ticketNo },
                    { title: "Issued On", render: () => r.createdDate && formatDateTime(r.createdDate) },
                    { title: "Loading Dock", render: () => r.loadingDock || "Waiting" }
                  ]} />
                }
              }} />}
          </Card>
        </div>
      )}

      {!auth && (
        <Login
          onLogin={async (token) => {
            setOfflineToken(token);
            setAuth(true);
            await loadData();
          }}
        />
      )}

      <LayoutConfigList
        selectedItem={selectedLayout}
        onSelectedLayout={setSelectedLayout}
        open={configVisible}
        onClose={() => SetConfigVisible(false)}
      />
    </div>
  );
};

