import BaseCrud from "@/components/base-crud"
import { formatDateTime, formatDateTime12 } from "@/pages/utils";
import { simpleRequestActions } from "@/services/model"
import { ExportOutlined, PlusOutlined } from "@ant-design/icons";
import { ITRequestDetail, ITRequestFormNames, ITRequestItemDetail, ITRequestListItem, SearchParams } from "./data.types";
import RequestForm from "./RequestForm";
import { createService } from "./services";
import { useAccess, history } from "@umijs/max";
import Status from "@/components/Status";
import { Button, Flex, Table, Typography } from "antd";


const isPending = (entity: ITRequestListItem) => !entity.lastStep && !!entity.currentAssignee;

export default () => {

    const requestActions = simpleRequestActions();
    const srv = createService(requestActions)
    const access = useAccess()

    return <BaseCrud<ITRequestListItem, ITRequestDetail, SearchParams, {} >

        listView={{
            statusProps: {
                defaultValue: 'ALL',
                options: [
                    { label: "All", value: "ALL" },
                    { label: "Pending", value: "PENDING" },
                    { label: "Completed", value: "COMPLETED" },
                    { label: "Rejected", value: "REJECTED" },
                ]
            },
            addNewAction: access.canRequestITRequest ? {
                label: 'New Request',
                icon: <PlusOutlined />,
                key: 'new-request',
                onRenderComp(props) {
                    return <RequestForm  {...props} />
                },
            } : undefined,
            quickSearch: true,
            expandable: {
                rowExpandable: (entity) => !!entity.items?.length,
                expandedRowRender: (entity) => (
                    <div style={{ background: '#fafafa', margin: -8, padding: 12, borderRadius: 4 }}>
                        <Table<ITRequestItemDetail>
                            dataSource={entity.items}
                            rowKey="id"
                            size="small"
                            bordered
                            pagination={false}
                            style={{ background: '#fff', borderRadius: 4, overflow: 'hidden' }}
                            columns={[
                                { title: 'Category', dataIndex: 'category', width: 180 },
                                {
                                    title: 'Item Name', dataIndex: 'itemName', render(itemName) {
                                        return <Typography.Text strong>{itemName}</Typography.Text>
                                    },
                                },
                                {
                                    title: 'Remarks', dataIndex: 'remarks'
                                },
                            ]}
                        />
                    </div>
                ),
            },
            columns: () => [
                {
                    title: 'Form No', width: 160, sorter: 'formNo', render(_, entity) {
                        return <Flex gap={5}><Button
                            size="small"
                            type="link"
                            title="Open in new tab"
                            icon={<ExportOutlined />}
                            onClick={() => {
                                window
                                    .open(
                                        `/external/data-form/${ITRequestFormNames.processDefKey}/${entity.processInstanceId}`,
                                    )
                                    ?.focus();
                            }}
                        />
                            <a onClick={() => { history.push(`/data-form/${ITRequestFormNames.processDefKey}/${entity.processInstanceId}`) }}>{entity.formNo}</a>
                        </Flex>
                    },
                },
                { title: 'Requested By', sorter: 'requestedBy', dataIndex: 'requestedBy' },
                {
                    title: 'Requested Date',width: 90, sorter: 'requestedDate', render(_, entity) {
                        return formatDateTime12(entity.requestedDate)
                    },
                },
                { title: 'Reason', sorter: 'reason', dataIndex: 'reason' },
                {
                    title: 'Review Stage', render(_, entity) {
                        return isPending(entity) ? entity.currentAssignee : entity.lastActionBy
                    },
                },
                {
                    title: 'Approve Status', render(_, entity) {
                        return <Status text={isPending(entity) ? 'PENDING' : 'COMPLETED'} />
                    },
                },
                {
                    title: 'Approved Date', render(_, entity) {
                        return formatDateTime12(isPending(entity) ? undefined : entity.lastActionDate)
                    },
                },
                {
                    title: 'Completed Date',width: 90, sorter: 'completedDate', render(_, entity,) {
                        return formatDateTime12(entity.completedDate)
                    },
                },
                {
                    title: 'Complete By', render(_, entity) {
                        return entity.completedDate ? entity.completedBy :
                        entity.lastStep ? entity.currentAssignee:''
                    },
                },
                {
                    title: 'Status',width: 100, sorter: 'status', render(_, entity) {
                        return <Status text={entity.status} />
                    }
                },

            ]
        }} services={srv} title={"IT Request"} />

}

