import BaseCrud from "@/components/base-crud"
import { history, useAccess, useQuery } from "@umijs/max";
import { ITNewStaffFormNames, NewStaffItemDetail, NewStaffListItem, SavePayLoad, SearchParams } from "./data.types"
import { createService } from "./services"
import { simpleRequestActions } from "@/services/model"
import { ExportOutlined, FilterOutlined, PlusOutlined, SelectOutlined } from "@ant-design/icons";
import RequestForm from "./ItNewStaffRequestForm";
import { formatDateTime, toReadable } from "@/pages/utils";
import Status from "@/components/Status";
import { Button, Flex, Space } from "antd";
import Export from "./Export";
import PageWrapper from "@/components/PageWrapper";
import { useMemo, useRef, useState } from "react";
import { TableViewSearchParams } from "@/components/DataCrud/TableView";
import AdvacneSearchParam from "./AdvanceSearchParams"
import { ActionType } from "@ant-design/pro-components";
import Form from "@/pages/process-flow/form";
export default () => {
  const access = useAccess()
  const requestActions = simpleRequestActions();
  const srv = createService(requestActions)

  const [filter, setFilter] = useState<TableViewSearchParams<SearchParams>>({
    criteria: {
      keyword: "",
      buIds: [],
      depIds: [],
      advanceSearch: {
        buIds: [],
        depIds: [],
        status: "ALL",
      },
    },
  });
  const { data, isLoading, refetch } = useQuery(
    ['fetch-paging-it-new-staff-request', filter],
    () => srv.fetchPaging(filter),
    { refetchOnWindowFocus: false }
  )
  const actionRef = useRef<ActionType>();
  const isAdvancedFiltered = () => {
    const adv = filter.criteria?.advanceSearch;
    return (
      (adv?.buIds?.length ?? 0) > 0 ||
      (adv?.depIds?.length ?? 0) > 0
    );
  };
  const [advanceSearchVisible, setAdvanceSearchVisible] = useState(false);
  const advanceSearchIcon = useMemo(() => {
    return isAdvancedFiltered()
      ? <FilterOutlined style={{ color: "red" }} />
      : <SelectOutlined />;
  }, [filter.criteria?.advanceSearch]);

  return (
    <>
      <PageWrapper<NewStaffListItem, SearchParams, NewStaffItemDetail | SavePayLoad >
        tabRender={(item) => [
          {
            action: 'add',
            tabLabel: 'New Request',
            tabIcon: <PlusOutlined />,
            panel: (props) => (
              <RequestForm formKey={""} />
            )
          },
          {
            action: 'view',
            tabLabel: item?.empName,
            tabIcon: <PlusOutlined />,
            panel: (props) => <Form openInTab formKey='it_new_staff_request' id={item?.processInstId} />
          }
        ]}
        listView={{
          type: "Table",
          title: "ICT - New Staff Support Request",
          advanceSearchButton: (
            <Button
              onClick={() => setAdvanceSearchVisible(true)}
              icon={advanceSearchIcon}
            />
          ),
          statuses: [
            {
              option: { label: "All", value: "ALL", default: true },
            }, {
              option: {
                label: "Pending", value: "PENDING"
              }
            },
            {
              option: {
                label: "Completed", value: "COMPLETED"
              }
            },
            {
              option: {
                label: "Rejected", value: "REJECTED"
              }
            }
          ],
          actionButtons: [
            // eslint-disable-next-line react/jsx-key
            <Space>
              {access.canRequestItNewStaffRequestExport && <Export key="export-btn" />}
            </Space>

          ],
          onRefresh: refetch,
          onFilter: (param, page, sort) => {
            setFilter((p) => ({
              ...p,
              criteria: {
                ...p.criteria,
                ...filter.criteria,
                keyword: param?.searchValue,
                status: param?.status,
                buIds: param?.buIds,
                depIds: param?.depIds,
                advanceSearch: {
                  ...p.criteria?.advanceSearch,
                }
              },
              sort: sort,
              pagination: page,
            }))
          },

          props: {
            dataSource: data?.items || [],
            actionRef: actionRef,
            loading: isLoading,
            pagination: {
              total: data?.total,
              current: filter.pagination?.current,
              pageSize: filter.pagination?.pageSize,
              onChange: (current, pageSize) =>
                setFilter((p) => ({
                  ...p,
                  pagination: { current, pageSize },
                })),
            },
            columns: [
              {
                title: '#', sorter: 'formNo', render(_, entity) {
                  return <Flex gap={5}>
                    <Button
                      size="small"
                      type="link"
                      title="Open in new tab"
                      icon={<ExportOutlined />}
                      onClick={() => {
                        window
                          .open(
                            `/external/data-form/${ITNewStaffFormNames.processDefKey}/${entity.processInstId}`,
                          )
                          ?.focus();
                      }}
                    />
                  </Flex>
                },
              },
              {
                title: "Form #",
                width: 160,
                actionProps: (item) => ({
                  type: 'view',
                  label: item.formNo,
                }),
                render: (_, entity) => (
                  <span
                    style={{ color: '#1677ff', cursor: 'pointer' }}
                    onClick={() => {
                      actionRef.current?.open?.({
                        action: 'view',
                        value: entity, // ✅ pass full entity
                        tabLabel: entity.formNo,
                        key: entity.processInstId, // optional unique key
                      });
                    }}
                  >
                    {entity.formNo}
                  </span>
                ),
              },
              { title: 'Requested By', sorter: 'requestedBy', dataIndex: 'requestedBy' },
              {
                title: 'Requested Date', sorter: 'requestedDate', render(_, entity) {
                  return formatDateTime(entity.requestedDate)
                },
              },
              { title: 'Employee ID.', dataIndex: "empNo", sorter: 'empNo' },
              { title: 'Employee Name', dataIndex: "empName", sorter: 'empName' },
              { title: 'Employee Name (KH)', dataIndex: "empLocalName" },
              { title: "Company", dataIndex: "bu" },
              { title: 'Function', dataIndex: "department", sorter: 'dept' },
              { title: 'Job Title', dataIndex: "jobTitle", sorter: 'jobTitle' },
              { title: 'Status', render: (_, r) => <Status text={toReadable(r.status)} />, sorter: 'status' },
            ],
          },
          // quickSearch: true,
          // extra: (
          //   <Space>
          //     {access.canRequestItNewStaffRequestExport && <Export />}
          //   </Space>
          // ),
          // addNewAction: access.canRequestITNewStaffRequest?{
          //   label: 'New Request',
          //   icon: <PlusOutlined />,
          //   key: 'new-request',
          //   onRenderComp(props) {
          //     return <RequestForm  {...props} />
          //   },
          // }:undefined,

          // statusProps: {
          //   defaultValue: "ALL",
          //   options: [
          //     { label: "All", value: "ALL" },
          //     { label: "Pending", value: "PENDING" },
          //     { label: "Completed", value: "COMPLETED" },
          //     { label: "Rejected", value: "REJECTED" },
          //   ]
          // },
          // subStatusProps: undefined,
          // onBeforeSearch: undefined
        }}
      />
      <AdvacneSearchParam
        open={advanceSearchVisible}
        onClose={() => setAdvanceSearchVisible(false)}
        onSearch={(params) => {
          setFilter((prev) => ({
            ...prev,
            criteria: {
              ...prev.criteria,
              buIds: params.buIds,
              depIds: params.depIds,
              advanceSearch: {
                ...prev.criteria?.advanceSearch,
                buIds: params.buIds,
                depIds: params.depIds,
                // startDate: params.startDate,
                // endDate: params.endDate,
              },
            },
          }));
          setAdvanceSearchVisible(false);
        }}
        onReset={() => {
          setFilter((prev) => ({
            ...prev,
            criteria: {
              ...prev.criteria,
              advanceSearch: {
                ...prev.criteria?.advanceSearch,
                buIds: [],
                depIds: [],
                // startDate: undefined,
                // endDate: undefined,
              },
            },
            pagination: { ...prev.pagination, current: 1 },
          }));
        }}
      />
    </>
  );
}

