import PageWrapper from "@/components/PageWrapperV1"
import RequestForm from "./Form"
import { simpleRequestActions } from "@/services/model"
import { useQuery } from "@umijs/max"
import { BookingAPI } from "../service";
import moment from "moment";
import { Tag, Space, Typography, Dropdown, Button } from "antd";
import { MoreOutlined, EyeOutlined, EditOutlined, DeleteOutlined, ExportOutlined } from "@ant-design/icons";
import BookingRequestDetail from "./Detail";
import { useState } from "react";
import { TableViewSearchParams } from "@/components/DataCrud/TableView";

export default () => {
    const requestActions = simpleRequestActions();
    const [filter, setFilter] = useState<TableViewSearchParams<any>>({})
    const { data, isFetching, refetch } = useQuery({
        queryKey: ["bookings", filter],
        queryFn: () => BookingAPI(requestActions).page(filter),
        refetchOnMount: true,
        refetchOnWindowFocus: false,
    })

    return (
        <PageWrapper
            tabRender={(it) => [
                {
                    tabLabel: "New",
                    action: "add",
                    tabKey: "add",
                    panel: ({ onCloseTab }) => <RequestForm
                        onClosed={() => {
                            onCloseTab?.()
                        }}
                    />
                },
                {
                    tabLabel: `${it?.bookingNo || 'Edit'}`,
                    action: "edit",
                    tabKey: `edit-${it?.id}`,
                    panel: ({ onCloseTab }) => <RequestForm
                        id={it?.id}
                        onClosed={() => {
                            onCloseTab?.()
                        }}
                    />
                },
                {
                    tabLabel: `${it?.bookingNo || 'Detail'}`,
                    action: "view",
                    tabKey: it?.id,
                    isExternalRoute: true,
                    panel: () => <BookingRequestDetail id={it?.id} />
                }
            ]}
            listView={{
                title: "Request List",
                type: "Table",
                statuses: [
                    { option: { value: "ALL", label: "All" } },
                    { option: { value: "DRAFT", label: "Draft" } },
                    { option: { value: "PENDING_APPROVAL", label: "Pending" } },
                    { option: { value: "APPROVED", label: "Approved" } },
                    { option: { value: "REJECTED", label: "Rejected" } },
                ],
                onRefresh: refetch,
                onFilter: (params, page, sort) => {
                    setFilter((p) => ({
                        criteria: {
                            ...p.criteria,
                            searchValue: params?.searchValue,
                            advanceSearch: {
                                ...p.criteria?.advanceSearch,
                                ...params
                            }
                        },
                        pagination: {
                            ...p.pagination,
                            page: page?.current,
                            pageSize: page?.pageSize
                        }
                    }))
                },
                props: {
                    dataSource: data?.items,
                    loading: isFetching,
                    columns: [
                        {
                            title: "Booking No",
                            dataIndex: "bookingNo",
                            width: 150,
                            actionProps: (item) => ({
                                type: "view",
                                label: `${item.bookingNo || '-'}`,
                                direction: "horizontal",
                                actionButtons: [
                                    {
                                        type: "link",
                                        icon: <ExportOutlined />,
                                        onClick: () => {
                                            window.open(`/external/fleet/booking/request/${item.id}`, '_blank')?.focus();
                                        }
                                    }
                                ]
                            })
                        },
                        {
                            title: "Type",
                            dataIndex: "bookingType",
                            width: 120,
                            render: (_, entity: any) => {
                                const type = entity.bookingType?.toUpperCase()
                                let style = { color: '#64748b', background: '#f1f5f9' }
                                if (type === 'CAR') {
                                    style = { color: '#2563eb', background: '#eff6ff' }
                                } else if (type === 'MOTORBIKE') {
                                    style = { color: '#ea580c', background: '#fff7ed' }
                                } else if (type === 'CARD') {
                                    style = { color: '#7c3aed', background: '#f5f3ff' }
                                }
                                return (
                                    <span style={{
                                        fontSize: '11px',
                                        fontWeight: 600,
                                        padding: '3px 8px',
                                        borderRadius: '4px',
                                        textTransform: 'uppercase',
                                        letterSpacing: '0.03em',
                                        display: 'inline-flex',
                                        ...style
                                    }}>
                                        {type || 'Unknown'}
                                    </span>
                                )
                            }
                        },
                        {
                            title: "Requestor",
                            dataIndex: "requestorName",
                            render: (_, entity: any) => (
                                <Space direction="vertical" size={0}>
                                    <Typography.Text style={{ fontWeight: 500, color: '#0f172a' }}>{entity.requestorName || entity.requestorCode || 'N/A'}</Typography.Text>
                                    {entity.departmentName && <Typography.Text type="secondary" style={{ fontSize: '11px', color: '#64748b' }}>{entity.departmentName}</Typography.Text>}
                                </Space>
                            )
                        },
                        {
                            title: "Purpose",
                            dataIndex: "purpose",
                            ellipsis: true,
                            render: (_, entity: any) => entity.detail?.purpose || '-'
                        },
                        {
                            title: "Created Date",
                            dataIndex: "createdDate",
                            width: 160,
                            render: (_, entity: any) => entity.createdDate ? moment(entity.createdDate).format("DD MMM YYYY, hh:mm A") : '-'
                        },
                        {
                            title: "Status",
                            dataIndex: "status",
                            render: (_, entity: any) => {
                                const status = entity.status?.toUpperCase()
                                let style = {
                                    color: '#475569',
                                    background: '#f1f5f9',
                                    border: '1px solid #cbd5e1'
                                }
                                if (status === 'APPROVED') {
                                    style = {
                                        color: '#16a34a',
                                        background: '#f0fdf4',
                                        border: '1px solid #bbf7d0'
                                    }
                                } else if (status === 'REJECTED' || status === 'CANCELLED') {
                                    style = {
                                        color: '#dc2626',
                                        background: '#fef2f2',
                                        border: '1px solid #fecaca'
                                    }
                                } else if (status === 'PENDING' || status === 'PENDING_APPROVAL') {
                                    style = {
                                        color: '#d97706',
                                        background: '#fffbeb',
                                        border: '1px solid #fef3c7'
                                    }
                                }
                                return (
                                    <span style={{
                                        fontSize: '11px',
                                        fontWeight: 600,
                                        padding: '3px 8px',
                                        borderRadius: '4px',
                                        letterSpacing: '0.03em',
                                        textTransform: 'uppercase',
                                        display: 'inline-flex',
                                        alignItems: 'center',
                                        ...style
                                    }}>
                                        {status || 'N/A'}
                                    </span>
                                )
                            }
                        },
                        // {
                        //     title: "Action",
                        //     key: "action",
                        //     width: 80,
                        //     align: "center",
                        //     render: (_, entity: any, __, action: any) => {
                        //         const handleMenuClick = ({ key, domEvent }: any) => {
                        //             domEvent?.stopPropagation();
                        //             if (key === 'view') {
                        //                 action?.openTab?.('view');
                        //             } else if (key === 'edit') {
                        //                 action??.('edit');
                        //             }
                        //         };
                        //         const items = [
                        //             {
                        //                 key: 'view',
                        //                 icon: <EyeOutlined />,
                        //                 label: 'View',
                        //             },
                        //             {
                        //                 key: 'edit',
                        //                 icon: <EditOutlined />,
                        //                 label: 'Edit',
                        //             },
                        //             {
                        //                 key: 'delete',
                        //                 icon: <DeleteOutlined />,
                        //                 label: 'Delete',
                        //                 danger: true,
                        //             }
                        //         ];
                        //         return (
                        //             <Dropdown menu={{ items, onClick: handleMenuClick }} placement="bottomRight" trigger={['hover']}>
                        //                 <Button type="text" icon={<MoreOutlined />} onClick={(e) => e.stopPropagation()} />
                        //             </Dropdown>
                        //         )
                        //     }
                        // }
                    ]
                }
            }}

        />
    )
}

