import React, { useState } from "react";
import PageWrapper from "@/components/PageWrapper";
import { BookingAssignmentForm } from "./Form";
import { useQuery } from "@umijs/max";
import moment from "moment";
import { Tag, Space, Typography, Dropdown, Button, Drawer, Modal, message, Input, MenuProps } from "antd";
import { MoreOutlined, CheckCircleOutlined, CloseCircleOutlined, SwapOutlined, EllipsisOutlined, CarOutlined, ExportOutlined } from "@ant-design/icons";
import { TableViewSearchParams } from "@/components/DataCrud/TableView";
import { BookingAssignmentAPIService } from "./services";
import { HandleAction } from "@ant-design/pro-editor";
import { BookingAssignmentActionEnum, BookingAssignmentActionParam } from "./data";
import { RemarkModal } from "@/components/RemarkModal";

export default () => {
    const [filter, setFilter] = useState<TableViewSearchParams<any>>({
        criteria: {

        }
    });

    const [drawerVisible, setDrawerVisible] = useState(false);
    const [selectedBookingId, setSelectedBookingId] = useState<number | undefined>(undefined);
    const [drawerWidth, setDrawerWidth] = useState(1000);

    const { data, isFetching, refetch } = useQuery({
        queryKey: ["bookings-assignment", filter],
        queryFn: () => BookingAssignmentAPIService.page(filter),
        refetchOnMount: true,
        refetchOnWindowFocus: false,
    });

    const handleComplete = () => {
        Modal.confirm({
            title: 'Complete Trip',
            content: 'Are you sure you want to mark this trip assignment as completed? This will return the vehicle and driver back.',
            okText: 'Complete',
            cancelText: 'Cancel',
            okButtonProps: { style: { background: '#16a34a', borderColor: '#16a34a', borderRadius: '6px' } },
            cancelButtonProps: { style: { borderRadius: '6px' } },
            onOk: async () => {
                try {
                    // await BookingAPIService.complete({ id, bookingId: id });
                    message.success("Trip completed successfully!");
                    refetch();
                } catch (e: any) {
                    message.error(e.message || "Failed to complete trip");
                }
            }
        });
    };
    const selectedBooking = data?.items?.find((item: any) => item.id === selectedBookingId);
    const isReassignment = selectedBooking?.assign?.status?.toUpperCase() === 'ASSIGNED' || selectedBooking?.assign?.status?.toUpperCase() === 'IN_PROGRESS';




    const [actionnModalOpen, setActionModalOpen] = React.useState<{ visible: boolean, action?: BookingAssignmentActionEnum, entity?: any }>({ visible: false });

    const handleAction = async (param: BookingAssignmentActionParam) => {
        BookingAssignmentAPIService.actions(param).then(() => {
            message.success("Booking action performed successfully")
            setActionModalOpen({ visible: false })
            refetch()
        }).catch((error) => {
            message.error(error?.message)
        })

    }
    const item = (entity: any): MenuProps["items"] => [
        {
            key: "unassign",
            label: "Unassign",
            danger: true,
            icon: <CarOutlined />,
            disabled: !['ASSIGNED'].includes(entity?.status?.toUpperCase()),
            onClick: () => setActionModalOpen({ visible: true, action: BookingAssignmentActionEnum.UNASSIGN, entity })
        },
        {
            key: "reject",
            label: "Reject",
            icon: <CloseCircleOutlined />,
            danger: true,
            disabled: !['PENDING_ASSIGN'].includes(entity?.status?.toUpperCase()),
            onClick: () => setActionModalOpen({ visible: true, action: BookingAssignmentActionEnum.REJECT, entity })
        },
        {
            key: "approve",
            label: "Complete",
            icon: <CheckCircleOutlined />,
            disabled: !['ASSIGNED', 'IN_PROGRESS'].includes(entity?.status?.toUpperCase()),
            onClick: () => setActionModalOpen({ visible: true, action: BookingAssignmentActionEnum.COMPLETED, entity })
        }
    ]

    return (
        <div>
            <PageWrapper
                tabRender={(it) => [
                    {
                        action: "action1",
                        tabKey: it?.bookingNo || it?.code,
                        tabLabel: it?.bookingNo || it?.code,
                        panel: () => <BookingAssignmentForm bookingId={it.id} />
                    }
                ]}
                listView={{
                    title: "Booking Assignment",
                    type: "Table",
                    actionButtons: [
                        <Button icon={<ExportOutlined />} type="text">Export</Button>
                    ],
                    statuses: [
                        { option: { value: "ALL", label: "All" } },
                        { option: { value: "PENDING_ASSIGN", label: "Pending" } },
                        { option: { value: "ASSIGNED", label: "Assigned" } },
                        { option: { value: "IN_PROGRESS", label: "In Progress" } },
                        { option: { value: "COMPLETED", label: "Completed" } },
                    ],
                    onRefresh: refetch,
                    onFilter: (params, page) => {
                        setFilter((p) => ({
                            criteria: {
                                ...p.criteria,
                                searchValue: params?.searchValue,
                                advanceSearch: {
                                    ...p.criteria?.advanceSearch,
                                    ...params
                                }
                            },
                            pagination: {
                                ...p.pagination,
                                page: page?.current,
                                pageSize: page?.pageSize
                            }
                        }));
                    },
                    props: {
                        dataSource: data?.items,
                        loading: isFetching,
                        columns: [
                            {
                                title: "Booking No",
                                dataIndex: "bookingNo",
                                width: 150,
                                actionProps: (record: any) => ({
                                    type: "action1",
                                    label: `${record?.bookingNo}`,
                                    tabKey: `${record?.bookingNo}`
                                })
                            },
                            {
                                title: "Type",
                                dataIndex: "bookingType",
                                width: 120,
                                render: (_, entity: any) => {
                                    const type = entity.bookingType?.toUpperCase();
                                    let style = { color: '#64748b', background: '#f1f5f9' };
                                    if (type === 'CAR') {
                                        style = { color: '#2563eb', background: '#eff6ff' };
                                    } else if (type === 'MOTORBIKE') {
                                        style = { color: '#ea580c', background: '#fff7ed' };
                                    } else if (type === 'CARD') {
                                        style = { color: '#7c3aed', background: '#f5f3ff' };
                                    }
                                    return (
                                        <span style={{
                                            fontSize: '11px',
                                            fontWeight: 600,
                                            padding: '3px 8px',
                                            borderRadius: '4px',
                                            textTransform: 'uppercase',
                                            letterSpacing: '0.03em',
                                            display: 'inline-flex',
                                            ...style
                                        }}>
                                            {type || 'Unknown'}
                                        </span>
                                    );
                                }
                            },
                            {
                                title: "Requestor",
                                dataIndex: "requestorName",
                                render: (_, entity: any) => (
                                    <Space direction="vertical" size={0}>
                                        <Typography.Text style={{ fontWeight: 500, color: '#0f172a' }}>{entity.requestorName || entity.requestorCode || 'N/A'}</Typography.Text>
                                        {entity.departmentName && <Typography.Text type="secondary" style={{ fontSize: '11px', color: '#64748b' }}>{entity.departmentName}</Typography.Text>}
                                    </Space>
                                )
                            },
                            {
                                title: "Destination",
                                dataIndex: "destination",
                                render: (_, entity: any) => entity.detail?.destination || '-'
                            },
                            {
                                title: "Start Date",
                                dataIndex: "startDateTime",
                                width: 160,
                                render: (_, entity: any) => entity.detail?.startDateTime ? moment(entity.detail.startDateTime).format("DD MMM YYYY, hh:mm A") : '-'
                            },
                            {
                                title: "Status",
                                dataIndex: "assignmentStatus",
                                width: 150,
                                render: (_, entity: any) => entity.status?.toLowerCase()?.replace('_', ' ')
                            },
                            {
                                title: "Action",
                                key: "action",
                                width: 80,
                                align: "center",
                                render: (_, entity: any) => {
                                    return (
                                        <Dropdown menu={{
                                            items: item(entity),
                                            style: { width: 200 }
                                        }} placement="bottomRight" trigger={['hover']}>
                                            <Button type="text" icon={<EllipsisOutlined />} />
                                        </Dropdown>
                                    );
                                }
                            }
                        ]
                    }
                }}
            />

            <RemarkModal
                open={actionnModalOpen.visible}
                onCancel={() => setActionModalOpen({ visible: false })}
                onOk={(remark) => handleAction({ remark: remark, action: actionnModalOpen.action, bookingId: actionnModalOpen?.entity?.id! })}
                description={`Are you sure you want to ${actionnModalOpen?.action?.toLocaleLowerCase()} this booking request?`}
                placeholder="Enter reason..."
                required={
                    actionnModalOpen.action === BookingAssignmentActionEnum.REJECT ||
                    actionnModalOpen.action === BookingAssignmentActionEnum.CANCEL ||
                    actionnModalOpen.action === BookingAssignmentActionEnum.COMPLETED ||
                    actionnModalOpen.action === BookingAssignmentActionEnum.UNASSIGN
                }
                showRemarkInput={
                    actionnModalOpen.action === BookingAssignmentActionEnum.REJECT ||
                    actionnModalOpen.action === BookingAssignmentActionEnum.CANCEL ||
                    actionnModalOpen.action === BookingAssignmentActionEnum.COMPLETED ||
                    actionnModalOpen.action === BookingAssignmentActionEnum.UNASSIGN
                }
                title={undefined}
            />
        </div>
    );
};

