import ListMenuComp from "@/components/ListMenu";
import { ReportName } from "@/pages/crm/reports";
import { PageContainer } from "@ant-design/pro-components";
import { useAccess, useQuery } from "@umijs/max";
import { useState } from "react";
import { translationsIcon } from '@/assets/translations.png';
import PageWrapper from "@/components/PageWrapper";
import TranslationForm from "./Form";
import TranslationAPIService from "./service";
import { TableViewSearchParams } from "@/components/DataCrud/TableView";
import { Button } from "antd";
import { DeleteOutlined, EditOutlined } from "@ant-design/icons";
import { RemarkModal } from "@/components/RemarkModal";
import TranslationModal from "./ModalForm";


export default () => {
    const [filter, setFilter] = useState<TableViewSearchParams<any>>();
    const { data, isFetching, refetch } = useQuery({
        queryKey: ["translation-location"],
        queryFn: async () => TranslationAPIService.page(filter),
        refetchOnWindowFocus: false,

    });
    const [remarkState, setRemarkState] = useState<{ visible?: boolean, action?: string, id?: number }>();
    const [editFormState, setEditFormState] = useState<{ visible?: boolean, data?: any }>();
    return (
        <>
            <PageWrapper
                tabRender={(it) => [
                    {
                        tabKey: "add",
                        tabLabel: "Add",
                        action: "add",
                        panel: () => <TranslationForm />
                    }
                ]}

                listView={{
                    type: "Table",
                    onRefresh: refetch,

                    props: {
                        dataSource: data?.items || [],
                        loading: isFetching,
                        columns: [
                            {
                                title: "ID",
                                dataIndex: "id",
                                width: 80,
                            },
                            {
                                title: "Module",
                                dataIndex: "module",
                                width: 120,
                            },
                            {
                                title: "Translation Key",
                                dataIndex: "translationKey",
                            },
                            {
                                title: "Translation Text",
                                dataIndex: "translationText",
                            },
                            {
                                title: "Language",
                                dataIndex: "languageCode",
                                width: 100,
                            },
                            {
                                title: "Active",
                                dataIndex: "active",
                                width: 100,
                                render: (active: boolean) => active ? "Yes" : "No"
                            },
                            {
                                title: "Created By",
                                dataIndex: "createdBy",
                                width: 120,
                            },
                            {
                                title: "Created Date",
                                dataIndex: "createdDate",
                                width: 180,
                                valueType: "dateTime"
                            },
                            {
                                title: "Version",
                                dataIndex: "version",
                                width: 80,
                            },
                            {
                                title: "Action",
                                render: (_, r: any) => <>
                                    <Button icon={<EditOutlined />} type="text" onClick={() => setEditFormState({ data: r, visible: true })} />
                                    <Button icon={<DeleteOutlined />} type="text"
                                        onClick={() => setRemarkState({ id: r.id, action: "DELETE", visible: true })}
                                        danger />
                                </>
                            }
                        ]
                    }
                }}
            />
            <TranslationModal
                open={editFormState?.visible ?? false}
                data={editFormState?.data}
                width={500}
                modalProps={{
                    onCancel: (e) => setEditFormState({}),
                }}
                onFinish={async (values) => {
                    await TranslationAPIService.save({
                        module: values.module,
                        data: [{ ...values }]
                    });
                    refetch?.();
                    setEditFormState({})
                }}
            />

            <RemarkModal
                title={`Remark for ${remarkState?.action?.toLowerCase()}`}
                open={remarkState?.visible ?? false}
                onCancel={() => setRemarkState({})}
                onOk={async (remark) => {
                    await TranslationAPIService.action({
                        id: remarkState?.id,
                        action: remarkState?.action,
                        remark: remark
                    });
                    setRemarkState({});
                    refetch?.();
                }}

            />

        </>
    )
}

