import React, { useState, useEffect } from 'react';
import { useQuery } from '@umijs/max';
import AppConfigurationAPIService from './service';
import {
    Tag,
    Typography,
    Flex,
    Card,
    Row,
    Col,
    Button,
    Space,
    Switch,
    Input,
    InputNumber,
    Select,
    Form,
    Badge,
    Avatar,
    Table,
    Modal,
    notification,
    ConfigProvider,
    theme,
    Tooltip,
    Divider
} from 'antd';
import { ProCard, ProDescriptions } from '@ant-design/pro-components';
import {
    SettingOutlined,
    SecurityScanOutlined,
    CloudServerOutlined,
    AppstoreAddOutlined,
    GlobalOutlined,
    InfoCircleOutlined,
    MobileOutlined,
    UserOutlined,
    AppstoreOutlined,
    FileTextOutlined,
    SaveOutlined,
    ReloadOutlined,
    ExportOutlined,
    BulbOutlined,
    EditOutlined,
    DeleteOutlined,
    CheckCircleOutlined,
    CloseCircleOutlined,
    SyncOutlined,
    SafetyOutlined,
    AndroidOutlined,
    AppleOutlined,
    LaptopOutlined,
    ThunderboltOutlined,
    WarningOutlined,
    QuestionCircleOutlined
} from '@ant-design/icons';

const { Title, Text } = Typography;



const initialFormValues = {
    // 1. General Configuration
    maintenanceMode: false,
    maintenanceMessage: 'The system is undergoing scheduled maintenance. Please check back later.',
    forceUpdate: true,
    minimumVersion: '1.0.0',

    // 2. Device Policy
    allowMultipleDevices: true,
    maxDevicePerUser: 3,
    requireDeviceApproval: true,

    // 3. Security Settings
    requireBiometric: true,
    allowRootedDevice: false,
    allowEmulator: false,
    sessionTimeoutMinute: 30,
    maxLoginAttempts: 5,

    // 4. Offline Settings
    allowOfflineMode: true,
    offlineRetentionDay: 7,
    syncIntervalMinute: 15,

    // 5. Feature Management
    enableBanner: true,
    enableTranslation: true,
    enablePushNotification: true,
    enableMiniApp: true,

    // 6. Mobile Application Settings
    appName: 'IES Workplace Suite',
    currentVersion: '1.2.0',
    minSupportedVersion: '1.0.0',
    appStatus: 'Active',

    // 8. Device Registration Policy
    allowDeviceReplacement: true,
    allowSelfRegistration: true,
    autoDisableInactive: true,
    inactiveDaysThreshold: 90
};

const AppConfigManagement: React.FC = () => {
    const [isDark, setIsDark] = useState<boolean>(false);
    const [form] = Form.useForm();
    const [loading, setLoading] = useState<boolean>(false);

    const { data, isFetching, refetch } = useQuery({
        queryKey: ["app-configuration"],
        queryFn: () => AppConfigurationAPIService.fetch().query(),
        refetchOnWindowFocus: false,
    });

    useEffect(() => {
        if (data) {
            form.setFieldsValue(data);

            const lastUpdated = data.modifiedDate || data.createdDate || '';
            const formattedDate = lastUpdated ? new Date(lastUpdated).toLocaleString() : 'Never';

            setMetaInfo({
                lastModified: formattedDate,
                modifiedBy: data.modifiedBy || data.createdBy || 'System',
                status: data.maintenanceMode ? 'Maintenance' : 'Active'
            });
        }
    }, [data, form]);

    // Meta state
    const [metaInfo, setMetaInfo] = useState({
        lastModified: '2026-06-17 14:02:18',
        modifiedBy: 'Admin Reach',
        status: 'Active'
    });

    // Export modal state
    const [isExportModalOpen, setIsExportModalOpen] = useState<boolean>(false);
    const [configJson, setConfigJson] = useState<string>('');

    const allowMultipleDevices = Form.useWatch('allowMultipleDevices', form);

    useEffect(() => {
        if (allowMultipleDevices === false) {
            form.setFieldValue('maxDevicePerUser', 1);
        }
    }, [allowMultipleDevices, form]);

    // Handle save
    const handleSave = async () => {
        try {
            const values = await form.validateFields();
            setLoading(true);

            // Format to exact backend Create record payload
            const backendPayload = {
                maintenanceMode: !!values.maintenanceMode,
                maintenanceMessage: values.maintenanceMessage || '',
                forceUpdate: !!values.forceUpdate,
                minimumVersion: values.minimumVersion || '1.0.0',
                allowMultipleDevices: !!values.allowMultipleDevices,
                maxDevicePerUser: Number(values.maxDevicePerUser) || 1,
                requireDeviceApproval: !!values.requireDeviceApproval,
                requireBiometric: !!values.requireBiometric,
                allowRootedDevice: !!values.allowRootedDevice,
                allowEmulator: !!values.allowEmulator,
                allowOfflineMode: !!values.allowOfflineMode,
                offlineRetentionDay: Number(values.offlineRetentionDay) || 1,
                enableBanner: !!values.enableBanner,
                enableTranslation: !!values.enableTranslation,
                enablePushNotification: !!values.enablePushNotification,
                enableMiniApp: !!values.enableMiniApp,
                sessionTimeoutMinute: Number(values.sessionTimeoutMinute) || 30,
                syncIntervalMinute: Number(values.syncIntervalMinute) || 15
            };
            console.log('Saved payload sent to backend:', backendPayload);

            try {
                Modal.confirm({
                    title: "App Configuration Update",
                    content: "Are you sure you want to update the app configuration policies?",
                    onOk: async () => {
                        if (data?.id) {
                            await AppConfigurationAPIService.update(backendPayload);
                        } else {
                            await AppConfigurationAPIService.save(backendPayload);
                        }
                        notification.success({
                            message: 'Configuration Saved Successfully',
                            description: 'The app policy configurations have been compiled and pushed to active devices.',
                            placement: 'topRight',
                        });
                        setMetaInfo({
                            lastModified: new Date().toISOString().replace('T', ' ').substring(0, 19),
                            modifiedBy: 'Admin Reach',
                            status: values.maintenanceMode ? 'Maintenance' : 'Active'
                        });
                        refetch();
                    }
                });
            } catch (apiError: any) {
                notification.error({
                    message: 'API Save Error',
                    description: apiError?.message || 'Failed to submit the configuration payload to the backend service.',
                    placement: 'topRight'
                });
            } finally {
                setLoading(false);
            }
        } catch (error) {
            notification.error({
                message: 'Validation Failed',
                description: 'Please review and fix configuration policy errors before saving.',
                placement: 'topRight',
            });
        }
    };

    // Handle Reset
    const handleReset = () => {
        Modal.confirm({
            title: 'Are you sure you want to reset policies?',
            icon: <WarningOutlined style={{ color: '#faad14' }} />,
            content: 'This will revert all fields back to their default server configurations.',
            okText: 'Reset',
            cancelText: 'Cancel',
            okButtonProps: { danger: true },
            onOk() {
                form.setFieldsValue(initialFormValues);
                notification.warning({
                    message: 'Configuration Reset',
                    description: 'Policies reverted to standard defaults. Click Save to publish.',
                    placement: 'topRight',
                });
            }
        });
    };

    // Handle Export
    const handleExport = () => {
        const values = form.getFieldsValue();
        const exportData = {
            metadata: {
                exportedAt: new Date().toISOString(),
                exportedBy: metaInfo.modifiedBy,
                schemaVersion: '1.0'
            },
            configuration: {
                maintenanceMode: values.maintenanceMode ?? false,
                maintenanceMessage: values.maintenanceMessage ?? '',
                forceUpdate: values.forceUpdate ?? false,
                minimumVersion: values.minimumVersion ?? '1.0.0',
                allowMultipleDevices: values.allowMultipleDevices ?? false,
                maxDevicePerUser: values.maxDevicePerUser ?? 1,
                requireDeviceApproval: values.requireDeviceApproval ?? false,
                requireBiometric: values.requireBiometric ?? false,
                allowRootedDevice: values.allowRootedDevice ?? false,
                allowEmulator: values.allowEmulator ?? false,
                allowOfflineMode: values.allowOfflineMode ?? false,
                offlineRetentionDay: values.offlineRetentionDay ?? 1,
                enableBanner: values.enableBanner ?? false,
                enableTranslation: values.enableTranslation ?? false,
                enablePushNotification: values.enablePushNotification ?? false,
                enableMiniApp: values.enableMiniApp ?? false,
                sessionTimeoutMinute: values.sessionTimeoutMinute ?? 30,
                syncIntervalMinute: values.syncIntervalMinute ?? 15
            }
        };
        setConfigJson(JSON.stringify(exportData, null, 2));
        setIsExportModalOpen(true);
    };

    // Handle Refresh
    const handleRefresh = async () => {
        setLoading(true);
        try {
            await refetch();
            notification.info({
                message: 'Configuration Refreshed',
                description: 'Latest app config state has been fetched from the server.',
                placement: 'topRight',
            });
        } catch (error: any) {
            notification.error({
                message: 'Refresh Failed',
                description: error?.message || 'Failed to sync with the backend server.',
                placement: 'topRight'
            });
        } finally {
            setLoading(false);
        }
    };



    // Theme values
    const primaryBg = isDark ? '#141414' : '#f5f7fa';
    const cardBg = isDark ? '#1f1f1f' : '#ffffff';
    const textColor = isDark ? 'rgba(255, 255, 255, 0.85)' : 'rgba(0, 0, 0, 0.85)';
    const textSecColor = isDark ? 'rgba(255, 255, 255, 0.45)' : 'rgba(0, 0, 0, 0.45)';
    const borderTheme = isDark ? '#303030' : '#f0f0f0';

    return (
        <ConfigProvider theme={{ algorithm: isDark ? theme.darkAlgorithm : theme.defaultAlgorithm }}>
            <div style={{ background: primaryBg, minHeight: '100vh', padding: '24px 24px 80px 24px', transition: 'all 0.3s ease', color: textColor }}>

                {/* Top Banner / Title */}
                <Flex justify="space-between" align="center" style={{ marginBottom: '24px', paddingBottom: '16px', borderBottom: `1px solid ${borderTheme}` }}>
                    <Flex align="center" gap={12}>
                        <div style={{ background: '#1890ff', padding: '10px', borderRadius: '12px', display: 'flex', justifyContent: 'center', alignContent: 'center' }}>
                            <SettingOutlined style={{ color: '#fff', fontSize: '24px' }} />
                        </div>
                        <div>
                            <Title level={2} style={{ margin: 0, fontWeight: 700 }}>Mobile App Policy Configuration</Title>
                            <Text type="secondary">Enterprise-grade device governance, application control, security restrictions, and mini-app settings</Text>
                        </div>
                    </Flex>
                    <Space size="middle">
                        <Button
                            icon={<BulbOutlined />}
                            onClick={() => setIsDark(!isDark)}
                            type="dashed"
                            style={{ borderRadius: '8px' }}
                        >
                            {isDark ? 'Light Theme' : 'Dark Theme'}
                        </Button>
                        <Button
                            icon={<ReloadOutlined />}
                            onClick={handleRefresh}
                            style={{ borderRadius: '8px' }}
                        >
                            Refresh
                        </Button>
                        <Button
                            icon={<ExportOutlined />}
                            onClick={handleExport}
                            type="primary"
                            ghost
                            style={{ borderRadius: '8px' }}
                        >
                            Export Schema
                        </Button>
                    </Space>
                </Flex>


                <Form
                    form={form}
                    layout="vertical"
                    initialValues={initialFormValues}
                    requiredMark="optional"
                >
                    <Row gutter={[16, 16]}>

                        {/* Left Metadata & Quick Summary Panel */}
                        <Col xs={24} lg={6}>
                            <Flex vertical gap={16}>

                                {/* Status Overview Card */}
                                <Card
                                    title="Policy Metadata"
                                    bordered={false}
                                    style={{ borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)', background: cardBg }}
                                >
                                    <ProDescriptions
                                        column={1}
                                        dataSource={metaInfo}
                                        columns={[
                                            {
                                                title: 'Policy Status',
                                                dataIndex: 'status',
                                                render: (val) => (
                                                    <Tag color={val === 'Active' ? 'success' : 'orange'} style={{ fontWeight: 600, borderRadius: '4px' }}>
                                                        {val === 'Active' ? 'ACTIVE / PUBLISHED' : 'MAINTENANCE MODE'}
                                                    </Tag>
                                                )
                                            },
                                            {
                                                title: 'Modified By',
                                                dataIndex: 'modifiedBy',
                                                render: (val) => (
                                                    <Space>
                                                        <Avatar size="small" style={{ backgroundColor: '#1890ff' }}>R</Avatar>
                                                        <Text strong>{val}</Text>
                                                    </Space>
                                                )
                                            },
                                            {
                                                title: 'Last Updated',
                                                dataIndex: 'lastModified',
                                                render: (val) => (
                                                    <Text type="secondary" style={{ fontSize: '13px' }}>
                                                        <SyncOutlined spin={loading} style={{ marginRight: 6 }} />
