                                    <Divider style={{ margin: '16px 0' }} />
                                    <div>
                                        <Text strong style={{ fontSize: '13px', display: 'block', marginBottom: '8px' }}>Color Indicators Legend:</Text>
                                        <Flex vertical gap={6}>
                                            <Flex align="center" gap={8}><Badge color="#52c41a" /><Text style={{ fontSize: '12px' }}>Green = Policy Enabled</Text></Flex>
                                            <Flex align="center" gap={8}><Badge color="#ff4d4f" /><Text style={{ fontSize: '12px' }}>Red = Policy Disabled</Text></Flex>
                                            <Flex align="center" gap={8}><Badge color="#faad14" /><Text style={{ fontSize: '12px' }}>Orange = Maintenance Mode Active</Text></Flex>
                                            <Flex align="center" gap={8}><Badge color="#1890ff" /><Text style={{ fontSize: '12px' }}>Blue = Informational & Metrics</Text></Flex>
                                        </Flex>
                                    </div>
                                </Card>

                                {/* MDM Governance Card */}
                                <Card
                                    bordered={false}
