                                >
                                    <Flex vertical gap={12}>
                                        <Space>
                                            <SafetyOutlined style={{ fontSize: '24px' }} />
                                            <Title level={4} style={{ color: '#fff', margin: 0 }}>Application Governance</Title>
                                        </Space>
                                        <Text style={{ color: 'rgba(255, 255, 255, 0.85)', fontSize: '13px' }}>
                                            Policy rules are enforced instantly upon the next request from the mobile client. Configuration synchronization applies dynamically on device check-in.
                                        </Text>
                                        <div style={{ marginTop: '8px' }}>
                                            <Badge status="processing" text={<span style={{ color: '#fff', fontSize: '12px' }}>124 active MDM sessions</span>} />
                                        </div>
                                    </Flex>
                                </Card>
                            </Flex>
                        </Col>

                        {/* Right Content forms area */}
                        <Col xs={24} lg={18}>
                            <Flex vertical gap={16}>

                                {/* Section 1 & 6: App General Info & Settings */}
                                <ProCard
                                    title={
                                        <Space>
                                            <InfoCircleOutlined style={{ color: '#1890ff' }} />
                                            <span>General & Application Settings</span>
                                        </Space>
                                    }
                                    bordered
                                    headerBordered
                                    style={{ borderRadius: '12px', background: cardBg }}
                                    loading={loading || isFetching}
                                >
                                    <Row gutter={24}>
                                        <Col xs={24} md={12}>
                                            <Title level={5} style={{ marginBottom: 16 }}>Mobile Application Settings</Title>
                                            <Form.Item
