                                            >
                                                <Input placeholder="e.g. IES Suite" />
                                            </Form.Item>
                                            <Row gutter={12}>
                                                <Col span={12}>
                                                    <Form.Item
                                                        name="currentVersion"
                                                        label="Current Version"
                                                        rules={[
                                                            { required: true, message: 'Required' },
                                                            { pattern: /^[0-9]+\.[0-9]+\.[0-9]+$/, message: 'Must be x.y.z' }
                                                        ]}
                                                    >
                                                        <Input placeholder="e.g. 1.2.0" />
                                                    </Form.Item>
                                                </Col>
                                                <Col span={12}>
                                                    <Form.Item
                                                        name="minSupportedVersion"
                                                        label="Min Supported Version"
                                                        rules={[
                                                            { required: true, message: 'Required' },
                                                            { pattern: /^[0-9]+\.[0-9]+\.[0-9]+$/, message: 'Must be x.y.z' }
                                                        ]}
                                                    >
                                                        <Input placeholder="e.g. 1.0.0" />
                                                    </Form.Item>
                                                </Col>
                                            </Row>
                                            <Form.Item name="appStatus" label="App Status">
                                                <Select options={[
                                                    { value: 'Active', label: <Space><Badge status="success" />Active</Space> },
                                                    { value: 'Inactive', label: <Space><Badge status="error" />Inactive</Space> },
