                                            </Form.Item>
                                        </Col>
                                    </Row>
                                </ProCard>

                                {/* Section 2, 3 & 8: Access, Security & Registration policies */}
                                <ProCard
                                    title={
                                        <Space>
                                            <SecurityScanOutlined style={{ color: '#52c41a' }} />
                                            <span>Security & Device Governance Policy</span>
                                        </Space>
                                    }
                                    bordered
                                    headerBordered
                                    style={{ borderRadius: '12px', background: cardBg }}
                                    loading={loading || isFetching}
                                >
                                    <Row gutter={24}>
                                        <Col xs={24} md={8}>
                                            <Title level={5} style={{ marginBottom: 16 }}>Device Policies</Title>
                                            <Form.Item name="allowMultipleDevices" label="Allow Multiple Devices" valuePropName="checked">
