                                                <Switch checkedChildren="Yes" unCheckedChildren="No" />
                                            </Form.Item>
                                            <Form.Item name="allowEmulator" label="Allow Emulators" valuePropName="checked">
                                                <Switch checkedChildren="Yes" unCheckedChildren="No" />
