                                            <Form.Item name="allowDeviceReplacement" label="Allow Device Replacement" valuePropName="checked">
                                                <Switch checkedChildren="Yes" unCheckedChildren="No" />
                                            </Form.Item>
                                            <Form.Item name="allowSelfRegistration" label="Self Device Registration" valuePropName="checked">
                                                <Switch checkedChildren="Yes" unCheckedChildren="No" />
                                            </Form.Item>
                                            <Form.Item name="autoDisableInactive" label="Auto Disable Inactive Device" valuePropName="checked">
                                                <Switch checkedChildren="Yes" unCheckedChildren="No" />
                                            </Form.Item>
                                            <Form.Item
                                                name="inactiveDaysThreshold"
