                                            >
                                                <InputNumber style={{ width: '100%' }} min={1} />
                                            </Form.Item>
                                        </Col>
                                    </Row>
                                </ProCard>

                                {/* Section 4 & 5: Offline Settings & Feature Management */}
                                <ProCard
                                    title={
                                        <Space>
                                            <CloudServerOutlined style={{ color: '#faad14' }} />
                                            <span>Offline Rules & Feature Flag Management</span>
                                        </Space>
                                    }
                                    bordered
                                    headerBordered
                                    style={{ borderRadius: '12px', background: cardBg }}
                                    loading={loading || isFetching}
                                >
                                    <Row gutter={24}>
                                        <Col xs={24} md={12}>
                                            <Title level={5} style={{ marginBottom: 16 }}>Offline Mode Policy</Title>
                                            <Form.Item name="allowOfflineMode" label="Allow Offline Access" valuePropName="checked">
                                                <Switch checkedChildren="Yes" unCheckedChildren="No" />
                                            </Form.Item>
                                            <Form.Item
                                                name="offlineRetentionDay"
                                                label="Retention Days Limit"
                                                rules={[{ required: true, type: 'number', min: 1, max: 30 }]}
                                            >
                                                <InputNumber style={{ width: '100%' }} min={1} max={30} />
                                            </Form.Item>
                                            <Form.Item
                                                name="syncIntervalMinute"
                                                label="Sync Interval (Minutes)"
                                                rules={[{ required: true, type: 'number', min: 1, max: 1440 }]}
                                            >
                                                <InputNumber style={{ width: '100%' }} min={1} />
                                            </Form.Item>
                                        </Col>

                                        <Col xs={24} md={12}>
                                            <Title level={5} style={{ marginBottom: 16 }}>Active Feature Toggles</Title>
                                            <Row gutter={24}>
                                                <Col span={12}>
                                                    <Form.Item name="enableBanner" label="Enable Banners" valuePropName="checked">
                                                        <Switch checkedChildren="YES" unCheckedChildren="NO" />
                                                    </Form.Item>
                                                    <Form.Item name="enableTranslation" label="Enable Translations" valuePropName="checked">
                                                        <Switch checkedChildren="YES" unCheckedChildren="NO" />
                                                    </Form.Item>
                                                </Col>
                                                <Col span={12}>
                                                    <Form.Item name="enablePushNotification" label="Push Notification" valuePropName="checked">
                                                        <Switch checkedChildren="YES" unCheckedChildren="NO" />
                                                    </Form.Item>
                                                    <Form.Item name="enableMiniApp" label="Enable Mini Apps" valuePropName="checked">
                                                        <Switch checkedChildren="YES" unCheckedChildren="NO" />
                                                    </Form.Item>
                                                </Col>
                                            </Row>
                                        </Col>
                                    </Row>
                                </ProCard>


                            </Flex>
                        </Col>
                    </Row>
                </Form>

                {/* Sticky Action Footer */}
                <div style={{
                    position: 'fixed',
                    bottom: 0,
                    left: 0,
                    right: 0,
                    zIndex: 1000,
                    background: isDark ? 'rgba(31, 31, 31, 0.92)' : 'rgba(255, 255, 255, 0.92)',
                    backdropFilter: 'blur(10px)',
                    borderTop: `1px solid ${borderTheme}`,
                    padding: '12px 24px',
                    boxShadow: isDark ? '0 -4px 24px rgba(0, 0, 0, 0.6)' : '0 -4px 24px rgba(0, 0, 0, 0.06)',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    transition: 'all 0.3s ease'
                }}>
                    <Space>
                        <Text type="secondary" style={{ fontSize: '13px' }}>
                            Last synchronized: <Text strong>{metaInfo.lastModified}</Text>
                        </Text>
                    </Space>
                    <Space size="middle">
                        <Button
                            icon={<ReloadOutlined />}
                            onClick={handleReset}
                            danger
                            type="dashed"
                            style={{ minWidth: '110px' }}
                        >
                            Reset Configuration
                        </Button>
                        <Button
                            type="primary"
                            icon={<SaveOutlined />}
                            loading={loading}
                            onClick={handleSave}
                            style={{ minWidth: '150px' }}
                        >
                            Save Configuration
                        </Button>
                    </Space>
                </div>



                {/* Export Details JSON Dialog Modal */}
                <Modal
                    title={<Space><ExportOutlined /><span>Exported Configuration JSON</span></Space>}
                    open={isExportModalOpen}
                    onCancel={() => setIsExportModalOpen(false)}
                    footer={[
                        <Button key="close" type="primary" onClick={() => setIsExportModalOpen(false)}>
                            Close
                        </Button>
                    ]}
                    width={650}
                >
                    <div style={{ marginTop: 16 }}>
                        <Text type="secondary" style={{ display: 'block', marginBottom: '8px' }}>
                            Copy configuration settings payload to apply globally or migrate to staging/production endpoints.
                        </Text>
                        <Input.TextArea
                            value={configJson}
                            readOnly
                            rows={15}
                            style={{ fontFamily: 'monospace', fontSize: '13px', background: isDark ? '#141414' : '#fafafa' }}
                        />
                    </div>
                </Modal>

            </div>
        </ConfigProvider>
    );
};

export default AppConfigManagement;

