import PageWrapper from "@/components/PageWrapperV1";
import { useQuery } from "@umijs/max";
import { useState } from "react";
import { TableViewSearchParams } from "@/components/DataCrud/TableView";
import EmployeePoicyAPIService from "./service";
import { Tag, Badge, Space, Button, Table, theme, Dropdown, message, Modal } from "antd";
import { EditOutlined, SendOutlined, MoreOutlined, DeleteOutlined, CheckCircleOutlined, StopOutlined, EllipsisOutlined } from "@ant-design/icons";
import dayjs from "dayjs";
import EmployeePolicyDetail from "./Detail";
import TestNotificationModal from "./components/TestNotificationModal";
import { RemarkModal } from "@/components/RemarkModal";

export default () => {
    const { token } = theme.useToken();
    const [filter, setFilter] = useState<TableViewSearchParams<any>>();
    const [testModalOpen, setTestModalOpen] = useState(false);
    const [selectedEmployeeCode, setSelectedEmployeeCode] = useState<string>('');
    const [remarkModalOpen, setRemarkModalOpen] = useState<{ visible: boolean, action: string, item: any }>({ visible: false, action: "", item: undefined });
    const { data, isFetching, refetch } = useQuery({
        queryKey: ["employee-policy", filter],
        queryFn: () => EmployeePoicyAPIService.page(filter),
        refetchOnWindowFocus: false
    });



    return (
        <>
            <PageWrapper
                tabRender={(it) => [
                    {
                        action: "edit",
                        tabKey: it?.employeeCode,
                        tabLabel: `${it?.employeeCode} - ${it?.employeeName}`,
                        panel: ({ onCloseTab }) => (
                            <EmployeePolicyDetail
                                id={it.id}
                                onClose={onCloseTab}
                            />
                        )
                    }
                ]}
                hideAdd
                listView={{
                    type: "Table",
                    onRefresh: refetch,
                    onFilter: (params, page, sort) => {
                        setFilter(prev => ({
                            criteria: {
                                ...prev?.criteria,
                                ...params
                            },
                            pagination: {
                                pageSize: page?.pageSize,
                                page: page?.current
                            }
                        }));
                    },
                    props: {
                        dataSource: data?.items,
                        loading: isFetching,
                        rowKey: "employeeCode",
                        pagination: {
                            total: data?.total
                        },
                        expandable: {
                            expandedRowRender: (record: any) => {
                                return (
                                    <Table
                                        columns={[
                                            { title: "Device ID", dataIndex: "deviceId" },
                                            { title: "Device Name", dataIndex: "deviceName" },
                                            { title: "OS Version", dataIndex: "osName", render: (_: any, r: any) => `${r.osName || ''} ${r.osVersion || ''}` },
                                            {
                                                title: "Status",
                                                dataIndex: "approved",
                                                render: (_: any, r: any) => {
                                                    let color = "blue";
                                                    let text = "Pending";
                                                    if (r.blocked) {
                                                        color = "red";
                                                        text = "Blocked";
                                                    } else if (r.approved) {
                                                        color = "green";
                                                        text = "Approved";
                                                    }
                                                    return <Tag color={color}>{text}</Tag>;
                                                }
                                            },
                                            {
                                                title: "Last Active",
                                                dataIndex: "lastActiveDate",
                                                render: (val: any) => val ? dayjs(val).format('DD-MM-YYYY h:mm:ssA') : "-"
                                            }
                                        ]}
                                        dataSource={record.devices || []}
                                        pagination={false}
                                        size="small"
                                        rowKey="id"
                                        style={{ margin: '8px 0', background: '#fafafa' }}
                                    />
                                );
                            }
                        },
                        columns: [
                            {
                                title: "Employee Code",
                                dataIndex: "employeeCode",
                                actionProps: (it) => ({
                                    label: it.employeeCode,
                                    type: "edit"
                                })
                            },
                            {
                                title: "Employee Name",
                                dataIndex: "employeeName"
                            },
                            {
                                title: "Policy Scope",
                                dataIndex: "policy",
                                render: (val: any) => (
                                    <Tag color={val === "Global" || val === "Gloable" ? "purple" : "blue"}>
                                        {val === "Gloable" ? "Global" : val || "-"}
                                    </Tag>
                                )
                            },
                            {
                                title: "Device Count",
                                dataIndex: "deviceCount",
                                align: "center",
                                render: (val: any, record: any) => (
                                    <Badge count={record?.devices?.length || 0} showZero color={token.colorPrimary} />
                                )
                            },
                            {
                                title: "Modified By",
                                dataIndex: "modifiedBy",
                                render: (val: any) => val || "-"
                            },
                            {
                                title: "Modified Date",
                                dataIndex: "modifiedDate",
                                valueType: "dateTime",
                                hideInSearch: true
                            },
                            {
                                title: "Actions",
                                valueType: "option",
                                render: (_, record: any, __, action: any) => {
                                    const items = [
                                        {
                                            key: 'edit',
                                            icon: <EditOutlined />,
                                            label: 'Edit Policy',
                                            onClick: () => action?.openTab?.("edit")
                                        },
                                        {
                                            key: 'test',
                                            icon: <SendOutlined />,
                                            label: 'Test Notification',
                                            onClick: () => {
                                                setSelectedEmployeeCode(record.employeeCode);
                                                setTestModalOpen(true);
                                            }
                                        },
                                        {
                                            type: 'divider'
                                        },
                                        {
                                            key: 'active',
                                            icon: <CheckCircleOutlined />,
                                            label: 'Active',
                                            disabled: record.active,
                                            onClick: () => setRemarkModalOpen({ visible: true, action: "ACTIVE", item: record })
                                        },
                                        {
                                            key: 'inactive',
                                            icon: <StopOutlined />,
                                            label: 'Inactive',
                                            disabled: !record.active,
                                            onClick: () => setRemarkModalOpen({ visible: true, action: "INACTIVE", item: record })
                                        },
                                        {
                                            type: 'divider'
                                        },
                                        {
                                            key: 'remove',
                                            icon: <DeleteOutlined />,
                                            danger: true,
                                            label: 'Remove',
                                            onClick: () => setRemarkModalOpen({ visible: true, action: "REMOVE", item: record })
                                        }
                                    ];

                                    return (
                                        <Dropdown menu={{ items }} trigger={['click']}>
                                            <Button type="text" icon={<EllipsisOutlined />} />
                                        </Dropdown>
                                    );
                                }
                            }
                        ]
                    }
                }}
            />

            <TestNotificationModal
                open={testModalOpen}
                onCancel={() => setTestModalOpen(false)}
                employeeCode={selectedEmployeeCode}
            />
            <RemarkModal
                open={remarkModalOpen.visible}
                onCancel={() => setRemarkModalOpen({ visible: false, action: "", item: undefined })}

                onOk={async (remark) => {
                    await EmployeePoicyAPIService.action({
                        id: remarkModalOpen.item?.id,
                        action: remarkModalOpen.action,
                        remark
                    });
                    message.success(`Action ${remarkModalOpen.action} successful`);
                    setRemarkModalOpen({ visible: false, action: "", item: undefined });
                    refetch();
                }} title={remarkModalOpen.action === "" ? "" : remarkModalOpen.action === "ACTIVE" ? "Activate Policy" : remarkModalOpen.action === "INACTIVE" ? "Deactivate Policy" : "Remove Policy"} />
        </>
    )
};

