import React, { useState } from 'react';
import dayjs from 'dayjs';
import PageWrapper, { PageWrapperContext } from "@/components/PageWrapperV1";
import { Card, Col, Row, Button, Space, Tag, Switch, Modal, message, Statistic, Dropdown, Menu, Form, Input, Select, Badge } from 'antd';
import {
    EditOutlined,
    CopyOutlined,
    DeleteOutlined,
    EyeOutlined,
    CheckCircleOutlined,
    MailOutlined,
    MessageOutlined,
    MobileOutlined,
    BellOutlined,
    AppstoreOutlined,
    SendOutlined,
    ClockCircleOutlined,
    DownOutlined,
    AlertOutlined,
    ThunderboltOutlined,
    ApartmentOutlined,
    LinkOutlined,
    SafetyCertificateOutlined
} from '@ant-design/icons';
import NotificationAPIService, { NotificationTemplate } from './service';
import NotificationForm from './Form';
import NotificationDetail from './Detail';
import { TableViewSearchParams } from '@/components/DataCrud/TableView';
import { useQuery } from '@umijs/max';
import { RemarkModal } from '@/components/RemarkModal';
export default () => {
    const [filter, setFilter] = useState<TableViewSearchParams<any>>({});
    const [actionState, setActionState] = useState<{ visible?: boolean, type: "ACTIVE" | "INACTIVE" | "DELETE", record: NotificationTemplate } | null>(null);

    // Test send modal state
    const [testModalState, setTestModalState] = useState<{
        visible: boolean;
        record?: NotificationTemplate;
    }>({ visible: false });
    const [testLoading, setTestLoading] = useState(false);

    const { data, isFetching, refetch } = useQuery(
        ["notifications", filter],
        () => NotificationAPIService.page(filter),
        {
            refetchOnWindowFocus: false,
        }
    );

    // Dynamic stats computation for the current page
    const items = data?.items || [];
    const totalCount = data?.total || items.length;
    const activeCount = items.filter((it: any) => it.active).length;
    const highPriorityCount = items.filter((it: any) => ['HIGH', 'CRITICAL'].includes((it.priority || '').toUpperCase())).length;

    let pushCount = 0;
    let emailCount = 0;
    let smsCount = 0;
    items.forEach((it: any) => {
        const channels = it.channels || [];
        channels.forEach((ch: any) => {
            // Backend returns NotificationTemplateChannel objects or plain strings
            const code = typeof ch === 'string' ? ch : (ch?.channel || '');
            const upper = code.toUpperCase();
            if (upper === 'PUSH' || upper === 'IN_APP') pushCount++;
            else if (upper === 'EMAIL') emailCount++;
            else if (upper === 'SMS') smsCount++;
        });
    });

    // Channel tags renderer
    const renderChannelTags = (channelsVal: any) => {
        // Normalize: channels may be string[], object[], or comma-separated string
        let channels: string[] = [];
        if (Array.isArray(channelsVal)) {
            channels = channelsVal
                .map((ch: any) => typeof ch === 'string' ? ch : (ch?.channel || ''))
                .filter(Boolean);
        } else if (typeof channelsVal === 'string') {
            channels = channelsVal.split(',').filter(Boolean);
        }
        return (
            <Space wrap size={4}>
                {channels.map((channel: string) => {
                    let color = 'default';
                    let icon = null;
                    const upper = (channel || '').toUpperCase().replace(/[-\s]+/g, '_');
                    switch (upper) {
                        case 'PUSH': color = 'blue'; icon = <MobileOutlined />; break;
                        case 'IN_APP': color = 'cyan'; icon = <BellOutlined />; break;
                        case 'EMAIL': color = 'purple'; icon = <MailOutlined />; break;
                        case 'SMS': color = 'orange'; icon = <MessageOutlined />; break;
                        case 'TELEGRAM': color = 'geekblue'; icon = <SendOutlined />; break;
                        case 'WHATSAPP': color = 'green'; icon = <MessageOutlined />; break;
                        case 'SLACK': color = 'volcano'; icon = <ApartmentOutlined />; break;
                        case 'TEAMS': color = 'indigo'; icon = <ApartmentOutlined />; break;
                        case 'WEBHOOK': color = 'magenta'; icon = <LinkOutlined />; break;
                    }
                    return (
                        <Tag key={channel} color={color} icon={icon} style={{ borderRadius: '3px', margin: 0, fontSize: '11px' }}>
                            {channel}
                        </Tag>
                    );
                })}
            </Space>
        );
    };

    // Priority badge styling helper
    const getPriorityTag = (priority: string) => {
        let color = 'blue';
        const upper = (priority || '').toUpperCase();
        switch (upper) {
            case 'CRITICAL': color = 'red'; break;
            case 'HIGH': color = 'volcano'; break;
            case 'NORMAL': color = 'orange'; break;
            case 'LOW': color = 'lime'; break;
        }
        return <Tag color={color} style={{ borderRadius: '3px', fontWeight: 600, fontSize: '11px' }}>{priority}</Tag>;
    };



    const handleSendTestSubmit = async (values: any) => {
        try {
            setTestLoading(true);
            await NotificationAPIService.sendTestNotification({
                templateId: String(testModalState.record?.id || '1'),
                employeeCode: values.employeeCode,
                channel: values.channel,
                employeeName: 'Phanny Ngoun'
            });
            message.success(`Test notification successfully dispatched to employee "${values.employeeCode}" via ${values.channel}!`);
            setTestModalState({ visible: false });
        } catch (e: any) {
            message.error(e.message || 'Failed to dispatch test notification.');
        } finally {
            setTestLoading(false);
        }
    };

    // Quick Active Status Toggle
