        const upper = (module || '').toUpperCase();
        let color = 'default';
        switch (upper) {
            case 'ATTENDANCE': color = 'green'; break;
            case 'LEAVE': color = 'blue'; break;
            case 'PAYROLL': color = 'magenta'; break;
            case 'MISSION': color = 'cyan'; break;
            case 'APPROVAL': color = 'orange'; break;
            case 'SHIFT': color = 'purple'; break;
            case 'OVERTIME': color = 'gold'; break;
            case 'HOLIDAY': color = 'volcano'; break;
            case 'ANNOUNCEMENT': color = 'geekblue'; break;
            case 'SYSTEM': color = 'red'; break;
        }
        return <Tag color={color} style={{ borderRadius: '3px', fontWeight: 500 }}>{upper}</Tag>;
    };

    return (
        <div style={{ padding: '8px' }}>
            <PageWrapper
                tabRender={(it) => [
                    {
                        action: "add",
