                        panel: ({ onCloseTab }) => (
                            <NotificationForm item={it} mode='duplicate' onClose={() => {
                                onCloseTab();
                                refetch();
                            }} />
                        )
                    },
                    {
                        action: "view",
                        tabKey: `view-${it?.id}`,
                        tabLabel: it?.name ? `View: ${it.name}` : 'Template Details',
                        panel: () => (
                            <NotificationDetail item={it} />
                        )
                    }
                ]}

                listView={{
                    type: "Table",
                    title: "Notification Templates",
                    onRefresh: refetch,
                    statuses: [
                        { option: { label: 'All', value: 'ALL', default: true } },
                        { option: { label: 'Active', value: 'ACTIVE' } },
                        { option: { label: 'Inactive', value: 'INACTIVE' } },
                        { option: { label: 'Attendance', value: 'ATTENDANCE' } },
                        { option: { label: 'Leave', value: 'LEAVE' } },
                        { option: { label: 'Payroll', value: 'PAYROLL' } },
                        { option: { label: 'Mission', value: 'MISSION' } },
                        { option: { label: 'Approval', value: 'APPROVAL' } },
                        { option: { label: 'System', value: 'SYSTEM' } }
                    ],
                    // onExtraFilterRender: () => (
                    //     <Row gutter={[16, 16]} style={{ marginBottom: 16 }}>
                    //         <Col xs={24} sm={12} md={6}>
                    //             <Card style={{ borderRadius: '8px', borderLeft: '4px solid #1890ff', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }} bodyStyle={{ padding: '16px' }}>
                    //                 <Statistic
                    //                     title={<span style={{ fontSize: '13px', color: '#8c8c8c', fontWeight: 500 }}>Total Templates</span>}
                    //                     value={totalCount}
                    //                     prefix={<AppstoreOutlined style={{ color: '#1890ff', marginRight: 4 }} />}
                    //                 />
                    //             </Card>
                    //         </Col>
                    //         <Col xs={24} sm={12} md={6}>
                    //             <Card style={{ borderRadius: '8px', borderLeft: '4px solid #52c41a', boxShadow: '0 2px 8px rgba(0,0,0,0.04)' }} bodyStyle={{ padding: '16px' }}>
                    //                 <Statistic
