                    //                 <div style={{ display: 'flex', flexDirection: 'column' }}>
                    //                     <span style={{ fontSize: '13px', color: '#8c8c8c', fontWeight: 500, marginBottom: 4 }}>Channels Active</span>
                    //                     <Space size={8} style={{ marginTop: 4 }}>
                    //                         <Badge count={pushCount} size="small" overflowCount={9} title="Push Notifications">
                    //                             <Tag color="blue" icon={<MobileOutlined />} style={{ margin: 0, fontSize: '10px' }}>Push</Tag>
                    //                         </Badge>
                    //                         <Badge count={emailCount} size="small" overflowCount={9} title="Email Alerts">
                    //                             <Tag color="purple" icon={<MailOutlined />} style={{ margin: 0, fontSize: '10px' }}>Email</Tag>
                    //                         </Badge>
