                                    let icon = <ThunderboltOutlined />;
                                    let color = 'purple';
                                    if (t === 'SCHEDULE') {
                                        icon = <ClockCircleOutlined />;
                                        color = 'cyan';
                                    } else if (t === 'MANUAL') {
                                        icon = <EyeOutlined />;
                                        color = 'orange';
