                                }
                            },
                            {
                                title: "Duplicate Strategy",
                                dataIndex: "duplicateStrategy",
                                key: "duplicateStrategy",
                                render: (strategy: any, record: any) => {
                                    if (!strategy || strategy === 'NONE') return <span style={{ color: '#bfbfbf' }}>None</span>;
                                    const windowText = strategy === 'TIME_WINDOW' && record.duplicateWindowMinutes
                                        ? ` (${record.duplicateWindowMinutes}m)`
                                        : '';
                                    return (
                                        <Tag color="geekblue" icon={<SafetyCertificateOutlined />} style={{ borderRadius: '3px', fontSize: '11px' }}>
                                            {strategy}{windowText}
                                        </Tag>
                                    );
                                }
                            },
                            {
                                title: "Channels",
                                dataIndex: "channels",
                                key: "channels",
                                hideInSearch: true,
                                render: (channels: any) => renderChannelTags(channels)
                            },
                            {
                                title: "Priority",
                                dataIndex: "priority",
                                key: "priority",
                                render: (p: any) => getPriorityTag(p)
                            },
                            {
                                title: "Delay / Schedule",
                                key: "delay",
                                hideInSearch: true,
                                render: (_, record: any) => {
                                    if (record.triggerType === 'SCHEDULE' && record.delayDirection === 'SPECIFIC_TIME' && record.scheduleTime) {
                                        const parsedTime = dayjs(record.scheduleTime, 'HH:mm:ss');
                                        return `At ${parsedTime.isValid() ? parsedTime.format('h:mm A') : record.scheduleTime}`;
                                    }
                                    if (record.delayMinutes && record.delayMinutes > 0) {
                                        return `${record.delayMinutes} mins delay`;
                                    }
                                    return 'Immediate';
                                }
                            },
                            {
                                title: "Status",
                                dataIndex: "active",
                                key: "active",
                                render: (active: boolean, record: any) => (
                                    <Switch
                                        checked={active}
                                        size="small"
                                        onChange={(checked) => handleToggleStatus(record, checked)}
                                    />
                                )
                            },
                            {
                                title: "Action",
                                key: "actions",
                                hideInSearch: true,
                                width: 90,
                                render: (_, record: any) => (
                                    <PageWrapperContext.Consumer>
                                        {({ onAddTab, tabRender }) => (
                                            <Dropdown
                                                overlay={
                                                    <Menu size="small">
                                                        <Menu.Item
                                                            icon={<EditOutlined style={{ color: '#1890ff' }} />}
                                                            onClick={() => {
                                                                const config = tabRender?.(record).find(t => t.action === 'edit');
                                                                if (config) onAddTab?.(record, config, `edit-${record.id}`);
                                                            }}
                                                        >
                                                            Edit Properties
                                                        </Menu.Item>
                                                        <Menu.Item
                                                            icon={<CopyOutlined style={{ color: '#52c41a' }} />}
                                                            onClick={() => {
                                                                const config = tabRender?.(record).find(t => t.action === 'duplicate');
                                                                if (config) onAddTab?.(record, config, `duplicate-${record.id}`);
                                                            }}
                                                        >
                                                            Duplicate Template
                                                        </Menu.Item>
                                                        <Menu.Item
                                                            icon={<EyeOutlined style={{ color: '#722ed1' }} />}
                                                            onClick={() => {
                                                                const config = tabRender?.(record).find(t => t.action === 'view');
                                                                if (config) onAddTab?.(record, config, `view-${record.id}`);
                                                            }}
                                                        >
                                                            Preview Details
                                                        </Menu.Item>
                                                        <Menu.Item
                                                            icon={<SendOutlined style={{ color: '#fa8c16' }} />}
                                                            onClick={() => setTestModalState({ visible: true, record })}
                                                        >
                                                            Send Test Notification
                                                        </Menu.Item>
                                                        <Menu.Divider />
                                                        <Menu.Item
                                                            danger
                                                            icon={<DeleteOutlined />}
                                                            onClick={() => setActionState({ visible: true, type: "DELETE", record })}
                                                        >
                                                            Delete Template
                                                        </Menu.Item>
                                                    </Menu>
                                                }
                                                trigger={['click']}
                                            >
                                                <Button size="small" type="link">
                                                    Actions <DownOutlined style={{ fontSize: '10px' }} />
                                                </Button>
                                            </Dropdown>
                                        )}
                                    </PageWrapperContext.Consumer>
                                )
                            }
                        ]
                    }
                }}
            />



            {/* Test Send Modal */}
            <Modal
                title={`Send Test Dispatch: ${testModalState.record?.name || ''}`}
                visible={testModalState.visible}
                onCancel={() => setTestModalState({ visible: false })}
                footer={null}
                destroyOnClose
            >
                <Form layout="vertical" onFinish={handleSendTestSubmit} initialValues={{ employeeCode: 'EMP-0042', channel: 'PUSH' }}>
                    <Form.Item
                        name="employeeCode"
                        label="Target Employee Code"
                        rules={[{ required: true, message: 'Please input code' }]}
                    >
                        <Input placeholder="e.g. EMP-0042" />
                    </Form.Item>
                    <Form.Item
                        name="channel"
                        label="Delivery Channel Medium"
                        rules={[{ required: true }]}
                    >
                        <Select options={['PUSH', 'IN_APP', 'EMAIL', 'SMS', 'TELEGRAM'].map(c => ({ label: c, value: c }))} />
                    </Form.Item>
                    <Form.Item style={{ textAlign: 'right', marginBottom: 0 }}>
                        <Space>
                            <Button onClick={() => setTestModalState({ visible: false })}>Cancel</Button>
                            <Button type="primary" htmlType="submit" icon={<SendOutlined />} loading={testLoading}>
                                Dispatch Test
                            </Button>
                        </Space>
                    </Form.Item>
                </Form>
            </Modal>

            {/* Reason Remark Modal */}
            <RemarkModal
                open={!!actionState?.visible}
                title={"Reason for " + actionState?.type?.toLowerCase() + " " + actionState?.record?.name}
                onCancel={() => {
                    setActionState(null);
                }}
                onOk={async (remark) => {
                    await NotificationAPIService.action({ id: Number(actionState?.record?.id ?? 0), type: actionState?.type ?? 'DELETE', remark: remark });
                    setActionState(null);
                    message.success("Configuration updated successfully!");
                    refetch?.();
                }}
            />
        </div>
    );
};

