import React, { useMemo } from "react"
import { Space, Button, Switch, Popconfirm, Tag, message, Card, Row, Col, Statistic } from "antd"
import { EditOutlined, PlayCircleOutlined, DeleteOutlined, FileTextOutlined, ProjectOutlined, CheckCircleOutlined, InfoCircleOutlined } from "@ant-design/icons"
import PageWrapper from "@/components/PageWrapperV1"
import ReportForm from "./Form"
import ReportPreview from "./ReportPreview"
import { ReportService, Report } from "./service"
import { useQuery } from "@umijs/max"
import { ReportModalButton } from "./ReportModalButton"

const ReportList: React.FC = () => {
  const { data: reports, refetch } = useQuery({
    queryKey: ["reports_list"],
    queryFn: async () => ReportService.getReports(),
    refetchOnWindowFocus: false
  });

  const handleDelete = (id: string) => {
    ReportService.deleteReport(id);
    message.success("Report deleted successfully");
    refetch();
  };

  const handleToggleActive = (id: string, checked: boolean) => {
    ReportService.toggleReportActive(id, checked);
    message.success(`Report ${checked ? 'enabled' : 'disabled'} successfully`);
    refetch();
  };

  return (
    <div style={{ padding: '0 4px' }}>


      <PageWrapper<Report, any, any>
        tabRender={(it) => [
          {
            tabLabel: "New Template",
            action: "add",
            panel: (prop) => (
              <ReportForm
                action="add"
                onClose={() => {
                  prop.onCloseTab();
                  refetch();
                }}
              />
            )
          },
          {
            tabLabel: `Edit: ${it?.name || 'Template'}`,
            action: "edit",
            tabKey: `edit-${it?.id}`,
            panel: (prop) => (
              <ReportForm
                action="edit"
                reportId={it?.id}
                onClose={() => {
                  prop.onCloseTab();
                  refetch();
                }}
              />
            )
          },
          {
            tabLabel: `Run: ${it?.name || 'Report'}`,
            action: "run",
            tabKey: `run-${it?.id}`,
            panel: () => (
              <ReportPreview reportId={it?.id!} />
            )
          }
        ]}

        listView={{
          type: "Table",
          onRefresh: () => refetch(),
          actionButtons: [
            <ReportModalButton reportId={"EMP_ATTENDANCE"} buttonType="text" />
          ],
          props: {
            dataSource: reports || [],
            columns: [
              {
                title: "Report Code",
                dataIndex: "code",
                width: 140,
                render: (code, record, _, action: any) => (
                  <a onClick={() => action.openTab("run")} style={{ fontWeight: 600, color: '#3b82f6' }}>
                    {code}
                  </a>
                )
              },
              {
                title: "Report Name",
                dataIndex: "name",
                width: 220,
                actionProps: (record) => ({
                  label: record.name,
                  type: "run"
                })
              },
              {
                title: "Description",
                dataIndex: "description",
                ellipsis: true,
                render: (text) => <span style={{ color: '#64748b' }}>{text || 'No description'}</span>
              },
              {
                title: "API Endpoint URL",
                dataIndex: "api_url",
                width: 250,
                render: (url, record) => (
                  <span style={{ display: 'flex', alignItems: 'center' }}>
                    <Tag
                      color={record.method === 'POST' ? 'geekblue' : 'green'}
                      style={{
                        borderRadius: '4px',
                        fontWeight: 600,
                        fontSize: '10px',
                        padding: '1px 6px',
                        border: 'none',
                        marginRight: 8
                      }}
                    >
                      {record.method}
                    </Tag>
                    <code style={{ fontSize: '11px', background: '#f1f5f9', padding: '2px 6px', borderRadius: '4px', color: '#334155' }}>
                      {url}
                    </code>
                  </span>
                )
              },
              {
                title: "Format",
                dataIndex: "download_type",
                width: 180,
                render: (formats: string[]) => (
                  <Space size={4} wrap>
                    {formats?.map(f => {
                      let color = 'default';
                      if (f === 'EXCEL') color = 'success';
                      if (f === 'CSV') color = 'warning';
                      if (f === 'PDF') color = 'error';
                      return (
                        <Tag
                          key={f}
                          color={color}
                          bordered={false}
                          style={{
                            fontSize: '10px',
                            fontWeight: 600,
                            borderRadius: '4px',
                            padding: '1px 6px'
                          }}
                        >
                          {f}
                        </Tag>
                      );
                    })}
                  </Space>
                )
              },
              {
                title: "Active",
                dataIndex: "active",
                width: 80,
                render: (active, record) => (
                  <Switch
                    checked={active}
                    size="small"
                    onChange={(checked) => handleToggleActive(record.id, checked)}
                    style={{ background: active ? '#10b981' : undefined }}
                  />
                )
              },
              {
                title: "Actions",
                dataIndex: "actions",
                align: "center",
                width: 140,
                render: (_, record, __, action: any) => {
                  return (
                    <Space>
                      <Button
                        size="small"
                        icon={<PlayCircleOutlined />}
                        type="primary"
                        ghost
                        onClick={() => action.openTab("run")}
                        title="Run Report"
                        className="action-btn-hover"
                        style={{ borderColor: '#3b82f6', color: '#3b82f6' }}
                      />
                      <Button
                        size="small"
                        icon={<EditOutlined />}
                        onClick={() => action.openTab("edit")}
                        title="Edit Report"
                        className="action-btn-hover"
                      />
                      <Popconfirm
                        title="Delete this template?"
                        description="Are you sure you want to delete this template?"
                        onConfirm={() => handleDelete(record.id)}
                        okText="Delete"
                        cancelText="Cancel"
                        okButtonProps={{ danger: true }}
                      >
                        <Button
                          size="small"
                          danger
                          icon={<DeleteOutlined />}
                          title="Delete Report"
                          className="action-btn-hover"
                        />
                      </Popconfirm>
                    </Space>
                  )
                }
              }
            ]
          }
        }}
      />
    </div>
  )
}

export default ReportList

